export interface OperationWithAssignment extends OperationResponse {
  assigned: boolean;
  rolOperationId?: number;
}

export function getRolOperationColumns(
  onToggle: (op: OperationWithAssignment) => void,
): TableColumnWithFilters<OperationWithAssignment>[] {
  return [
    {
      id: "id",
      name: "ID",
      selector: (data) => data.id ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "name",
      name: "Nombre",
      selector: (data) => data.name ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "path",
      name: "Ruta",
      selector: (data) => data.path ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "httpMethod",
      name: "M├®todo HTTP",
      selector: (data) =>
        (data as OperationWithAssignment & { httpMethod?: string })
          .httpMethod ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "assigned",
      name: "Estado",
      center: true,
      cell: (data) =>
        data.assigned ? (
          <span className="px-2 py-1 rounded text-xs font-semibold bg-green-100 text-green-800">
            Asignado
          </span>
        ) : (
          <span className="px-2 py-1 rounded text-xs font-semibold bg-gray-100 text-gray-600">
            No asignado
          </span>
        ),
    },
    {
      id: "actions",
      name: "Acciones",
      center: true,
      button: true,
      cell: (data) => (
        <Button
          size="sm"
          variant={data.assigned ? "danger" : "primary"}
          onClick={() => onToggle(data)}
        >
          {data.assigned ? "Quitar" : "Asignar"}
        </Button>
      ),
    },
  ];
}

import { useCallback, useState } from "react";
