            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.name || ""}
            />
            {errors?.name ? (
              <FieldError>{errors.name as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.phone}
            name="phone"
            onChange={handleTextChange("phone")}
          >
            <Label className="font-bold">Tel├®fono (8 d├¡gitos)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.phone || ""}
            />
            {errors?.phone ? (
              <FieldError>{errors.phone as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.address}
            name="address"
            onChange={handleTextChange("address")}
          >
            <Label className="font-bold">Direcci├│n</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.address || ""}
            />
            {errors?.address ? (
              <FieldError>{errors.address as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.description}
            name="description"
            onChange={handleTextChange("description")}
          >
            <Label className="font-bold">Descripci├│n</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.description || ""}
            />
            {errors?.description ? (
              <FieldError>{errors.description as string}</FieldError>
            ) : null}
          </TextField>
          <OptionsSelect
            isRequired
            defaultValue={
              form.state !== null && form.state !== undefined
                ? {
                    label: form.state === 1 ? "Activo" : "Inactivo",
                    value: String(form.state),
                  }
                : { label: "Activo", value: "1" }
            }
            errorMessage={errors?.state as string}
            isInvalid={!!errors?.state}
            label="Estado"
            name="state"
            options={[
              { label: "Activo", value: "1" },
              { label: "Inactivo", value: "0" },
            ]}
            placeholder="Seleccione un estado"
            onChange={handleStateChange}
          />
        </div>
        <div className="flex gap-4 justify-end mt-4">
          <AsyncButton
            className="font-bold"
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() => navigate("/branch")}
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            className="font-bold"
            isLoading={loading}
            loadingText={isEditing ? "Actualizando..." : "Creando..."}
            size="lg"
            type="submit"
            variant="primary"
          >
            {isEditing ? "Actualizar" : "Crear"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { Form } from "@heroui/react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  createDispense,
  createDispenseItem,
} from "../../services/dispenseService";
import {
  getMedicineInventory,
  partialUpdateMedicineInventory,
} from "../../services/medicineService";
import { getPrescriptionItems } from "../../services/prescriptionService";
import type { MedicineInventoryResponse } from "../../types/MedicineInventoryResponse";
import type { PrescriptionItemResponse } from "../../types/PrescriptionItemResponse";
import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { LowStockAlert } from "../shared/LowStockAlert";

export interface DispenseFormProps {
  readonly prescriptionId: number;
  readonly prescriptionDate: string;
  readonly onSuccess?: (dispenseId: number) => void;
}

interface DispenseItemRow {
  prescriptionItem: PrescriptionItemResponse;
  inventory: MedicineInventoryResponse | null;
  quantity: number;
  unitPrice: number;
  wasSubstituted: boolean;
  substitutionReason: string;
}

const DEFAULT_BRANCH_ID = 1;

const formatCurrency = (amount: number): string => `Q ${amount.toFixed(2)}`;

export function DispenseForm({ prescriptionId, onSuccess }: DispenseFormProps) {
  const [rows, setRows] = useState<DispenseItemRow[]>([]);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitSuccess, setSubmitSuccess] = useState<string | null>(null);

  // ÔöÇÔöÇ Fetch prescription items ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const { data: itemsData, isLoading: itemsLoading } = useQuery({
    queryKey: ["prescriptionItems", prescriptionId],
    queryFn: () =>
      getPrescriptionItems({
        filters: `PrescriptionId:eq:${prescriptionId}`,
        pageSize: 100,
        pageNumber: 1,
        include: "",
        includeTotal: false,
      }),
    enabled: !!prescriptionId,
  });

  // ÔöÇÔöÇ Fetch inventory for each medicine name ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const prescriptionItems = itemsData?.data ?? [];

  const { data: inventoryData } = useQuery({
    queryKey: ["dispenseInventory", prescriptionId],
    queryFn: async () => {
      if (prescriptionItems.length === 0) return [];
      const results: MedicineInventoryResponse[] = [];
      for (const item of prescriptionItems) {
        const res = await getMedicineInventory({
          filters: `Medicine.Name:like:${item.medicineName},BranchId:eq:${DEFAULT_BRANCH_ID}`,
          include: "Medicine",
          pageSize: 1,
          pageNumber: 1,
          includeTotal: false,
        });
        if (res.data && res.data.length > 0) {
          results.push(res.data[0]);
        } else {
          // Push a sentinel so index alignment is preserved
          results.push(null as unknown as MedicineInventoryResponse);
        }
      }
      return results;
    },
    enabled: prescriptionItems.length > 0,
  });

  // ÔöÇÔöÇ Build rows once both datasets are available ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  useEffect(() => {
    if (prescriptionItems.length === 0) return;
    const inv = inventoryData ?? [];
    setRows(
      prescriptionItems.map((item, idx) => {
        const inventory = inv[idx] ?? null;
        return {
          prescriptionItem: item,
          inventory,
          quantity: 1,
          unitPrice: inventory?.medicine?.defaultPrice ?? 0,
          wasSubstituted: false,
          substitutionReason: "",
        };
      }),
    );
  }, [prescriptionItems, inventoryData]);

  // ÔöÇÔöÇ Row field handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const updateRow = useCallback(
    (
      idx: number,
      patch: Partial<Omit<DispenseItemRow, "prescriptionItem" | "inventory">>,
    ) => {
      setRows((prev) =>
        prev.map((row, i) => (i === idx ? { ...row, ...patch } : row)),
      );
    },
    [],
  );

  // ÔöÇÔöÇ Computed total ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const total = useMemo(
    () => rows.reduce((sum, row) => sum + row.quantity * row.unitPrice, 0),
    [rows],
  );

  // ÔöÇÔöÇ Mutations ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const { mutateAsync: doCreateDispense, isPending } = useMutation({
    mutationFn: createDispense,
  });

  // ÔöÇÔöÇ Submit ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const handleSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();
      setSubmitError(null);
      setSubmitSuccess(null);

      // Validate substitution reasons
      for (const row of rows) {
        if (row.wasSubstituted && !row.substitutionReason.trim()) {
          setSubmitError(
            `La raz├│n de sustituci├│n es requerida para "${row.prescriptionItem.medicineName}".`,
          );
          return;
        }
      }

      // Validate stock sufficiency
      for (const row of rows) {
        if (row.inventory && row.quantity > row.inventory.currentStock) {
          setSubmitError(
            `Stock insuficiente para "${row.prescriptionItem.medicineName}". Stock actual: ${row.inventory.currentStock}. Cantidad solicitada: ${row.quantity}.`,
          );
          return;
        }
      }

      // 1. Create dispense header
      const dispenseRes = await doCreateDispense({
        prescriptionId,
        totalAmount: Math.round(total * 100) / 100,
        state: 1,
      });

      if (!dispenseRes.success) {
        setSubmitError(dispenseRes.message ?? "Error al crear el despacho.");
        return;
      }

      const dispenseId = dispenseRes.data.id;

      // 2. Create each dispense item + update inventory
      for (const row of rows) {
        const medicineName = row.prescriptionItem.medicineName;

        const itemRes = await createDispenseItem({
          dispenseId,
          medicineId: row.inventory?.medicineId ?? null,
          quantity: row.quantity,
          unitPrice: row.unitPrice,
          wasSubstituted: row.wasSubstituted,
          substitutionReason: row.wasSubstituted
            ? row.substitutionReason
            : null,
          originalMedicineName: medicineName,
          dispensedMedicineName: row.wasSubstituted
            ? row.substitutionReason.split(":")[0]?.trim() || medicineName
            : medicineName,
          state: 1,
        });

        if (!itemRes.success) {
          setSubmitError(
            `Error al registrar ├¡tem "${medicineName}": ${itemRes.message}`,
          );
          return;
        }

        // 3. Update inventory stock
        if (row.inventory) {
          const newStock = row.inventory.currentStock - row.quantity;
          await partialUpdateMedicineInventory({
            id: row.inventory.id,
            currentStock: newStock,
          });
        }
      }

      const totalFormatted = formatCurrency(Math.round(total * 100) / 100);
      const itemCount = rows.length;
      setSubmitSuccess(
        `Despacho registrado exitosamente. ${itemCount} medicamento(s) despachado(s). Total: ${totalFormatted}.`,
      );
      onSuccess?.(dispenseId);
    },
    [rows, total, prescriptionId, doCreateDispense, onSuccess],
  );

  if (itemsLoading) {
    return (
      <div className="flex justify-center items-center py-12">
        <span className="text-gray-500">Cargando ├¡tems de la receta...</span>
      </div>
    );
  }

  if (prescriptionItems.length === 0) {
    return (
      <div className="max-w-3xl mx-auto p-6">
        <p className="text-center text-gray-500">
          Esta receta no tiene ├¡tems registrados.
        </p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        Despachar Receta #{prescriptionId}
      </h1>

      {submitError ? <Response message={submitError} type={false} /> : null}
      {submitSuccess ? <Response type message={submitSuccess} /> : null}

      {/* Low-stock alerts */}
      <div className="flex flex-col gap-2 mb-4">
        {rows.map((row) =>
          row.inventory &&
          row.inventory.currentStock <=
            (row.inventory.medicine?.minimumStock ?? 0) ? (
            <LowStockAlert
              key={row.prescriptionItem.id}
              currentStock={row.inventory.currentStock}
              medicineName={row.prescriptionItem.medicineName}
              minimumStock={row.inventory.medicine?.minimumStock ?? 0}
            />
          ) : null,
        )}
      </div>

      <Form className="flex flex-col gap-4" onSubmit={handleSubmit}>
        {/* Items table */}
        <div className="overflow-x-auto rounded-lg border">
          <table className="w-full text-sm">
            <thead className="bg-gray-50 dark:bg-gray-800">
              <tr>
                <th className="px-4 py-3 text-left font-semibold">
                  Medicamento
                </th>
                <th className="px-4 py-3 text-center font-semibold w-28">
                  Cantidad
                </th>
                <th className="px-4 py-3 text-center font-semibold w-32">
                  Precio Unit.
                </th>
                <th className="px-4 py-3 text-center font-semibold w-28">
                  Subtotal
                </th>
                <th className="px-4 py-3 text-center font-semibold w-28">
                  Sustituci├│n
                </th>
                <th className="px-4 py-3 text-left font-semibold">
                  Raz├│n de Sustituci├│n
                </th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {rows.map((row, idx) => (
                <tr
                  key={row.prescriptionItem.id}
                  className="hover:bg-gray-50 dark:hover:bg-gray-800/50"
                >
                  {/* Medicine name */}
                  <td className="px-4 py-3 font-medium">
                    {row.prescriptionItem.medicineName}
                    {row.prescriptionItem.dosage ? (
                      <span className="block text-xs text-gray-500">
                        Dosis: {row.prescriptionItem.dosage}
                      </span>
                    ) : null}
                    {row.inventory === null && (
                      <span className="block text-xs text-orange-500">
                        ÔÜá´©Å Sin inventario registrado
                      </span>
                    )}
                  </td>

                  {/* Quantity */}
                  <td className="px-4 py-3">
                    <input
                      className="w-full px-2 py-1 border rounded-md text-center"
                      min={1}
                      type="number"
                      value={row.quantity}
                      onChange={(e) =>
                        updateRow(idx, {
                          quantity: Math.max(1, Number(e.target.value) || 1),
                        })
                      }
                    />
                  </td>

                  {/* Unit price */}
                  <td className="px-4 py-3 text-center">
                    {!row.unitPrice ? (
                      <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-xs font-semibold bg-yellow-100 text-yellow-800">
                        <i className="bi bi-exclamation-triangle" /> Precio no
                        configurado
                      </span>
                    ) : (
                      <span className="text-sm font-semibold text-green-700 dark:text-green-400">
                        {formatCurrency(row.unitPrice)}
                      </span>
                    )}
                  </td>

                  {/* Subtotal */}
                  <td className="px-4 py-3 text-center font-semibold">
                    {formatCurrency(row.quantity * row.unitPrice)}
                  </td>

                  {/* Was substituted checkbox */}
                  <td className="px-4 py-3 text-center">
                    <input
                      checked={row.wasSubstituted}
                      className="w-4 h-4 accent-blue-600"
                      id={`sub-${idx}`}
                      type="checkbox"
                      onChange={(e) =>
                        updateRow(idx, {
                          wasSubstituted: e.target.checked,
                          substitutionReason: e.target.checked
                            ? row.substitutionReason
                            : "",
                        })
                      }
                    />
                  </td>

                  {/* Substitution reason */}
                  <td className="px-4 py-3">
                    {row.wasSubstituted ? (
                      <input
                        required
                        className="w-full px-2 py-1 border rounded-md"
                        placeholder="Raz├│n de sustituci├│n *"
                        type="text"
                        value={row.substitutionReason}
                        onChange={(e) =>
                          updateRow(idx, { substitutionReason: e.target.value })
                        }
                      />
                    ) : (
                      <span className="text-gray-400 text-xs">ÔÇö</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Total */}
        <div className="flex justify-end items-center gap-4 mt-2 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-700">
          <span className="text-lg font-bold">Total del Despacho:</span>
          <span className="text-2xl font-bold text-blue-800 dark:text-blue-300">
            {formatCurrency(total)}
          </span>
        </div>

        {/* Submit */}
        <div className="flex justify-end mt-2">
          <AsyncButton
            className="font-bold"
            isLoading={isPending}
            loadingText="Procesando despacho..."
            size="lg"
            type="submit"
            variant="primary"
          >
            <i className="bi bi-bag-check mr-2" /> Confirmar Despacho
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useMutation } from "@tanstack/react-query";
import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  type ChangeEvent,
} from "react";
import { useNavigate } from "react-router";
import type { MultiValue, SingleValue } from "react-select";

import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { CatalogueSelect } from "../select/CatalogueSelect";
import { LowStockAlert } from "../shared/LowStockAlert";

import { getBranches } from "../../services/branchService";
import { createInventoryMovement } from "../../services/inventoryMovementService";
import {
  getMedicineInventory,
  getMedicines,
} from "../../services/medicineService";

import type { BranchResponse } from "../../types/BranchResponse";
import type { InventoryMovementRequest } from "../../types/InventoryMovementResponse";
import { MovementTypeLabels } from "../../types/InventoryMovementResponse";
import type { MedicineInventoryResponse } from "../../types/MedicineInventoryResponse";
import type { MedicineResponse } from "../../types/MedicineResponse";

import { useAuth } from "../../hooks/useAuth";
import { validateInventoryMovement } from "../../validations/inventoryMovementValidation";

// ÔöÇÔöÇ Movement type helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/** Movement types available for manual CRUD (excludes Despacho=6 which is automatic) */
const MANUAL_MOVEMENT_TYPES = [0, 1, 2, 3, 4, 5] as const;

/** Exit movement types that reduce stock */
const EXIT_TYPES = new Set([2, 3, 5]);

/** Whether a movement type is an entry (increases stock) */
const isEntryType = (type: number): boolean => [0, 1, 4].includes(type);

/** Field visibility configuration per movement type */
const FIELD_CONFIG: Record<
  number,
  {
    unitCost: boolean;
    referenceNumber: boolean;
    notes: boolean;
    notesLabel: string;
    referenceLabel: string;
  }
> = {
  0: {
    unitCost: true,
    referenceNumber: true,
    notes: true,
    notesLabel: "Notas (opcional)",
    referenceLabel: "N├║mero de Factura",
  },
  1: {
    unitCost: false,
    referenceNumber: true,
    notes: true,
    notesLabel: "Motivo de Devoluci├│n",
    referenceLabel: "Referencia de Devoluci├│n",
  },
  2: {
    unitCost: false,
    referenceNumber: true,
    notes: false,
    notesLabel: "",
    referenceLabel: "Referencia de Venta",
  },
  3: {
    unitCost: false,
    referenceNumber: true,
    notes: true,
    notesLabel: "Motivo del Reclamo",
    referenceLabel: "Referencia del Reclamo",
  },
  4: {
    unitCost: false,
    referenceNumber: false,
    notes: true,
    notesLabel: "Justificaci├│n (m├¡n. 10 caracteres) *",
    referenceLabel: "",
  },
  5: {
    unitCost: false,
    referenceNumber: false,
    notes: true,
    notesLabel: "Justificaci├│n (m├¡n. 10 caracteres) *",
    referenceLabel: "",
  },
};

// ÔöÇÔöÇ Reference type mapping ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
const REFERENCE_TYPE_MAP: Record<number, string> = {
  0: "Factura",
  1: "Devoluci├│n",
  2: "Venta",
  3: "Reclamo",
  4: "Ajuste",
  5: "Ajuste",
};

// ÔöÇÔöÇ Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export function InventoryMovementForm() {
  const navigate = useNavigate();
  const { userId } = useAuth();

  // ÔöÇÔöÇ Form state ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const [movementType, setMovementType] = useState<number | null>(null);
  const [medicineId, setMedicineId] = useState<number | null>(null);
  const [branchId, setBranchId] = useState<number | null>(null);
  const [quantity, setQuantity] = useState<string>("");
  const [unitCost, setUnitCost] = useState<string>("");
  const [referenceNumber, setReferenceNumber] = useState<string>("");
  const [notes, setNotes] = useState<string>("");

  // ÔöÇÔöÇ Lookup state ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const [selectedMedicine, setSelectedMedicine] =
    useState<MedicineResponse | null>(null);
  const [inventory, setInventory] = useState<MedicineInventoryResponse | null>(
    null,
  );
  const [inventoryLoading, setInventoryLoading] = useState(false);

  // ÔöÇÔöÇ UI state ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitSuccess, setSubmitSuccess] = useState<string | null>(null);

  // ÔöÇÔöÇ Medicine cache ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const medicineCacheRef = useState<Map<number, MedicineResponse>>(
    () => new Map(),
  )[0];

  // ÔöÇÔöÇ Field config for current type ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const fieldConfig = movementType !== null ? FIELD_CONFIG[movementType] : null;

  // ÔöÇÔöÇ Fetch inventory when medicine + branch are selected ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  useEffect(() => {
    if (!medicineId || !branchId) {
      setInventory(null);
      return;
    }

    let cancelled = false;
    setInventoryLoading(true);

    getMedicineInventory({
      filters: `MedicineId:eq:${medicineId},BranchId:eq:${branchId}`,
      include: "Medicine",
      pageSize: 1,
      pageNumber: 1,
      includeTotal: false,
    })
      .then((res) => {
        if (cancelled) return;
        if (res.success && res.data && res.data.length > 0) {
          setInventory(res.data[0]);
        } else {
          setInventory(null);
        }
      })
      .finally(() => {
        if (!cancelled) setInventoryLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [medicineId, branchId]);

  // ÔöÇÔöÇ Projected stock after operation ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const projectedStock = useMemo(() => {
    if (!inventory || !quantity) return null;
    const qty = Number(quantity);
    if (isNaN(qty) || qty <= 0) return null;
    if (movementType === null) return null;

    return isEntryType(movementType)
      ? inventory.currentStock + qty
      : inventory.currentStock - qty;
  }, [inventory, quantity, movementType]);

  // ÔöÇÔöÇ Low stock warning ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const showLowStockAlert = useMemo(() => {
    if (movementType === null || !EXIT_TYPES.has(movementType)) return false;
    if (projectedStock === null || !selectedMedicine) return false;
    return projectedStock < selectedMedicine.minimumStock;
  }, [movementType, projectedStock, selectedMedicine]);

  // ÔöÇÔöÇ Selectors for CatalogueSelect ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const selectorMedicine = useCallback(
    (item: MedicineResponse) => {
      medicineCacheRef.set(item.id, item);
      return { label: `${item.name} (${item.unit})`, value: String(item.id) };
    },
    [medicineCacheRef],
  );

  const selectorBranch = useCallback(
    (item: BranchResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  // ÔöÇÔöÇ Handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const handleMedicineChange = useCallback(
    (
      opt:
        | SingleValue<{ label: string; value: string }>
        | MultiValue<{ label: string; value: string }>
        | null,
    ) => {
      if (opt && !Array.isArray(opt) && "value" in opt) {
        const id = Number(opt.value);
        setMedicineId(id);
        setSelectedMedicine(medicineCacheRef.get(id) ?? null);
      } else {
        setMedicineId(null);
        setSelectedMedicine(null);
        setInventory(null);
      }
    },
    [medicineCacheRef],
  );

  const handleBranchChange = useCallback(
    (
      opt:
        | SingleValue<{ label: string; value: string }>
        | MultiValue<{ label: string; value: string }>
        | null,
    ) => {
      if (opt && !Array.isArray(opt) && "value" in opt) {
        setBranchId(Number(opt.value));
      } else {
        setBranchId(null);
      }
    },
    [],
  );

  const handleMovementTypeChange = useCallback(
    (e: ChangeEvent<HTMLSelectElement>) => {
      const val = e.target.value;
      setMovementType(val === "" ? null : Number(val));
      // Reset type-specific fields
      setUnitCost("");
      setReferenceNumber("");
      setNotes("");
      setErrors({});
      setSubmitError(null);
    },
    [],
  );

  // ÔöÇÔöÇ Mutation ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const { mutateAsync: doCreate, isPending } = useMutation({
    mutationFn: createInventoryMovement,
  });

  // ÔöÇÔöÇ Submit ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const handleSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();
      setSubmitError(null);
      setSubmitSuccess(null);

      // Build form data for validation
      const formData = {
        movementType: movementType ?? "",
        medicineId: medicineId ?? "",
        branchId: branchId ?? "",
        quantity,
        unitCost,
        notes,
      };

      const validationErrors = validateInventoryMovement(formData);
      setErrors(validationErrors as Record<string, string>);

      if (Object.keys(validationErrors).length > 0) {
        setSubmitError("Corrija los errores del formulario.");
        return;
      }

      // Ensure inventory record exists
      if (!inventory) {
        setSubmitError(
          "No se encontr├│ registro de inventario para el medicamento y sucursal seleccionados. Verifique que exista un registro de inventario.",
        );
        return;
      }

      // CU-13 FA03: Stock insuficiente para salidas
      if (
        EXIT_TYPES.has(movementType!) &&
        Number(quantity) > inventory.currentStock
      ) {
        setSubmitError(
          `Stock insuficiente. Stock actual: ${inventory.currentStock}. No se puede registrar una salida de ${quantity} unidades.`,
        );
        return;
      }

      const request: InventoryMovementRequest = {
        medicineInventoryId: inventory.id,
        medicineId: medicineId!,
        branchId: branchId!,
        movementType: movementType!,
        quantity: Number(quantity),
        unitCost: movementType === 0 ? Number(unitCost) : 0,
        referenceNumber: referenceNumber.trim() || null,
        referenceType: REFERENCE_TYPE_MAP[movementType!] ?? null,
        notes: notes.trim() || null,
        userId: userId ?? null,
        state: 1,
      };

      const response = await doCreate(request);

      if (!response.success) {
        setSubmitError(response.message ?? "Error al registrar el movimiento.");
        return;
      }

      const medicineName = selectedMedicine?.name ?? "Medicamento";
      const typeLabel = MovementTypeLabels[movementType!]?.label ?? "";
      const newStock = isEntryType(movementType!)
        ? inventory.currentStock + Number(quantity)
        : inventory.currentStock - Number(quantity);
      setSubmitSuccess(
        `Movimiento registrado exitosamente. Medicamento: ${medicineName}. Tipo: ${typeLabel}. Cantidad: ${quantity}. Stock actualizado: ${newStock}.`,
      );
      // Reset form
      setMovementType(null);
      setMedicineId(null);
      setBranchId(null);
      setSelectedMedicine(null);
      setInventory(null);
      setQuantity("");
      setUnitCost("");
      setReferenceNumber("");
      setNotes("");
      setErrors({});
    },
    [
      movementType,
      medicineId,
      branchId,
      quantity,
      unitCost,
      referenceNumber,
      notes,
      inventory,
      userId,
      doCreate,
    ],
  );

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        <i className="bi bi-journal-plus mr-2" />
        Registrar Movimiento de Inventario
      </h1>

      {submitError ? <Response message={submitError} type={false} /> : null}
      {submitSuccess ? <Response type message={submitSuccess} /> : null}

      {/* Low stock alert */}
      {showLowStockAlert && selectedMedicine && projectedStock !== null ? (
        <div className="mb-4">
          <LowStockAlert
            currentStock={projectedStock}
            medicineName={selectedMedicine.name}
            minimumStock={selectedMedicine.minimumStock}
          />
        </div>
      ) : null}

      <Form className="flex flex-col gap-4" onSubmit={handleSubmit}>
        {/* ÔöÇÔöÇ Operation type selector ÔöÇÔöÇ */}
        <div>
          <div
            className={`rounded-xl transition-colors ${
              errors.movementType
                ? "bg-danger-50 hover:bg-danger-100"
                : "bg-default-100 hover:bg-default-200"
            }`}
          >
            <label
              className={`${errors.movementType ? "text-danger" : "text-default-500"} text-xs ms-3 pt-2 block`}
              htmlFor="movementType"
            >
              Tipo de Operaci├│n{" "}
              <span className="text-danger font-bold ml-1">*</span>
            </label>
            <select
              className="w-full bg-transparent px-3 py-2 text-sm outline-none cursor-pointer"
              id="movementType"
              name="movementType"
              value={movementType ?? ""}
              onChange={handleMovementTypeChange}
            >
              <option value="">Seleccione un tipo de operaci├│n</option>
              {MANUAL_MOVEMENT_TYPES.map((type) => (
                <option key={type} value={type}>
                  {MovementTypeLabels[type].label}
                </option>
              ))}
            </select>
          </div>
          {errors.movementType ? (
            <p className="text-danger text-sm ms-1 mt-1">
              {errors.movementType}
            </p>
          ) : null}
        </div>

        {/* ÔöÇÔöÇ Dynamic fields (only shown when type is selected) ÔöÇÔöÇ */}
        {movementType !== null && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Medicine */}
              <CatalogueSelect<MedicineResponse>
                isRequired
                deps="State:eq:1"
                errorMessage={errors.medicineId}
                fieldSearch="Name"
                isInvalid={!!errors.medicineId}
                label="Medicamento"
                name="medicineId"
                placeholder="Buscar medicamento..."
                queryFn={getMedicines}
                selectorFn={selectorMedicine}
                onChange={handleMedicineChange}
              />

              {/* Branch */}
              <CatalogueSelect<BranchResponse>
                isRequired
                deps="State:eq:1"
                errorMessage={errors.branchId}
                fieldSearch="Name"
                isInvalid={!!errors.branchId}
                label="Sucursal"
                name="branchId"
                placeholder="Seleccionar sucursal..."
                queryFn={getBranches}
                selectorFn={selectorBranch}
                onChange={handleBranchChange}
              />

              {/* Quantity */}
              <TextField
                isRequired
                className="w-full flex flex-col gap-1"
                isInvalid={!!errors.quantity}
                name="quantity"
              >
                <Label className="font-bold">Cantidad</Label>
                <Input
                  className="w-full px-3 py-2 border rounded-md"
                  min="1"
                  step="1"
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                />
                {errors.quantity ? (
                  <FieldError>{errors.quantity}</FieldError>
                ) : null}
              </TextField>

              {/* Unit Cost (only for Compra) */}
              {fieldConfig?.unitCost ? (
                <TextField
                  isRequired
                  className="w-full flex flex-col gap-1"
                  isInvalid={!!errors.unitCost}
                  name="unitCost"
                >
                  <Label className="font-bold">Costo Unitario (Q)</Label>
                  <Input
                    className="w-full px-3 py-2 border rounded-md"
                    min="0.01"
                    step="0.01"
                    type="number"
                    value={unitCost}
                    onChange={(e) => setUnitCost(e.target.value)}
                  />
                  {errors.unitCost ? (
                    <FieldError>{errors.unitCost}</FieldError>
                  ) : null}
                </TextField>
              ) : null}

              {/* Reference Number */}
              {fieldConfig?.referenceNumber ? (
                <TextField
                  className="w-full flex flex-col gap-1"
                  name="referenceNumber"
                >
                  <Label className="font-bold">
                    {fieldConfig.referenceLabel}
                  </Label>
                  <Input
                    className="w-full px-3 py-2 border rounded-md"
                    maxLength={100}
                    type="text"
                    value={referenceNumber}
                    onChange={(e) => setReferenceNumber(e.target.value)}
                  />
                </TextField>
              ) : null}
            </div>

            {/* Notes / Justification */}
            {fieldConfig?.notes ? (
              <div className="flex flex-col gap-1">
                <label
                  className={`font-bold text-sm ${errors.notes ? "text-danger" : ""}`}
                  htmlFor="notes"
                >
                  {fieldConfig.notesLabel}
                </label>
                <textarea
                  className={`w-full px-3 py-2 border rounded-md resize-none ${
                    errors.notes ? "border-danger" : ""
                  }`}
                  id="notes"
                  maxLength={500}
                  name="notes"
                  rows={3}
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                />
                {errors.notes ? (
                  <p className="text-danger text-sm">{errors.notes}</p>
                ) : null}
                {(movementType === 4 || movementType === 5) && (
                  <p className="text-xs text-default-400">
                    {notes.trim().length}/10 caracteres m├¡nimos
                  </p>
                )}
              </div>
            ) : null}

            {/* ÔöÇÔöÇ Inventory info panel ÔöÇÔöÇ */}
            {medicineId && branchId ? (
              <div className="p-4 rounded-lg border bg-default-50">
                <h3 className="text-sm font-bold mb-2">
                  <i className="bi bi-info-circle mr-1" />
                  Informaci├│n de Inventario
                </h3>
                {inventoryLoading ? (
                  <p className="text-sm text-default-400">
                    Consultando inventario...
                  </p>
                ) : inventory ? (
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
                    <div>
                      <span className="text-default-500 block">
                        Stock Actual
                      </span>
                      <span className="font-bold text-lg">
                        {inventory.currentStock}
                      </span>
                    </div>
                    <div>
                      <span className="text-default-500 block">
                        Stock M├¡nimo
                      </span>
                      <span className="font-bold text-lg">
                        {selectedMedicine?.minimumStock ?? "ÔÇö"}
                      </span>
                    </div>
                    {projectedStock !== null && (
                      <div>
                        <span className="text-default-500 block">
                          Stock Proyectado
                        </span>
                        <span
                          className={`font-bold text-lg ${
                            projectedStock < 0
                              ? "text-danger"
                              : showLowStockAlert
                                ? "text-warning"
                                : "text-success"
                          }`}
                        >
                          {projectedStock}
                        </span>
                      </div>
                    )}
                    <div>
                      <span className="text-default-500 block">Operaci├│n</span>
                      <span
                        className={`inline-flex items-center px-2 py-0.5 rounded-md text-xs font-semibold ${
                          MovementTypeLabels[movementType]?.color ?? ""
                        }`}
                      >
                        {isEntryType(movementType) ? "Ôåæ Entrada" : "Ôåô Salida"}
                      </span>
                    </div>
                  </div>
                ) : (
                  <p className="text-sm text-warning">
                    ÔÜá´©Å No se encontr├│ registro de inventario para esta
                    combinaci├│n de medicamento y sucursal.
                  </p>
                )}
              </div>
            ) : null}

            {/* ÔöÇÔöÇ Actions ÔöÇÔöÇ */}
            <div className="flex gap-4 justify-end mt-4">
              <AsyncButton
                className="font-bold"
                isLoading={false}
                size="lg"
                type="button"
                variant="secondary"
                onClick={() => navigate("/inventory-movement")}
              >
                Cancelar
              </AsyncButton>
              <AsyncButton
                className="font-bold"
                isLoading={isPending}
                loadingText="Registrando..."
                size="lg"
                type="submit"
                variant="primary"
              >
                <i className="bi bi-journal-plus mr-2" />
                Registrar Movimiento
              </AsyncButton>
            </div>
          </>
        )}
      </Form>
    </div>
  );
}

import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useCallback, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import type { SingleValue } from "react-select";
import { useForm } from "../../hooks/useForm";
import { getLaboratories } from "../../services/laboratoryService";
import type { ApiResponse } from "../../types/ApiResponse";
import type { LabExamRequest } from "../../types/LabExamResponse";
import type { LaboratoryResponse } from "../../types/LaboratoryResponse";
import type { ValidationFailure } from "../../types/ValidationFailure";
import { validateLabExam } from "../../validations/labExamValidation";
import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { CatalogueSelect } from "../select/CatalogueSelect";
import { OptionsSelect, type OptionValue } from "../select/OptionsSelect";

interface LabExamFormProps {
  readonly type: "create" | "edit";
  readonly initialForm: LabExamRequest;
  readonly onSubmit: (
    form: LabExamRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
}

export function LabExamForm({ type, initialForm, onSubmit }: LabExamFormProps) {
  const isEditing = type === "edit";
  const navigate = useNavigate();

  const {
    form,
    errors,
    handleChange,
    handleSubmit,
    success,
    message,
    loading,
  } = useForm<LabExamRequest, unknown>(
    initialForm,
    validateLabExam,
    onSubmit,
    true,
  );

  const handleTextChange = useCallback(
    (name: string) => (val: string) => {
      handleChange({
        target: { name, value: val },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleSelectChange = useCallback(
    (name: string) => (opt: OptionValue) => {
      const option = opt as SingleValue<{ label: string; value: string }>;
      handleChange({
        target: { name, value: option?.value || "" },
      } as React.ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleStateChange = useCallback(
    (newValue: OptionValue) => {
      const value =
        newValue && !Array.isArray(newValue) && "value" in newValue
          ? Number((newValue as { value: string }).value)
          : null;
      handleChange({
        target: { name: "state", value },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const selectorLaboratory = useCallback(
    (item: LaboratoryResponse) => ({
      label: item.name,
      value: String(item.id),
    }),
    [],
  );

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        {isEditing
          ? "Editar Examen de Laboratorio"
          : "Crear Examen de Laboratorio"}
      </h1>
      {success != null && <Response message={message} type={success} />}
      <Form
        className="flex flex-col gap-4"
        validationErrors={errors}
        onSubmit={handleSubmit}
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.name}
            name="name"
            onChange={handleTextChange("name")}
          >
            <Label className="font-bold">Nombre del Examen</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.name || ""}
            />
            {errors?.name ? (
              <FieldError>{errors.name as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.defaultAmount}
            name="defaultAmount"
            onChange={handleTextChange("defaultAmount")}
          >
            <Label className="font-bold">Precio Base (Q)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              min="0"
              step="0.01"
              type="number"
              value={form.defaultAmount?.toString() || ""}
            />
            {errors?.defaultAmount ? (
              <FieldError>{errors.defaultAmount as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.description}
            name="description"
            onChange={handleTextChange("description")}
          >
            <Label className="font-bold">Descripci├│n</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.description || ""}
            />
            {errors?.description ? (
              <FieldError>{errors.description as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.unit}
            name="unit"
            onChange={handleTextChange("unit")}
          >
            <Label className="font-bold">Unidad de Medida</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.unit || ""}
            />
            {errors?.unit ? (
              <FieldError>{errors.unit as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.referenceRange}
            name="referenceRange"
            onChange={handleTextChange("referenceRange")}
          >
            <Label className="font-bold">Rango de Referencia</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.referenceRange || ""}
            />
            {errors?.referenceRange ? (
              <FieldError>{errors.referenceRange as string}</FieldError>
            ) : null}
          </TextField>
          <CatalogueSelect
            isRequired
            defaultValue={
              isEditing && form.laboratoryId
                ? {
                    label: String(form.laboratoryId),
                    value: String(form.laboratoryId),
                  }
                : null
            }
            deps="State:eq:1"
            errorMessage={errors?.laboratoryId as string}
            fieldSearch="Name"
            isInvalid={!!errors?.laboratoryId}
            label="Laboratorio"
            name="laboratoryId"
            placeholder="Seleccione un laboratorio"
            queryFn={getLaboratories}
            selectorFn={selectorLaboratory}
            onChange={handleSelectChange("laboratoryId")}
          />
          <OptionsSelect
            isRequired
            defaultValue={
              form.state !== null && form.state !== undefined
                ? {
                    label: form.state === 1 ? "Activo" : "Inactivo",
                    value: String(form.state),
                  }
                : { label: "Activo", value: "1" }
            }
            errorMessage={errors?.state as string}
            isInvalid={!!errors?.state}
            label="Estado"
            name="state"
            options={[
              { label: "Activo", value: "1" },
              { label: "Inactivo", value: "0" },
            ]}
            placeholder="Seleccione un estado"
            onChange={handleStateChange}
          />
        </div>
        <div className="flex gap-4 justify-end mt-4">
          <AsyncButton
            className="font-bold"
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() => navigate("/lab-exam")}
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            className="font-bold"
            isLoading={loading}
            loadingText={isEditing ? "Actualizando..." : "Creando..."}
            size="lg"
            type="submit"
            variant="primary"
          >
            {isEditing ? "Actualizar" : "Crear"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { Form, Input, Label, TextField } from "@heroui/react";
import { useMutation } from "@tanstack/react-query";
import {
  useCallback,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
} from "react";
import type { MultiValue, SingleValue } from "react-select";
import { getLabExams } from "../../services/labExamService";
import {
  createLabOrder,
  createLabOrderItem,
} from "../../services/labOrderService";
import type { LabExamResponse } from "../../types/LabExamResponse";
import type { LabOrderRequest } from "../../types/LabOrderResponse";
import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { CatalogueSelect } from "../select/CatalogueSelect";

interface LabOrderFormProps {
  readonly initialConsultationId?: number | null;
  readonly initialDoctorId?: number | null;
  readonly initialPatientId?: number | null;
  readonly fromDoctorDashboard?: boolean;
  readonly patientName?: string;
  readonly onSuccess?: (labOrderId: number) => void;
}

interface LabOrderItemRow {
  id: string; // local key for React list rendering
  labExamId: number | null;
  examName: string;
  defaultAmount: number | null;
}

interface LabOrderFormState {
  consultationId: number | null;
  doctorId: number | null;
  patientId: number | null;
  isExternal: boolean;
  notes: string;
}

const formatCurrency = (amount: number): string => `Q ${amount.toFixed(2)}`;

const newItemRow = (): LabOrderItemRow => ({
  id: crypto.randomUUID(),
  labExamId: null,
  examName: "",
  defaultAmount: null,
});

export function LabOrderForm({
  initialConsultationId,
  initialDoctorId,
  initialPatientId,
  fromDoctorDashboard = false,
  patientName,
  onSuccess,
}: LabOrderFormProps) {
  const [form, setForm] = useState<LabOrderFormState>({
    consultationId: initialConsultationId ?? null,
    doctorId: initialDoctorId ?? null,
    patientId: initialPatientId ?? null,
    isExternal: false,
    notes: "",
  });

  const [items, setItems] = useState<LabOrderItemRow[]>([newItemRow()]);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitSuccess, setSubmitSuccess] = useState<string | null>(null);

  // Cache of fetched LabExam data keyed by exam ID
  const examCacheRef = useRef<Map<number, LabExamResponse>>(new Map());

  // ÔöÇÔöÇ Computed total ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const totalAmount = useMemo(
    () => items.reduce((sum, item) => sum + (item.defaultAmount ?? 0), 0),
    [items],
  );

  // ÔöÇÔöÇ Field handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const handleChange = useCallback(
    (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      const { name, value, type } = e.target as HTMLInputElement;
      setForm((prev) => ({
        ...prev,
        [name]:
          type === "checkbox"
            ? (e.target as HTMLInputElement).checked
            : type === "number"
              ? value === ""
                ? null
                : Number(value)
              : value,
      }));
    },
    [],
  );

  // ÔöÇÔöÇ Item handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const addItem = useCallback(() => {
    setItems((prev) => [...prev, newItemRow()]);
  }, []);

  const removeItem = useCallback((id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  }, []);

  const updateItemExam = useCallback(
    (id: string) =>
      (
        opt:
          | SingleValue<{ label: string; value: string }>
          | MultiValue<{ label: string; value: string }>
          | null,
      ) => {
        if (opt && !Array.isArray(opt) && "value" in opt) {
          const examId = Number(opt.value);
          const cachedExam = examCacheRef.current.get(examId);
          const defaultAmount = cachedExam?.defaultAmount ?? null;
          const examName = cachedExam?.name ?? opt.label;
          setItems((prev) =>
            prev.map((item) =>
              item.id === id
                ? { ...item, labExamId: examId, examName, defaultAmount }
                : item,
            ),
          );
        } else {
          setItems((prev) =>
            prev.map((item) =>
              item.id === id
                ? {
                    ...item,
                    labExamId: null,
                    examName: "",
                    defaultAmount: null,
                  }
                : item,
            ),
          );
        }
      },
    [],
  );

  const selectorLabExam = useCallback((item: LabExamResponse) => {
    // Cache the full exam data for price lookup
    examCacheRef.current.set(item.id, item);
    return { label: item.name, value: String(item.id) };
  }, []);

  // ÔöÇÔöÇ Mutations ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const { mutateAsync: doCreateOrder, isPending } = useMutation({
    mutationFn: (data: LabOrderRequest) => createLabOrder(data),
  });

  // ÔöÇÔöÇ Submit ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const handleSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();
      setSubmitError(null);
      setSubmitSuccess(null);

      if (!form.doctorId) {
        setSubmitError("El ID del m├®dico es requerido.");
        return;
      }
      if (!form.patientId) {
        setSubmitError("El ID del paciente es requerido.");
        return;
      }
      if (items.length === 0) {
        setSubmitError("Debe agregar al menos un examen.");
        return;
      }
      if (items.some((i) => !i.labExamId)) {
        setSubmitError("Todos los ex├ímenes deben tener un tipo seleccionado.");
        return;
      }

      const orderPayload: LabOrderRequest = {
        consultationId: form.consultationId,
        doctorId: form.doctorId,
        patientId: form.patientId,
        orderStatus: 0,
        isExternal: form.isExternal,
        notes: form.notes || null,
        state: 1,
      };

      const orderResponse = await doCreateOrder(orderPayload);
      if (!orderResponse.success) {
        setSubmitError(orderResponse.message ?? "Error al crear la orden.");
        return;
      }

      const labOrderId = orderResponse.data.id;

      // Create each item sequentially
      for (const item of items) {
        const itemResponse = await createLabOrderItem({
          labOrderId,
          labExamId: item.labExamId!,
          amount: item.defaultAmount ?? 0,
          state: 1,
        });
        if (!itemResponse.success) {
          setSubmitError(`Error al agregar examen: ${itemResponse.message}`);
          return;
        }
      }

      const examCount = items.length;
      const totalFormatted = formatCurrency(totalAmount);
      setSubmitSuccess(
        `Orden de laboratorio creada exitosamente. ${examCount} examen(es) registrado(s). Costo total estimado: ${totalFormatted}.`,
      );
      onSuccess?.(labOrderId);
    },
    [form, items, doCreateOrder, onSuccess],
  );

  return (
    <div className="max-w-3xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-2">
        Nueva Orden de Laboratorio
      </h1>

      {fromDoctorDashboard && patientName ? (
        <div className="mb-4 rounded-xl bg-blue-50 border border-blue-200 px-4 py-3 text-center dark:bg-blue-900/20 dark:border-blue-700">
          <p className="text-sm text-blue-700 dark:text-blue-300">
            <i className="bi bi-flask mr-2" />
            Orden para: <strong>{patientName}</strong>
          </p>
        </div>
      ) : null}

      {submitError ? <Response message={submitError} type={false} /> : null}
      {submitSuccess ? <Response type message={submitSuccess} /> : null}

      <Form className="flex flex-col gap-4" onSubmit={handleSubmit}>
        {/* ÔöÇÔöÇ Header fields ÔöÇÔöÇ */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Only show manual ID fields when NOT coming from doctor dashboard */}
          {!fromDoctorDashboard && (
            <>
              <TextField className="flex flex-col gap-1" name="consultationId">
                <Label className="font-bold text-sm">
                  ID de Consulta (opcional)
                </Label>
                <Input
                  className="px-3 py-2 border rounded-md"
                  name="consultationId"
                  type="number"
                  value={form.consultationId?.toString() ?? ""}
                  onChange={handleChange}
                />
              </TextField>
              <TextField
                isRequired
                className="flex flex-col gap-1"
                name="doctorId"
              >
                <Label className="font-bold text-sm">ID del M├®dico *</Label>
                <Input
                  className="px-3 py-2 border rounded-md"
                  name="doctorId"
                  type="number"
                  value={form.doctorId?.toString() ?? ""}
                  onChange={handleChange}
                />
              </TextField>
              <TextField
                isRequired
                className="flex flex-col gap-1"
                name="patientId"
              >
                <Label className="font-bold text-sm">ID del Paciente *</Label>
                <Input
                  className="px-3 py-2 border rounded-md"
                  name="patientId"
                  type="number"
                  value={form.patientId?.toString() ?? ""}
                  onChange={handleChange}
                />
              </TextField>
            </>
          )}
          <div className="flex flex-col gap-1">
            <label className="font-bold text-sm">Estado</label>
            <input
              readOnly
              className="px-3 py-2 border rounded-md bg-gray-100 text-gray-500 cursor-not-allowed"
              type="text"
              value="Pendiente"
            />
          </div>

          <div className="flex items-center gap-3 md:col-span-2">
            <input
              checked={form.isExternal}
              className="w-4 h-4 accent-blue-600"
              id="isExternal"
              name="isExternal"
              type="checkbox"
              onChange={handleChange}
            />
            <label
              className="font-bold text-sm cursor-pointer"
              htmlFor="isExternal"
            >
              Orden Externa
            </label>
          </div>

          <div className="flex flex-col gap-1 md:col-span-2">
            <label className="font-bold text-sm" htmlFor="notes">
              Notas (opcional)
            </label>
            <textarea
              className="px-3 py-2 border rounded-md resize-none"
              id="notes"
              name="notes"
              rows={3}
              value={form.notes}
              onChange={handleChange}
            />
          </div>
        </div>

        {/* ÔöÇÔöÇ Items ÔöÇÔöÇ */}
        <div className="mt-4">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-lg font-bold">
              <i className="bi bi-flask mr-2" />
              Ex├ímenes ({items.length})
            </h2>
            <button
              className="px-4 py-2 rounded-lg text-sm font-semibold bg-blue-100 text-blue-800 hover:bg-blue-200 transition-colors"
              type="button"
              onClick={addItem}
            >
              <i className="bi bi-plus-circle mr-1" /> Agregar Examen
            </button>
          </div>

          {items.length === 0 && (
            <p className="text-gray-400 text-center py-4">
              No hay ex├ímenes. Haga clic en "Agregar Examen" para comenzar.
            </p>
          )}

          <div className="flex flex-col gap-3">
            {items.map((item, index) => (
              <div
                key={item.id}
                className="grid grid-cols-1 md:grid-cols-[1fr_140px_auto] gap-3 items-end p-3 bg-gray-50 dark:bg-gray-800 rounded-lg border"
              >
                <div>
                  <label className="font-bold text-sm block mb-1">
                    Examen #{index + 1} *
                  </label>
                  <CatalogueSelect<LabExamResponse>
                    fieldSearch="Name"
                    label=""
                    placeholder="Buscar examen..."
                    queryFn={getLabExams}
                    selectorFn={selectorLabExam}
                    onChange={updateItemExam(item.id)}
                  />
                </div>

                <div className="flex flex-col gap-1">
                  <label className="font-bold text-sm">Precio</label>
                  {item.labExamId == null ? (
                    <span className="px-3 py-2 text-sm text-gray-400">ÔÇö</span>
                  ) : !item.defaultAmount ? (
                    <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-xs font-semibold bg-yellow-100 text-yellow-800">
                      <i className="bi bi-exclamation-triangle" /> Precio no
                      configurado
                    </span>
                  ) : (
                    <span className="px-3 py-2 text-sm font-semibold text-green-700 dark:text-green-400">
                      {formatCurrency(item.defaultAmount)}
                    </span>
                  )}
                </div>

                <button
                  className="px-3 py-2 rounded-lg text-sm font-semibold bg-red-100 text-red-700 hover:bg-red-200 transition-colors self-end"
                  type="button"
                  onClick={() => removeItem(item.id)}
                >
                  <i className="bi bi-trash mr-1" /> Eliminar
                </button>
              </div>
            ))}
          </div>

          {/* ÔöÇÔöÇ Total ÔöÇÔöÇ */}
          {items.length > 0 && (
            <div className="flex justify-end mt-4 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-700">
              <span className="text-lg font-bold text-blue-800 dark:text-blue-300">
                Total: {formatCurrency(totalAmount)}
              </span>
            </div>
          )}
        </div>

        {/* ÔöÇÔöÇ Submit ÔöÇÔöÇ */}
        <div className="flex justify-end mt-4">
          <AsyncButton
            className="font-bold"
            isLoading={isPending}
            loadingText="Creando orden..."
            size="lg"
            type="submit"
            variant="primary"
          >
            <i className="bi bi-clipboard-plus mr-2" /> Crear Orden
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useCallback, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import { useForm } from "../../hooks/useForm";
import type { ApiResponse } from "../../types/ApiResponse";
import type { LaboratoryRequest } from "../../types/LaboratoryResponse";
import type { ValidationFailure } from "../../types/ValidationFailure";
import { validateLaboratory } from "../../validations/laboratoryValidation";
import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { OptionsSelect, type OptionValue } from "../select/OptionsSelect";

interface LaboratoryFormProps {
  readonly type: "create" | "edit";
  readonly initialForm: LaboratoryRequest;
  readonly onSubmit: (
    form: LaboratoryRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
}

export function LaboratoryForm({
  type,
  initialForm,
  onSubmit,
}: LaboratoryFormProps) {
  const isEditing = type === "edit";
  const navigate = useNavigate();

  const {
    form,
    errors,
    handleChange,
    handleSubmit,
    success,
    message,
    loading,
  } = useForm<LaboratoryRequest, unknown>(
    initialForm,
    validateLaboratory,
    onSubmit,
    true,
  );

  const handleTextChange = useCallback(
    (name: string) => (val: string) => {
      handleChange({
        target: { name, value: val },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleStateChange = useCallback(
    (newValue: OptionValue) => {
      const value =
        newValue && !Array.isArray(newValue) && "value" in newValue
          ? Number((newValue as { value: string }).value)
          : null;
      handleChange({
        target: { name: "state", value },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        {isEditing ? "Editar Laboratorio" : "Crear Laboratorio"}
      </h1>
      {success != null && <Response message={message} type={success} />}
      <Form
        className="flex flex-col gap-4"
        validationErrors={errors}
        onSubmit={handleSubmit}
      >
        <TextField
          isRequired
          className="w-full flex flex-col gap-1"
          isInvalid={!!errors?.name}
          name="name"
          onChange={handleTextChange("name")}
        >
          <Label className="font-bold">Nombre</Label>
          <Input
            className="w-full px-3 py-2 border rounded-md"
            type="text"
            value={form.name || ""}
          />
          {errors?.name ? (
            <FieldError>{errors.name as string}</FieldError>
          ) : null}
        </TextField>
        <TextField
          className="w-full flex flex-col gap-1"
          isInvalid={!!errors?.description}
          name="description"
          onChange={handleTextChange("description")}
        >
          <Label className="font-bold">Descripci├│n</Label>
          <Input
            className="w-full px-3 py-2 border rounded-md"
            type="text"
            value={form.description || ""}
          />
          {errors?.description ? (
            <FieldError>{errors.description as string}</FieldError>
          ) : null}
        </TextField>
        <OptionsSelect
          isRequired
          defaultValue={
            form.state !== null && form.state !== undefined
              ? {
                  label: form.state === 1 ? "Activo" : "Inactivo",
                  value: String(form.state),
                }
              : { label: "Activo", value: "1" }
          }
          errorMessage={errors?.state as string}
          isInvalid={!!errors?.state}
          label="Estado"
          name="state"
          options={[
            { label: "Activo", value: "1" },
            { label: "Inactivo", value: "0" },
          ]}
          placeholder="Seleccione un estado"
          onChange={handleStateChange}
        />
        <div className="flex gap-4 justify-end mt-4">
          <AsyncButton
            className="font-bold"
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() => navigate("/laboratory")}
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            className="font-bold"
            isLoading={loading}
            loadingText={isEditing ? "Actualizando..." : "Creando..."}
            size="lg"
            type="submit"
            variant="primary"
          >
            {isEditing ? "Actualizar" : "Crear"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useCallback, useState, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import { useCie10Autocomplete } from "../../hooks/useCie10Autocomplete";
import { useForm } from "../../hooks/useForm";
import type { ApiResponse } from "../../types/ApiResponse";
import type { MedicalConsultationRequest } from "../../types/MedicalConsultationResponse";
import type { ValidationFailure } from "../../types/ValidationFailure";
import { validateMedicalConsultation } from "../../validations/medicalConsultationValidation";
import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { OptionsSelect, type OptionValue } from "../select/OptionsSelect";

interface MedicalConsultationFormProps {
  readonly type: "create" | "edit";
  readonly initialForm: MedicalConsultationRequest;
  readonly onSubmit: (
    form: MedicalConsultationRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
  readonly fromDoctorDashboard?: boolean;
  readonly patientName?: string;
  readonly doctorName?: string;
}

export function MedicalConsultationForm({
  type,
  initialForm,
  onSubmit,
  fromDoctorDashboard = false,
  patientName,
  doctorName,
}: MedicalConsultationFormProps) {
  const isEditing = type === "edit";
  const navigate = useNavigate();

  const [cie10Query, setCie10Query] = useState("");
  const [showSuggestions, setShowSuggestions] = useState(false);
  const { suggestions, isLoading: cie10Loading } =
    useCie10Autocomplete(cie10Query);

  const {
    form,
    errors,
    handleChange,
    handleSubmit,
    success,
    message,
    loading,
  } = useForm<MedicalConsultationRequest, unknown>(
    initialForm,
    validateMedicalConsultation,
    onSubmit,
    true,
  );

  const handleTextChange = useCallback(
    (name: string) => (val: string) => {
      handleChange({
        target: { name, value: val },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleSelectChange = useCallback(
    (name: string) => (newValue: OptionValue) => {
      const value =
        newValue && !Array.isArray(newValue) && "value" in newValue
          ? Number((newValue as { value: string }).value)
          : null;
      handleChange({
        target: { name, value },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  return (
    <div className="max-w-3xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-2">
        {isEditing ? "Editar Consulta M├®dica" : "Nueva Consulta M├®dica"}
      </h1>
      {fromDoctorDashboard &&
      (patientName || doctorName || initialForm.appointmentId) ? (
        <div className="mb-4 rounded-xl bg-blue-50 border border-blue-200 px-4 py-3 dark:bg-blue-900/20 dark:border-blue-700">
          <div className="flex flex-wrap gap-4 text-sm text-blue-700 dark:text-blue-300 justify-center">
            {initialForm.appointmentId ? (
              <span>
                <i className="bi bi-hash mr-1" />
                Cita: <strong>#{initialForm.appointmentId}</strong>
              </span>
            ) : null}
            {patientName ? (
              <span>
                <i className="bi bi-person-check mr-1" />
                Paciente: <strong>{patientName}</strong>
              </span>
            ) : null}
            {doctorName ? (
              <span>
                <i className="bi bi-person-badge mr-1" />
                M├®dico: <strong>{doctorName}</strong>
              </span>
            ) : null}
          </div>
        </div>
      ) : null}
      {success != null && <Response message={message} type={success} />}
      <Form
        className="flex flex-col gap-4"
        validationErrors={errors}
        onSubmit={handleSubmit}
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Hide manual ID fields when coming from doctor dashboard */}
          {!fromDoctorDashboard && (
            <>
              <TextField
                isRequired
                className="w-full flex flex-col gap-1"
                isInvalid={!!errors?.appointmentId}
                name="appointmentId"
                onChange={handleTextChange("appointmentId")}
              >
                <Label className="font-bold">ID de Cita</Label>
                <Input
                  className="w-full px-3 py-2 border rounded-md"
                  type="number"
                  value={form.appointmentId?.toString() || ""}
                />
                {errors?.appointmentId ? (
                  <FieldError>{errors.appointmentId as string}</FieldError>
                ) : null}
              </TextField>
              <TextField
                isRequired
                className="w-full flex flex-col gap-1"
                isInvalid={!!errors?.doctorId}
                name="doctorId"
                onChange={handleTextChange("doctorId")}
              >
                <Label className="font-bold">ID M├®dico</Label>
                <Input
                  className="w-full px-3 py-2 border rounded-md"
                  type="number"
                  value={form.doctorId?.toString() || ""}
                />
                {errors?.doctorId ? (
                  <FieldError>{errors.doctorId as string}</FieldError>
                ) : null}
              </TextField>
            </>
          )}
          <TextField
            isRequired
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.reasonForVisit}
            name="reasonForVisit"
            onChange={handleTextChange("reasonForVisit")}
          >
            <Label className="font-bold">Motivo de Visita</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.reasonForVisit || ""}
            />
            {errors?.reasonForVisit ? (
              <FieldError>{errors.reasonForVisit as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.clinicalFindings}
            name="clinicalFindings"
            onChange={handleTextChange("clinicalFindings")}
          >
            <Label className="font-bold">Hallazgos Cl├¡nicos</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.clinicalFindings || ""}
            />
            {errors?.clinicalFindings ? (
              <FieldError>{errors.clinicalFindings as string}</FieldError>
            ) : null}
          </TextField>
          <div className="w-full flex flex-col gap-1 relative">
            <label className="font-bold text-sm">C├│digo CIE-10</label>
            <input
              className="w-full px-3 py-2 border rounded-md"
              placeholder="Buscar diagn├│stico CIE-10..."
              type="text"
              value={cie10Query || form.diagnosisCie10Code || ""}
              onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
              onChange={(e) => {
                setCie10Query(e.target.value);
                setShowSuggestions(true);
                // Also update the form field directly
                handleChange({
                  target: { name: "diagnosisCie10Code", value: e.target.value },
                } as React.ChangeEvent<HTMLInputElement>);
              }}
            />
            {cie10Loading ? (
              <p className="text-xs text-gray-400">Buscando...</p>
            ) : null}
            {showSuggestions && suggestions.length > 0 ? (
              <ul className="absolute top-full left-0 right-0 z-50 bg-white border border-gray-200 rounded-md shadow-lg max-h-48 overflow-y-auto">
                {suggestions.map((item) => (
                  <li
                    key={item.code}
                    className="px-3 py-2 hover:bg-blue-50 cursor-pointer text-sm"
                    onMouseDown={() => {
                      const value = `${item.code} - ${item.description}`;
                      setCie10Query(value);
                      handleChange({
                        target: { name: "diagnosisCie10Code", value },
                      } as React.ChangeEvent<HTMLInputElement>);
                      setShowSuggestions(false);
                    }}
                  >
                    <span className="font-mono font-semibold text-blue-700">
                      {item.code}
                    </span>
                    {" ÔÇö "}
                    <span className="text-gray-700">{item.description}</span>
                  </li>
                ))}
              </ul>
            ) : null}
            {errors?.diagnosisCie10Code ? (
              <p className="text-danger text-sm">
                {errors.diagnosisCie10Code as string}
              </p>
            ) : null}
          </div>
          <OptionsSelect
            isRequired
            defaultValue={
              form.consultationStatus !== null &&
              form.consultationStatus !== undefined
                ? {
                    label:
                      form.consultationStatus === 0 ? "En curso" : "Finalizada",
                    value: String(form.consultationStatus),
                  }
                : { label: "En curso", value: "0" }
            }
            errorMessage={errors?.consultationStatus as string}
            isInvalid={!!errors?.consultationStatus}
            label="Estado de Consulta"
            name="consultationStatus"
            options={[
              { label: "En curso", value: "0" },
              { label: "Finalizada", value: "1" },
            ]}
            placeholder="Seleccione estado"
            onChange={handleSelectChange("consultationStatus")}
          />
          <TextField
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.diagnosis}
            name="diagnosis"
            onChange={handleTextChange("diagnosis")}
          >
            <Label className="font-bold">
              Diagn├│stico{" "}
              <span className="text-sm text-gray-500">
                (obligatorio para finalizar)
              </span>
            </Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.diagnosis || ""}
            />
            {errors?.diagnosis ? (
              <FieldError>{errors.diagnosis as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.treatmentPlan}
            name="treatmentPlan"
            onChange={handleTextChange("treatmentPlan")}
          >
            <Label className="font-bold">Plan de Tratamiento</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.treatmentPlan || ""}
            />
            {errors?.treatmentPlan ? (
              <FieldError>{errors.treatmentPlan as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1 md:col-span-2"
            isInvalid={!!errors?.notes}
            name="notes"
            onChange={handleTextChange("notes")}
          >
            <Label className="font-bold">Notas Adicionales</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.notes || ""}
            />
            {errors?.notes ? (
              <FieldError>{errors.notes as string}</FieldError>
            ) : null}
          </TextField>
          <OptionsSelect
            isRequired
            defaultValue={
              form.state !== null && form.state !== undefined
                ? {
                    label: form.state === 1 ? "Activo" : "Inactivo",
                    value: String(form.state),
                  }
                : { label: "Activo", value: "1" }
            }
            errorMessage={errors?.state as string}
            isInvalid={!!errors?.state}
            label="Estado"
            name="state"
            options={[
              { label: "Activo", value: "1" },
              { label: "Inactivo", value: "0" },
            ]}
            placeholder="Seleccione un estado"
            onChange={handleSelectChange("state")}
          />
        </div>
        <div className="flex gap-4 justify-end mt-4">
          {isEditing && initialForm.id ? (
            <div className="flex flex-wrap gap-3 mt-2 pt-4 border-t border-gray-200">
              <p className="w-full text-sm font-semibold text-gray-600 mb-1">
                Acciones de la consulta:
              </p>
              <button
                className="px-4 py-2 rounded-lg text-sm font-semibold bg-blue-100 text-blue-800 hover:bg-blue-200 transition-colors"
                type="button"
                onClick={() =>
                  navigate(
                    `/prescription/create?consultationId=${initialForm.id}`,
                  )
                }
              >
                ­ƒôï Crear Receta
              </button>
              <button
                className="px-4 py-2 rounded-lg text-sm font-semibold bg-purple-100 text-purple-800 hover:bg-purple-200 transition-colors"
                type="button"
                onClick={() =>
                  navigate(`/lab-order/create?consultationId=${initialForm.id}`)
                }
              >
                ­ƒö¼ Crear Orden de Lab
              </button>
              <button
                className="px-4 py-2 rounded-lg text-sm font-semibold bg-green-100 text-green-800 hover:bg-green-200 transition-colors"
                type="button"
                onClick={() =>
                  navigate(
                    `/appointment/create?followUp=true&parentConsultationId=${initialForm.id}`,
                  )
                }
              >
                ­ƒôà Agendar Seguimiento
              </button>
            </div>
          ) : null}
          <AsyncButton
            className="font-bold"
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() =>
              navigate(
                fromDoctorDashboard ? "/dashboard" : "/medical-consultation",
              )
            }
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            className="font-bold"
            isLoading={loading}
            loadingText={isEditing ? "Actualizando..." : "Guardando..."}
            size="lg"
            type="submit"
            variant="primary"
          >
            {isEditing ? "Actualizar" : "Guardar Consulta"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
