              <FieldError>{errors.name as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.unit}
            name="unit"
            onChange={handleTextChange("unit")}
          >
            <Label className="font-bold">Unidad (tableta, ml, etc.)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.unit || ""}
            />
            {errors?.unit ? (
              <FieldError>{errors.unit as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            isRequired
            className="w-full flex flex-col gap-1 md:col-span-2"
