            name="description"
            onChange={handleTextChange("description")}
          >
            <Label className="font-bold">Descripci├│n</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.description || ""}
            />
            {errors?.description ? (
              <FieldError>{errors.description as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.defaultPrice}
            name="defaultPrice"
            onChange={handleTextChange("defaultPrice")}
          >
            <Label className="font-bold">Precio Unitario (Q)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              min="0"
              step="0.01"
              type="number"
              value={form.defaultPrice?.toString() || ""}
            />
            {errors?.defaultPrice ? (
              <FieldError>{errors.defaultPrice as string}</FieldError>
            ) : null}
          </TextField>
          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.minimumStock}
            name="minimumStock"
            onChange={handleTextChange("minimumStock")}
          >
            <Label className="font-bold">Stock M├¡nimo</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              min="0"
              type="number"
              value={form.minimumStock?.toString() || ""}
            />
            {errors?.minimumStock ? (
              <FieldError>{errors.minimumStock as string}</FieldError>
            ) : null}
          </TextField>
          <OptionsSelect
            defaultValue={
              form.isControlled !== null && form.isControlled !== undefined
                ? {
                    label: form.isControlled ? "S├¡" : "No",
                    value: String(form.isControlled),
                  }
                : { label: "No", value: "false" }
            }
            errorMessage={errors?.isControlled as string}
            isInvalid={!!errors?.isControlled}
            label="┬┐Medicamento Controlado?"
            name="isControlled"
            options={[
              { label: "No", value: "false" },
              { label: "S├¡ ÔÜá´©Å", value: "true" },
            ]}
            placeholder="Seleccione"
            onChange={handleSelectChange("isControlled")}
          />
          <OptionsSelect
            isRequired
            defaultValue={
              form.state !== null && form.state !== undefined
                ? {
                    label: form.state === 1 ? "Activo" : "Inactivo",
                    value: String(form.state),
                  }
                : { label: "Activo", value: "1" }
            }
            errorMessage={errors?.state as string}
            isInvalid={!!errors?.state}
            label="Estado"
            name="state"
            options={[
              { label: "Activo", value: "1" },
              { label: "Inactivo", value: "0" },
            ]}
            placeholder="Seleccione un estado"
            onChange={handleStateChange}
          />
        </div>
        {form.isControlled ? (
          <div className="p-3 bg-orange-50 border border-orange-200 rounded-lg text-orange-800 text-sm">
            ÔÜá´©Å Este medicamento est├í marcado como controlado. Se aplicar├í
            auditor├¡a especial en cada despacho.
