          <AsyncButton
            className="font-bold"
            isLoading={loading}
            loadingText={isEditing ? "Actualizando..." : "Creando..."}
            size="lg"
            type="submit"
            variant="primary"
          >
            {isEditing ? "Actualizar" : "Crear"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useCallback, type ChangeEvent } from "react";
