          >
            <Label className="font-bold">Altura (cm)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              max="250"
              min="30"
              step="0.01"
              type="number"
              value={form.height?.toString() || ""}
            />
            {errors?.height ? (
              <FieldError>{errors.height as string}</FieldError>
            ) : null}
          </TextField>

          <OptionsSelect
            defaultValue={
              form.isEmergency
                ? { label: "S├¡ ­ƒÜ¿", value: "true" }
                : { label: "No", value: "false" }
            }
            label="┬┐Emergencia?"
            name="isEmergency"
            options={[
              { label: "No", value: "false" },
              { label: "S├¡ ­ƒÜ¿", value: "true" },
            ]}
            placeholder="Seleccione"
            onChange={(v) => {
              const val =
                v && !Array.isArray(v) && "value" in v
                  ? (v as { value: string }).value === "true"
                  : false;
              handleChange({
                target: { name: "isEmergency", value: val },
              } as unknown as ChangeEvent<HTMLInputElement>);
            }}
          />

          <OptionsSelect
            isRequired
            defaultValue={
              form.state !== null && form.state !== undefined
                ? {
                    label: form.state === 1 ? "Activo" : "Inactivo",
                    value: String(form.state),
                  }
                : { label: "Activo", value: "1" }
            }
            errorMessage={errors?.state as string}
            isInvalid={!!errors?.state}
            label="Estado"
            name="state"
            options={[
              { label: "Activo", value: "1" },
              { label: "Inactivo", value: "0" },
            ]}
            placeholder="Seleccione un estado"
