          />
        </div>
        <VitalSignAlertsDisplay alerts={alerts} />
        <div className="flex gap-4 justify-end mt-4">
          <AsyncButton
            className="font-bold"
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() =>
              navigate(fromNurseDashboard ? "/nurse-dashboard" : "/vital-sign")
