      setError("La fecha de vencimiento es requerida.");
      return;
    }

    setSaving(true);
    try {
      const request: DoctorTaskRequest = {
        doctorId: userId,
        title,
        description: description || null,
        dueDate: new Date(dueDate).toISOString(),
        priority,
      };

      if (isEditing && task) {
        request.id = task.id;
        await updateDoctorTask(request);
        toast.success(`Tarea actualizada exitosamente.`);
      } else {
        await createDoctorTask(request);
        toast.success(`Tarea creada exitosamente.`);
      }

      onSaved();
      onClose();
    } catch (err) {
      setError("Error al guardar la tarea. Intente de nuevo.");
    } finally {
      setSaving(false);
    }
  }, [
    title,
    description,
    dueDate,
    priority,
    userId,
    isEditing,
    task,
    onSaved,
    onClose,
  ]);

  const handleComplete = useCallback(async () => {
    if (!task) return;
    setSaving(true);
    try {
      await patchDoctorTask({ id: task.id, isCompleted: true });
      toast.success("Tarea completada exitosamente.");
      onSaved();
      onClose();
    } catch {
      setError("Error al completar la tarea.");
    } finally {
      setSaving(false);
    }
  }, [task, onSaved, onClose]);

  const handleDelete = useCallback(async () => {
    if (!task) return;
    setSaving(true);
    try {
      await patchDoctorTask({ id: task.id, state: 0 });
      toast.success("Tarea eliminada exitosamente.");
      onSaved();
      onClose();
    } catch {
      setError("Error al eliminar la tarea.");
    } finally {
      setSaving(false);
    }
  }, [task, onSaved, onClose]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
      onClick={onClose}
    >
      <div
        className="bg-white dark:bg-zinc-800 rounded-xl shadow-xl w-full max-w-lg mx-4 p-6"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold">
            {isEditing ? "Editar Tarea" : "Nueva Tarea"}
          </h2>
          <button
            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
            type="button"
            onClick={onClose}
          >
            <i className="bi bi-x-lg text-xl" />
          </button>
        </div>

        {error ? (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm dark:bg-red-900/20 dark:border-red-800 dark:text-red-300">
            {error}
          </div>
        ) : null}

        <div className="space-y-4">
          {/* Title */}
          <div>
            <label className="block text-sm font-medium mb-1">T├¡tulo *</label>
            <input
              className="w-full px-3 py-2 border border-gray-300 dark:border-zinc-600 rounded-lg bg-white dark:bg-zinc-700 text-sm focus:ring-2 focus:ring-orange-500 focus:border-transparent"
              maxLength={200}
              placeholder="T├¡tulo de la tarea"
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-medium mb-1">
              Descripci├│n
            </label>
            <textarea
              className="w-full px-3 py-2 border border-gray-300 dark:border-zinc-600 rounded-lg bg-white dark:bg-zinc-700 text-sm focus:ring-2 focus:ring-orange-500 focus:border-transparent resize-none"
              maxLength={1000}
              placeholder="Descripci├│n opcional"
              rows={3}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>

          {/* Due Date */}
          <div>
            <label className="block text-sm font-medium mb-1">
              Fecha de Vencimiento *
            </label>
            <input
              className="w-full px-3 py-2 border border-gray-300 dark:border-zinc-600 rounded-lg bg-white dark:bg-zinc-700 text-sm focus:ring-2 focus:ring-orange-500 focus:border-transparent"
              type="datetime-local"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
            />
          </div>

          {/* Priority */}
          <div>
            <label className="block text-sm font-medium mb-1">
              Prioridad *
            </label>
            <select
              className="w-full px-3 py-2 border border-gray-300 dark:border-zinc-600 rounded-lg bg-white dark:bg-zinc-700 text-sm focus:ring-2 focus:ring-orange-500 focus:border-transparent"
              value={priority}
              onChange={(e) => setPriority(Number(e.target.value))}
            >
              {Object.entries(PriorityLabels).map(([key, { label }]) => (
                <option key={key} value={key}>
                  {label}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center justify-between mt-6">
          <div className="flex gap-2">
            {isEditing ? (
              <>
                <button
                  className="px-4 py-2 text-sm font-medium text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                  disabled={saving}
                  type="button"
                  onClick={handleDelete}
                >
                  <i className="bi bi-trash mr-1" />
                  Eliminar
                </button>
                {!task?.isCompleted && (
                  <button
                    className="px-4 py-2 text-sm font-medium text-green-600 hover:text-green-700 hover:bg-green-50 dark:hover:bg-green-900/20 rounded-lg transition-colors"
                    disabled={saving}
                    type="button"
                    onClick={handleComplete}
                  >
                    <i className="bi bi-check-lg mr-1" />
                    Completar
                  </button>
                )}
              </>
            ) : null}
          </div>
          <div className="flex gap-2">
            <button
              className="px-4 py-2 text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-zinc-700 rounded-lg transition-colors"
              disabled={saving}
              type="button"
              onClick={onClose}
            >
              Cancelar
            </button>
            <button
              className="px-4 py-2 text-sm font-medium text-white bg-orange-500 hover:bg-orange-600 rounded-lg transition-colors disabled:opacity-50"
              disabled={saving}
              type="button"
              onClick={handleSave}
            >
              {saving ? "Guardando..." : isEditing ? "Actualizar" : "Crear"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/** Convert ISO date string to datetime-local input value */
function toDateInputValue(dateStr: string): string {
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return "";
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    const hours = String(d.getHours()).padStart(2, "0");
    const minutes = String(d.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  } catch {
    return "";
  }
}

import { useCallback, useMemo, useState } from "react";

import { patchDoctorTask } from "../../services/doctorTaskService";
import type { DoctorTaskResponse } from "../../types/DoctorTaskResponse";
import { PriorityLabels } from "../../types/DoctorTaskResponse";
import { formatTime } from "../../utils/dateFormatter";

interface TaskPanelProps {
  readonly tasks: DoctorTaskResponse[];
  readonly selectedDate: string;
  readonly onRefresh: () => void;
}

type TaskFilter = "all" | "pending" | "completed";

export function TaskPanel({ tasks, selectedDate, onRefresh }: TaskPanelProps) {
  const [filter, setFilter] = useState<TaskFilter>("pending");
  const [completingId, setCompletingId] = useState<number | null>(null);

  // Filter tasks for selected date
  const dayTasks = useMemo(() => {
    return tasks
      .filter((task) => {
        const taskDate = task.dueDate.split("T")[0];
        // Handle backend date format "dd/MM/yyyy HH:mm:ss"
        let normalizedDate = taskDate;
        if (task.dueDate.includes("/")) {
          const match = task.dueDate.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
          if (match) {
            normalizedDate = `${match[3]}-${match[2]}-${match[1]}`;
          }
        }
        return normalizedDate === selectedDate;
      })
      .filter((task) => {
        if (filter === "pending") return !task.isCompleted;
        if (filter === "completed") return task.isCompleted;
        return true;
      })
      .sort((a, b) => b.priority - a.priority); // Alta (2) first, Baja (0) last
  }, [tasks, selectedDate, filter]);

  const handleComplete = useCallback(
    async (taskId: number) => {
      setCompletingId(taskId);
      try {
        await patchDoctorTask({ id: taskId, isCompleted: true });
        onRefresh();
      } catch (error) {
        console.error("Error completing task:", error);
      } finally {
        setCompletingId(null);
      }
    },
    [onRefresh],
  );

  const formatSelectedDate = (dateStr: string): string => {
    try {
      const d = new Date(dateStr + "T12:00:00");
      return d.toLocaleDateString("es-GT", {
        weekday: "long",
        day: "numeric",
        month: "long",
      });
    } catch {
      return dateStr;
    }
  };

  return (
    <div className="w-full bg-white dark:bg-zinc-900 rounded-xl shadow-sm p-4 flex flex-col overflow-hidden max-h-[500px] lg:max-h-none">
      {/* Header */}
      <div className="mb-3">
        <h2 className="text-lg font-bold mb-1">Tareas del D├¡a</h2>
        <p className="text-sm text-gray-500 dark:text-gray-400 capitalize">
          {formatSelectedDate(selectedDate)}
        </p>
      </div>

      {/* Filter tabs */}
      <div className="flex gap-1 mb-3 bg-gray-100 dark:bg-zinc-800 rounded-lg p-1">
        <FilterButton
          active={filter === "pending"}
          label="Pendientes"
          onClick={() => setFilter("pending")}
        />
        <FilterButton
          active={filter === "completed"}
          label="Completadas"
          onClick={() => setFilter("completed")}
        />
        <FilterButton
          active={filter === "all"}
          label="Todas"
          onClick={() => setFilter("all")}
        />
      </div>

      {/* Task list */}
      <div className="flex-1 overflow-auto space-y-2 scrollbar-thin scrollbar-track-transparent scrollbar-thumb-gray-300 dark:scrollbar-thumb-zinc-700">
        {dayTasks.length === 0 ? (
          <div className="text-center py-8 text-gray-400 dark:text-gray-500">
            <i className="bi bi-check2-all text-3xl mb-2 block" />
            <p className="text-sm">
              {filter === "pending"
                ? "No hay tareas pendientes"
                : filter === "completed"
                  ? "No hay tareas completadas"
                  : "No hay tareas para este d├¡a"}
            </p>
          </div>
        ) : (
          dayTasks.map((task) => (
            <TaskItem
              key={task.id}
              completing={completingId === task.id}
              task={task}
              onComplete={handleComplete}
            />
          ))
        )}
      </div>

      {/* Summary */}
      <div className="mt-3 pt-3 border-t border-gray-200 dark:border-zinc-700">
        <div className="flex justify-between text-xs text-gray-500 dark:text-gray-400">
          <span>
            {
              tasks.filter((t) => {
                const taskDate = t.dueDate.split("T")[0];
                let normalizedDate = taskDate;
                if (t.dueDate.includes("/")) {
                  const match = t.dueDate.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
                  if (match)
                    normalizedDate = `${match[3]}-${match[2]}-${match[1]}`;
                }
                return normalizedDate === selectedDate && !t.isCompleted;
              }).length
            }{" "}
            pendientes
          </span>
          <span>
            {
              tasks.filter((t) => {
                const taskDate = t.dueDate.split("T")[0];
                let normalizedDate = taskDate;
                if (t.dueDate.includes("/")) {
                  const match = t.dueDate.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
                  if (match)
                    normalizedDate = `${match[3]}-${match[2]}-${match[1]}`;
                }
                return normalizedDate === selectedDate && t.isCompleted;
              }).length
            }{" "}
            completadas
          </span>
        </div>
      </div>
    </div>
  );
}

function FilterButton({
  active,
  label,
  onClick,
}: {
  readonly active: boolean;
  readonly label: string;
  readonly onClick: () => void;
}) {
  return (
    <button
      className={`flex-1 px-2 py-1.5 text-xs font-medium rounded-md transition-colors ${
        active
          ? "bg-white dark:bg-zinc-700 text-gray-900 dark:text-white shadow-sm"
          : "text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200"
      }`}
      type="button"
      onClick={onClick}
    >
      {label}
    </button>
  );
}

function TaskItem({
  task,
  completing,
  onComplete,
}: {
  readonly task: DoctorTaskResponse;
  readonly completing: boolean;
  readonly onComplete: (id: number) => void;
}) {
  const priorityInfo = PriorityLabels[task.priority] ?? PriorityLabels[1];

  return (
    <div
      className={`p-3 rounded-lg border transition-colors ${
        task.isCompleted
          ? "border-gray-200 dark:border-zinc-700 bg-gray-50 dark:bg-zinc-800/50 opacity-60"
          : "border-gray-200 dark:border-zinc-700 bg-white dark:bg-zinc-800 hover:border-orange-300 dark:hover:border-orange-700"
      }`}
    >
      <div className="flex items-start gap-2">
        {/* Checkbox */}
        {!task.isCompleted && (
          <button
            className="mt-0.5 shrink-0 w-5 h-5 rounded border-2 border-gray-300 dark:border-zinc-600 hover:border-orange-500 dark:hover:border-orange-400 flex items-center justify-center transition-colors disabled:opacity-50"
            disabled={completing}
            title="Marcar como completada"
            type="button"
            onClick={() => onComplete(task.id)}
          >
            {completing ? (
              <div className="w-3 h-3 border-2 border-orange-500 border-t-transparent rounded-full animate-spin" />
            ) : null}
          </button>
        )}
        {task.isCompleted ? (
          <div className="mt-0.5 shrink-0 w-5 h-5 rounded bg-green-500 flex items-center justify-center">
            <i className="bi bi-check text-white text-xs" />
          </div>
        ) : null}

        {/* Content */}
        <div className="flex-1 min-w-0">
          <p
            className={`text-sm font-medium truncate ${
              task.isCompleted
                ? "line-through text-gray-400 dark:text-gray-500"
                : ""
            }`}
          >
            {task.title}
          </p>
          {task.description ? (
            <p className="text-xs text-gray-500 dark:text-gray-400 truncate mt-0.5">
              {task.description}
            </p>
          ) : null}
          <div className="flex items-center gap-2 mt-1">
            <span
              className={`inline-flex items-center px-1.5 py-0.5 rounded text-xs font-medium ${priorityInfo.color}`}
            >
              {priorityInfo.label}
            </span>
            <span className="text-xs text-gray-400 dark:text-gray-500">
              {formatTime(task.dueDate)}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

import { toast } from "@heroui/react";
import { useMutation } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useIdempotencyKey } from "../../hooks/useIdempotencyKey";
import { useLuhnValidator } from "../../hooks/useLuhnValidator";
import { usePaymentTimer } from "../../hooks/usePaymentTimer";
import { createPayment } from "../../services/paymentService";
import type { PaymentResponse } from "../../types/PaymentResponse";
import { maskCardNumber } from "../../utils/maskCardNumber";
import { AsyncButton } from "../button/AsyncButton";
import { CountdownTimer } from "../shared/CountdownTimer";

interface CardPaymentFormProps {
  readonly amount: number;
  readonly appointmentId: number;
  readonly onSuccess: (payment: PaymentResponse) => void;
}

const PAYMENT_ERROR_MESSAGES: Record<string, string> = {
  insufficient_funds: "Fondos insuficientes",
  invalid_card: "Tarjeta inv├ílida",
  expired_card: "Tarjeta expirada",
};

function parseExpiry(expiry: string): { month: number; year: number } | null {
  const match = /^(\d{2})\/(\d{2})$/.exec(expiry);
  if (!match) return null;
  const month = parseInt(match[1], 10);
  const year = parseInt(match[2], 10) + 2000;
  if (month < 1 || month > 12) return null;
  return { month, year };
}

function isExpiryInFuture(expiry: string): boolean {
  const parsed = parseExpiry(expiry);
  if (!parsed) return false;
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth() + 1; // 1-based
  if (parsed.year > currentYear) return true;
  if (parsed.year === currentYear && parsed.month >= currentMonth) return true;
  return false;
}

/**
 * Credit/debit card payment form.
 * CVV is stored only in local state and cleared immediately after the API call.
 */
export function CardPaymentForm({
  amount,
  appointmentId,
  onSuccess,
}: CardPaymentFormProps) {
  const [cardNumber, setCardNumber] = useState("");
  const [cardholderName, setCardholderName] = useState("");
  const [expiry, setExpiry] = useState("");
  const [cvv, setCvv] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isExpired, setIsExpired] = useState(false);

  const { key, regenerate } = useIdempotencyKey();
  const { validate: validateLuhn } = useLuhnValidator();
  const { remaining } = usePaymentTimer(
    10,
    useCallback(() => setIsExpired(true), []),
  );

  const mutation = useMutation({
    mutationFn: createPayment,
  });

  const formattedAmount = new Intl.NumberFormat("es-GT", {
    style: "currency",
    currency: "GTQ",
  }).format(amount);

  function validate(): boolean {
    const newErrors: Record<string, string> = {};

    // Card number: 13ÔÇô19 digits, passes Luhn
    const digits = cardNumber.replace(/\s/g, "");
    if (!/^\d{13,19}$/.test(digits)) {
      newErrors.cardNumber =
        "El n├║mero de tarjeta debe tener entre 13 y 19 d├¡gitos";
    } else if (!validateLuhn(digits)) {
      newErrors.cardNumber = "El n├║mero de tarjeta no es v├ílido";
    }

    // Cardholder name: 5ÔÇô100 chars
    if (
      cardholderName.trim().length < 5 ||
      cardholderName.trim().length > 100
    ) {
      newErrors.cardholderName =
        "El nombre debe tener entre 5 y 100 caracteres";
    }

    // Expiry: MM/YY format, not in the past
    if (!/^\d{2}\/\d{2}$/.test(expiry)) {
      newErrors.expiry = "Formato inv├ílido. Use MM/AA";
    } else if (!isExpiryInFuture(expiry)) {
      newErrors.expiry = "La tarjeta est├í vencida";
    }

    // CVV: 3ÔÇô4 digits
    if (!/^\d{3,4}$/.test(cvv)) {
      newErrors.cvv = "El CVV debe tener 3 o 4 d├¡gitos";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (isExpired) return;
    if (!validate()) return;

    const digits = cardNumber.replace(/\s/g, "");

    try {
      const response = await mutation.mutateAsync({
        appointmentId,
        amount,
        paymentMethod: 1,
        paymentType: 0,
        idempotencyKey: key,
        cardLastFourDigits: digits.slice(-4),
        state: 1,
      });

      // Clear CVV immediately after API call ÔÇö before any other action
      setCvv("");

      if (response.success && response.data) {
        onSuccess(response.data);
      } else {
        const errorKey =
          response.message?.toLowerCase().replace(/\s+/g, "_") ?? "";
        const friendlyMessage =
          PAYMENT_ERROR_MESSAGES[errorKey] ??
          PAYMENT_ERROR_MESSAGES[response.message ?? ""] ??
          response.message ??
          "Error al procesar el pago";
        toast.danger(friendlyMessage);
        regenerate();
      }
    } catch {
      // CVV already cleared above in the try block; ensure it's cleared on error too
      setCvv("");
      toast.danger("Error al procesar el pago. Intente nuevamente.");
      regenerate();
    }
  }

  function handleCardNumberChange(e: React.ChangeEvent<HTMLInputElement>) {
    // Allow only digits, max 19
    const value = e.target.value.replace(/\D/g, "").slice(0, 19);
    setCardNumber(value);
  }

  function handleExpiryChange(e: React.ChangeEvent<HTMLInputElement>) {
    let value = e.target.value.replace(/\D/g, "");
    if (value.length > 4) value = value.slice(0, 4);
    if (value.length >= 3) {
      value = `${value.slice(0, 2)}/${value.slice(2)}`;
    }
    setExpiry(value);
  }

  if (isExpired) {
    return (
      <div className="rounded-lg border border-red-300 bg-red-50 p-6 text-center">
        <p className="text-lg font-bold text-red-700">
          La sesi├│n de pago ha expirado.
        </p>
        <p className="mt-1 text-sm text-red-600">
          Por favor, recargue la p├ígina para iniciar una nueva sesi├│n.
        </p>
      </div>
    );
  }

  return (
    <form noValidate className="space-y-5" onSubmit={handleSubmit}>
      {/* Timer */}
      <div className="flex justify-center">
        <CountdownTimer label="Sesi├│n de pago" remaining={remaining} />
      </div>

      {/* Amount */}
      <div className="rounded-lg bg-blue-50 border border-blue-200 p-4 text-center">
        <p className="text-sm font-medium text-blue-700">Monto a pagar</p>
        <p className="text-3xl font-bold text-blue-900">{formattedAmount}</p>
      </div>

      {/* Card number */}
      <div>
        <label
          className="block text-sm font-semibold text-gray-700 mb-1"
          htmlFor="cardNumber"
        >
          N├║mero de tarjeta
        </label>
        <input
          className={`w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            errors.cardNumber ? "border-red-400 bg-red-50" : "border-gray-300"
          }`}
          disabled={mutation.isPending}
          id="cardNumber"
          inputMode="numeric"
          maxLength={19}
          placeholder="1234 5678 9012 3456"
          type="text"
          value={cardNumber}
          onChange={handleCardNumberChange}
        />
        {/* Masked display */}
        {cardNumber.length > 0 && (
          <p className="mt-1 font-mono text-sm text-gray-500 tracking-widest">
            {maskCardNumber(cardNumber)}
          </p>
        )}
        {errors.cardNumber ? (
          <p className="mt-1 text-xs text-red-600">{errors.cardNumber}</p>
        ) : null}
      </div>

      {/* Cardholder name */}
      <div>
        <label
          className="block text-sm font-semibold text-gray-700 mb-1"
          htmlFor="cardholderName"
        >
          Nombre del titular
        </label>
        <input
          className={`w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            errors.cardholderName
              ? "border-red-400 bg-red-50"
              : "border-gray-300"
          }`}
          disabled={mutation.isPending}
          id="cardholderName"
          placeholder="Como aparece en la tarjeta"
          type="text"
          value={cardholderName}
          onChange={(e) => setCardholderName(e.target.value)}
        />
        {errors.cardholderName ? (
          <p className="mt-1 text-xs text-red-600">{errors.cardholderName}</p>
        ) : null}
      </div>

      {/* Expiry + CVV row */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label
            className="block text-sm font-semibold text-gray-700 mb-1"
            htmlFor="expiry"
          >
            Vencimiento
          </label>
          <input
            className={`w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
              errors.expiry ? "border-red-400 bg-red-50" : "border-gray-300"
            }`}
            disabled={mutation.isPending}
            id="expiry"
            maxLength={5}
            placeholder="MM/AA"
            type="text"
            value={expiry}
            onChange={handleExpiryChange}
          />
          {errors.expiry ? (
            <p className="mt-1 text-xs text-red-600">{errors.expiry}</p>
          ) : null}
        </div>

        <div>
          <label
            className="block text-sm font-semibold text-gray-700 mb-1"
            htmlFor="cvv"
          >
            CVV
          </label>
          <input
            autoComplete="off"
            className={`w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
              errors.cvv ? "border-red-400 bg-red-50" : "border-gray-300"
            }`}
            disabled={mutation.isPending}
            id="cvv"
            maxLength={4}
            placeholder="ÔÇóÔÇóÔÇó"
            type="password"
            value={cvv}
            onChange={(e) =>
              setCvv(e.target.value.replace(/\D/g, "").slice(0, 4))
            }
          />
          {errors.cvv ? (
            <p className="mt-1 text-xs text-red-600">{errors.cvv}</p>
          ) : null}
        </div>
      </div>

      {/* Submit */}
      <AsyncButton
        className="w-full"
        isDisabled={isExpired}
        isLoading={mutation.isPending}
        size="lg"
        type="submit"
        variant="primary"
      >
        Pagar {formattedAmount}
      </AsyncButton>
    </form>
  );
}

import { useCallback, useState } from "react";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import type { UseAppointmentHubReturn } from "../../hooks/useAppointmentHub";
import { getDoctorAvailability } from "../../services/patientPortalService";
import { formatDateLong } from "../../utils/dateFormatter";

interface DynamicCalendarProps {
  readonly doctorId: number;
  readonly onSlotSelected: (dateTime: Date) => void;
  /** Optional SignalR hub state ÔÇö when provided, enables real-time slot blocking */
  readonly hub?: UseAppointmentHubReturn;
  /** The currently selected date (controlled from parent for hub group management) */
  readonly onDateChange?: (date: string | null) => void;
}

/**
 * Returns true if the 30-minute window starting at slotStart overlaps with
 * any of the occupied slots (each also treated as a 30-minute window).
 */
const isSlotOccupied = (slotStart: Date, occupiedSlots: string[]): boolean => {
  const slotEnd = new Date(slotStart.getTime() + 30 * 60 * 1000);
  return occupiedSlots.some((occupied) => {
    const occStart = new Date(occupied);
    const occEnd = new Date(occStart.getTime() + 30 * 60 * 1000);
    return slotStart < occEnd && slotEnd > occStart;
  });
};

/** Generate all 30-minute slots from 07:00 to 18:30 for the given date. */
const generateSlots = (date: Date): Date[] => {
  const slots: Date[] = [];
  // Start at 07:00, end at 18:30 (last slot starts at 18:30)
  for (let hour = 7; hour <= 18; hour++) {
    const minutes = hour === 18 ? [0, 30] : [0, 30];
    for (const minute of minutes) {
      if (hour === 18 && minute > 30) break;
      const slot = new Date(date);
      slot.setHours(hour, minute, 0, 0);
      slots.push(slot);
    }
  }
  return slots;
};

/** Format a Date as "yyyy-MM-dd" for the API call. */
const formatDateForApi = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

/** Format a Date as "HH:MM" for display. */
const formatTime = (date: Date): string => {
  const hours = String(date.getHours()).padStart(2, "0");
  const minutes = String(date.getMinutes()).padStart(2, "0");
  return `${hours}:${minutes}`;
};

export function DynamicCalendar({
  doctorId,
  onSlotSelected,
  hub,
  onDateChange,
}: DynamicCalendarProps) {
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [occupiedSlots, setOccupiedSlots] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);

  // Use hub state from props (or fallback to empty defaults if not provided)
  const connectionState = hub?.connectionState ?? "disconnected";
  const lockedSlots = hub?.lockedSlots ?? new Map();
  const confirmedSlots = hub?.confirmedSlots ?? new Set();
  const myLockedSlot = hub?.myLockedSlot ?? null;
  const lockSlot = hub?.lockSlot;
  const hubError = hub?.error ?? null;

  const handleDateChange = useCallback(
    async (value: Date) => {
      setSelectedDate(value);
      setSelectedSlot(null);
      onDateChange?.(formatDateForApi(value));
      setLoading(true);
      try {
        const formattedDate = formatDateForApi(value);
        const response = await getDoctorAvailability(doctorId, formattedDate);
        if (response.success && response.data) {
          setOccupiedSlots(response.data.occupiedSlots ?? []);
        } else {
          setOccupiedSlots([]);
        }
      } catch {
        setOccupiedSlots([]);
      } finally {
        setLoading(false);
      }
    },
    [doctorId, onDateChange],
  );

  const handleSlotClick = useCallback(
    async (slot: Date) => {
      const time = formatTime(slot);
      if (lockSlot) {
        await lockSlot(time);
      }
      setSelectedSlot(slot);
      onSlotSelected(slot);
    },
    [onSlotSelected, lockSlot],
  );

  const now = new Date();
  const allSlots = selectedDate ? generateSlots(selectedDate) : [];

  return (
    <div className="flex flex-col gap-4">
      {/* react-calendar */}
      <div className="flex justify-center">
        <Calendar
          minDate={new Date()}
          value={selectedDate}
          onChange={(value) => {
            if (value instanceof Date) {
              void handleDateChange(value);
            }
          }}
        />
      </div>

      {/* Slot grid */}
      {selectedDate ? (
        <div className="mt-2">
          <h3 className="mb-2 font-semibold text-gray-700">
            Horarios disponibles para el{" "}
            {formatDateLong(selectedDate.toISOString())}
          </h3>

          {/* Connection state indicator */}
          {connectionState === "reconnecting" && (
            <div className="text-sm text-amber-600">Reconectando...</div>
          )}
          {connectionState === "disconnected" && selectedDate ? (
            <div className="text-sm text-red-500">
              Desconectado ÔÇö los horarios pueden no estar actualizados
            </div>
          ) : null}

          {/* Hub error */}
          {hubError ? (
            <div className="text-sm text-red-500">{hubError}</div>
          ) : null}

          {loading ? (
            <div className="flex items-center justify-center py-6">
              <span className="text-sm text-gray-500">
                Cargando disponibilidad...
              </span>
            </div>
          ) : (
            <div className="grid grid-cols-4 gap-2 sm:grid-cols-6">
              {allSlots.map((slot) => {
                const time = formatTime(slot);
                const isPast = slot <= now;
                const occupied = isSlotOccupied(slot, occupiedSlots);
                const isConfirmed = confirmedSlots.has(time);
                const isLockedByOther = lockedSlots.has(time);
                const isSelected = myLockedSlot === time;
                const disabled =
                  isPast || occupied || isLockedByOther || isConfirmed;

                let buttonClass =
                  "rounded px-2 py-1 text-sm font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-1 ";

                if (isSelected) {
                  buttonClass += "bg-blue-600 text-white focus:ring-blue-500";
                } else if (isLockedByOther) {
                  buttonClass +=
                    "cursor-not-allowed bg-amber-100 text-amber-600";
                } else if (isPast || occupied || isConfirmed) {
                  buttonClass += "cursor-not-allowed bg-gray-100 text-gray-400";
                } else {
                  buttonClass +=
                    "bg-green-100 text-green-800 hover:bg-green-200 focus:ring-green-500";
                }

                return (
                  <button
                    key={slot.toISOString()}
                    aria-label={`Slot ${time}${
                      isLockedByOther
                        ? " - reservado temporalmente por otro paciente"
                        : occupied || isConfirmed
                          ? " - ocupado"
                          : isPast
                            ? " - pasado"
                            : " - disponible"
                    }`}
                    aria-pressed={isSelected}
                    className={buttonClass}
                    disabled={disabled}
                    title={
                      isLockedByOther
                        ? "Reservado temporalmente por otro paciente"
                        : undefined
                    }
                    type="button"
                    onClick={() => void handleSlotClick(slot)}
                  >
                    {time}
                    {isLockedByOther ? (
                      <span className="sr-only">
                        Reservado temporalmente por otro paciente
                      </span>
                    ) : null}
                  </button>
                );
              })}
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import { z } from "zod";
import { processPatientPayment } from "../../services/patientPortalService";
import type {
  PatientPaymentRequest,
  PaymentConfirmationResponse,
} from "../../types/PatientPortalTypes";
import { luhnCheck } from "../../utils/luhn";

interface PaymentFormProps {
  readonly appointmentId: number;
  readonly amount: number;
  readonly onPaymentSuccess: (
    confirmation: PaymentConfirmationResponse,
  ) => void;
  readonly onPaymentError: (message: string) => void;
}

// ---------------------------------------------------------------------------
// Zod schema (zod v4 uses `error` instead of `message`)
// ---------------------------------------------------------------------------
const paymentSchema = z.object({
  cardNumber: z
    .string()
    .regex(/^\d{13,19}$/, {
      error: "El n├║mero de tarjeta debe tener entre 13 y 19 d├¡gitos",
    })
    .refine(luhnCheck, { error: "El n├║mero de tarjeta no es v├ílido" }),
  cardHolder: z
    .string()
    .min(5, { error: "El nombre del titular debe tener al menos 5 caracteres" })
    .max(100, {
      error: "El nombre del titular no puede exceder 100 caracteres",
    }),
  expiry: z
    .string()
    .regex(/^(0[1-9]|1[0-2])\/\d{2}$/, { error: "Formato inv├ílido. Use MM/AA" })
    .refine(
      (val) => {
        const [month, year] = val.split("/");
        const expDate = new Date(
          2000 + parseInt(year, 10),
          parseInt(month, 10) - 1,
        );
        return expDate > new Date();
      },
      { error: "La tarjeta est├í vencida" },
    ),
  cvv: z
    .string()
    .regex(/^\d{3,4}$/, { error: "El CVV debe tener 3 o 4 d├¡gitos" }),
});

type PaymentFormErrors = Partial<
  Record<keyof z.infer<typeof paymentSchema>, string>
>;

/** Mask card number: show only last 4 digits as ****-****-****-XXXX */
const maskCardNumber = (raw: string): string => {
  const digits = raw.replace(/\D/g, "");
  if (digits.length < 4) return raw;
  const last4 = digits.slice(-4);
  const maskedGroups = Math.ceil((digits.length - 4) / 4);
  const masked = Array(maskedGroups).fill("****").join("-");
  return `${masked}-${last4}`;
};

/** Determine payment method: 1 = Visa (starts with 4), 2 = Mastercard (starts with 5) */
const getPaymentMethod = (cardNumber: string): number => {
  if (cardNumber.startsWith("4")) return 1;
  if (cardNumber.startsWith("5")) return 2;
  return 1;
};

export function PaymentForm({
  appointmentId,
  amount,
  onPaymentSuccess,
  onPaymentError,
}: PaymentFormProps) {
  // Raw card number (digits only) ÔÇö used for validation and submission
  const rawCardNumberRef = useRef<string>("");

  const [cardNumberDisplay, setCardNumberDisplay] = useState("");
  const [isMasked, setIsMasked] = useState(false);
  const [cardHolder, setCardHolder] = useState("");
  const [expiry, setExpiry] = useState("");
  const [cvv, setCvv] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<PaymentFormErrors>({});

  // idempotencyKey is generated once on mount and never regenerated
  const idempotencyKey = useRef<string>(uuidv4());

  // Keep idempotencyKey stable across re-renders
  useEffect(() => {
    idempotencyKey.current = uuidv4();
  }, []);

  // ---------------------------------------------------------------------------
  // Card number handlers
  // ---------------------------------------------------------------------------
  const handleCardNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value.replace(/\D/g, "");
    rawCardNumberRef.current = raw;
    setCardNumberDisplay(raw);
    setIsMasked(false);
  };

  const handleCardNumberBlur = () => {
    if (rawCardNumberRef.current.length >= 4) {
      setCardNumberDisplay(maskCardNumber(rawCardNumberRef.current));
      setIsMasked(true);
    }
  };

  const handleCardNumberFocus = () => {
    if (isMasked) {
      setCardNumberDisplay(rawCardNumberRef.current);
      setIsMasked(false);
    }
  };

  // ---------------------------------------------------------------------------
  // Expiry auto-format: insert "/" after 2 digits
  // ---------------------------------------------------------------------------
  const handleExpiryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.replace(/\D/g, "");
    if (val.length > 4) val = val.slice(0, 4);
    if (val.length >= 3) {
      val = `${val.slice(0, 2)}/${val.slice(2)}`;
    }
    setExpiry(val);
  };

  // ---------------------------------------------------------------------------
  // Submit
  // ---------------------------------------------------------------------------
  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const formData = {
      cardNumber: rawCardNumberRef.current,
      cardHolder,
      expiry,
      cvv,
    };

    const result = paymentSchema.safeParse(formData);

    if (!result.success) {
      const fieldErrors: PaymentFormErrors = {};
      for (const issue of result.error.issues) {
        const field = issue.path[0] as keyof PaymentFormErrors;
        if (!fieldErrors[field]) {
          fieldErrors[field] = issue.message;
        }
      }
      setErrors(fieldErrors);
      return;
    }

    setErrors({});
    setIsSubmitting(true);

    // Clear CVV from state immediately ÔÇö it must never be sent to the backend
    setCvv("");

    const cardNumber = rawCardNumberRef.current;
    const cardLastFourDigits = cardNumber.slice(-4);
    const paymentMethod = getPaymentMethod(cardNumber);

    const request: PatientPaymentRequest = {
      appointmentId,
      amount,
      paymentMethod,
      paymentType: 0, // Consulta
      paymentStatus: 0, // Pendiente
      paymentDate: new Date().toISOString(),
      cardLastFourDigits,
      idempotencyKey: idempotencyKey.current,
    };

    try {
      const response = await processPatientPayment(request);
      if (response.success && response.data) {
        onPaymentSuccess(response.data);
      } else {
        const rawMsg = response.message ?? "";
        let msg: string;
        if (
          rawMsg.toLowerCase().includes("rechaz") ||
          rawMsg.toLowerCase().includes("declined")
        ) {
          msg =
            "La transacci├│n con tarjeta fue rechazada por el banco. Verifique los datos de su tarjeta o utilice otro m├®todo de pago.";
        } else {
          msg =
            rawMsg ||
            "El pago no pudo ser procesado. Por favor, intente nuevamente o utilice otro m├®todo de pago.";
        }
        onPaymentError(msg);
      }
    } catch {
      onPaymentError(
        "Error de comunicaci├│n con la pasarela de pago. Por favor, verifique su conexi├│n e intente nuevamente.",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------
  return (
    <form
      noValidate
      className="flex flex-col gap-4"
      onSubmit={(e) => void handleSubmit(e)}
    >
      <h2 className="text-lg font-bold text-gray-800">Datos de pago</h2>

      {/* Card Number */}
      <div className="flex flex-col gap-1">
        <label
          className="text-sm font-medium text-gray-700"
          htmlFor="cardNumber"
        >
          N├║mero de tarjeta
        </label>
        <input
          autoComplete="cc-number"
          className={`w-full rounded-md border px-3 py-2 text-sm focus:outline-none focus:ring-2 ${
            errors.cardNumber
              ? "border-red-400 focus:ring-red-400"
              : "border-gray-300 focus:ring-blue-400"
          }`}
          id="cardNumber"
          inputMode="numeric"
          maxLength={19}
          name="cardNumber"
          placeholder="1234 5678 9012 3456"
          type="text"
          value={cardNumberDisplay}
          onBlur={handleCardNumberBlur}
          onChange={handleCardNumberChange}
          onFocus={handleCardNumberFocus}
        />
        {errors.cardNumber ? (
          <span className="text-xs text-red-500" role="alert">
            {errors.cardNumber}
          </span>
        ) : null}
      </div>

      {/* Card Holder */}
      <div className="flex flex-col gap-1">
        <label
          className="text-sm font-medium text-gray-700"
          htmlFor="cardHolder"
        >
          Nombre del titular
        </label>
        <input
          autoComplete="cc-name"
          className={`w-full rounded-md border px-3 py-2 text-sm focus:outline-none focus:ring-2 ${
            errors.cardHolder
              ? "border-red-400 focus:ring-red-400"
              : "border-gray-300 focus:ring-blue-400"
          }`}
          id="cardHolder"
          name="cardHolder"
          placeholder="JUAN PEREZ"
          type="text"
          value={cardHolder}
          onChange={(e) => setCardHolder(e.target.value.toUpperCase())}
        />
        {errors.cardHolder ? (
          <span className="text-xs text-red-500" role="alert">
            {errors.cardHolder}
          </span>
        ) : null}
      </div>

      {/* Expiry + CVV row */}
      <div className="flex gap-4">
        {/* Expiry */}
        <div className="flex flex-1 flex-col gap-1">
          <label className="text-sm font-medium text-gray-700" htmlFor="expiry">
            Vencimiento (MM/AA)
          </label>
          <input
            autoComplete="cc-exp"
            className={`w-full rounded-md border px-3 py-2 text-sm focus:outline-none focus:ring-2 ${
              errors.expiry
                ? "border-red-400 focus:ring-red-400"
                : "border-gray-300 focus:ring-blue-400"
            }`}
            id="expiry"
            inputMode="numeric"
            maxLength={5}
            name="expiry"
            placeholder="MM/AA"
            type="text"
            value={expiry}
            onChange={handleExpiryChange}
          />
          {errors.expiry ? (
            <span className="text-xs text-red-500" role="alert">
              {errors.expiry}
            </span>
          ) : null}
        </div>

        {/* CVV ÔÇö type="password", never sent to backend */}
        <div className="flex flex-1 flex-col gap-1">
          <label className="text-sm font-medium text-gray-700" htmlFor="cvv">
            CVV
          </label>
          <input
            autoComplete="cc-csc"
            className={`w-full rounded-md border px-3 py-2 text-sm focus:outline-none focus:ring-2 ${
              errors.cvv
                ? "border-red-400 focus:ring-red-400"
                : "border-gray-300 focus:ring-blue-400"
            }`}
            id="cvv"
            inputMode="numeric"
            maxLength={4}
            name="cvv"
            placeholder="ÔÇóÔÇóÔÇó"
            type="password"
            value={cvv}
            onChange={(e) => setCvv(e.target.value.replace(/\D/g, ""))}
          />
          {errors.cvv ? (
            <span className="text-xs text-red-500" role="alert">
              {errors.cvv}
            </span>
          ) : null}
        </div>
      </div>

      {/* Security note */}
      <p className="text-xs text-gray-500">
        <span aria-hidden="true">­ƒöÆ </span>
        Tu informaci├│n de pago est├í protegida. El CVV nunca se almacena ni se
        env├¡a.
      </p>

      {/* Submit */}
      <button
        className="mt-2 w-full rounded-md bg-blue-600 px-4 py-3 font-semibold text-white transition-colors hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
        disabled={isSubmitting}
        type="submit"
      >
        {isSubmitting ? "Procesando pago..." : `Pagar Q${amount.toFixed(2)}`}
      </button>
    </form>
  );
}

