export function CreateAppointmentPage() {
  const navigate = useNavigate();
  const { userId } = useAuth();

  const [wizard, setWizard] = useState<WizardState>({
    step: 1,
    patient: null,
    branch: null,
    specialty: null,
    doctor: null,
    appointmentDate: null,
  });

  const [slotConflictError, setSlotConflictError] = useState(false);

  // -- handlers ---------------------------------------------------------------
  const handlePatientSelect = useCallback(
    (patient: { id: number; name: string }) =>
      setWizard((prev) => ({ ...prev, step: 2, patient })),
    [],
  );

  const handleBranchSelect = useCallback(
    (branch: BranchResponse) =>
      setWizard((prev) => ({ ...prev, step: 3, branch })),
    [],
  );

  const handleSpecialtySelect = useCallback(
    (specialty: SpecialtyResponse) =>
      setWizard((prev) => ({ ...prev, step: 4, specialty })),
    [],
  );

  const handleDoctorSelect = useCallback(
    (doctor: DoctorResponse) =>
      setWizard((prev) => ({ ...prev, step: 5, doctor })),
    [],
  );

  const handleSlotSelect = useCallback((dateTime: Date) => {
    setSlotConflictError(false);
    setWizard((prev) => ({ ...prev, step: 6, appointmentDate: dateTime }));
  }, []);

  const handleConfirm = useCallback(
    async (reason: string) => {
      if (
        !wizard.patient ||
        !wizard.branch ||
        !wizard.specialty ||
        !wizard.doctor ||
        !wizard.appointmentDate
      ) {
        throw new Error(
          "Datos incompletos. Por favor, complete todos los pasos.",
        );
      }

      const response = await createAppointment({
        patientId: wizard.patient.id,
        doctorId: wizard.doctor.id,
        specialtyId: wizard.specialty.id,
        branchId: wizard.branch.id,
        appointmentDate: wizard.appointmentDate.toISOString(),
        reason,
        amount: CONSULTATION_FEE,
        state: 1,
        createdBy: userId,
      });

      if (response.success) {
        toast.success("Cita agendada correctamente");
        navigate(nameRoutes.appointment);
      } else {
        const isConflict =
          response.message?.toLowerCase().includes("disponible") ||
          response.message?.toLowerCase().includes("ocupado") ||
          response.message?.toLowerCase().includes("409");

        if (isConflict) {
          setSlotConflictError(true);
          setWizard((prev) => ({ ...prev, step: 5 }));
          throw new Error("El horario seleccionado ya no est├í disponible");
        }

        throw new Error(
          response.message ?? "Error al confirmar la cita. Intente de nuevo.",
        );
      }
    },
    [wizard, userId, navigate],
  );

  // -- render -----------------------------------------------------------------
  return (
    <section className="min-h-[calc(100vh-140px)] bg-gray-50 px-4 py-10 dark:bg-gray-900">
      <div className="mx-auto max-w-3xl">
        {/* Header */}
        <div className="mb-6 text-center">
          <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
            <i className="bi bi-calendar-plus mr-2 text-blue-600" />
            Crear Nueva Cita
          </h1>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
            Complete los pasos para agendar una cita desde el panel
            administrativo.
          </p>
        </div>

        <StepIndicator current={wizard.step} total={TOTAL_STEPS} />

        {/* Slot conflict banner */}
        {slotConflictError ? (
          <div className="mb-6 rounded-xl border border-red-300 bg-red-50 p-4 text-sm text-red-800 dark:border-red-700 dark:bg-red-900/20 dark:text-red-300">
            <i className="bi bi-exclamation-triangle-fill mr-2" />
            El horario seleccionado ya no est├í disponible. Por favor, elija otro
            horario.
          </div>
        ) : null}

        {/* Wizard card */}
        <div className="rounded-2xl border border-gray-100 bg-white p-6 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          {wizard.step === 1 && <Step1Patient onSelect={handlePatientSelect} />}

          {wizard.step === 2 && (
            <Step2Branch
              onBack={() => setWizard((prev) => ({ ...prev, step: 1 }))}
              onSelect={handleBranchSelect}
            />
          )}

          {wizard.step === 3 && wizard.branch ? (
            <Step3Specialty
              branchId={wizard.branch.id}
              branchName={wizard.branch.name}
              onBack={() => setWizard((prev) => ({ ...prev, step: 2 }))}
              onSelect={handleSpecialtySelect}
            />
          ) : null}

          {wizard.step === 4 && wizard.branch && wizard.specialty ? (
            <Step4Doctor
              branchId={wizard.branch.id}
              branchName={wizard.branch.name}
              specialtyId={wizard.specialty.id}
              specialtyName={wizard.specialty.name}
              onBack={() => setWizard((prev) => ({ ...prev, step: 3 }))}
              onSelect={handleDoctorSelect}
            />
          ) : null}

          {wizard.step === 5 &&
          wizard.doctor &&
          wizard.specialty &&
          wizard.branch ? (
            <Step5Slot
              branchName={wizard.branch.name}
              doctorId={wizard.doctor.id}
              doctorName={wizard.doctor.name}
              specialtyName={wizard.specialty.name}
              onBack={() => setWizard((prev) => ({ ...prev, step: 4 }))}
              onSelect={handleSlotSelect}
            />
          ) : null}

          {wizard.step === 6 &&
          wizard.patient &&
          wizard.branch &&
          wizard.specialty &&
          wizard.doctor &&
          wizard.appointmentDate ? (
            <Step6Confirm
              summary={{
                patientId: wizard.patient.id,
                patientName: wizard.patient.name,
                branchId: wizard.branch.id,
                branchName: wizard.branch.name,
                specialtyId: wizard.specialty.id,
                specialtyName: wizard.specialty.name,
                doctorId: wizard.doctor.id,
                doctorName: wizard.doctor.name,
                appointmentDate: wizard.appointmentDate,
              }}
              onBack={() => setWizard((prev) => ({ ...prev, step: 5 }))}
              onConfirm={handleConfirm}
            />
          ) : null}
        </div>
      </div>
    </section>
  );
}

import { Button, toast } from "@heroui/react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback } from "react";
import { useNavigate, useParams } from "react-router";
import { AppointmentForm } from "../../components/form/AppointmentForm";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { nameRoutes } from "../../configs/constants";
import {
  getAppointmentById,
  updateAppointment,
} from "../../services/appointmentService";
import type { AppointmentRequest } from "../../types/AppointmentResponse";
import { validationFailureToString } from "../../utils/converted";

export function UpdateAppointmentPage() {
  const { id } = useParams();
  const client = useQueryClient();
  const navigate = useNavigate();

  const { data, isLoading, error } = useQuery({
    queryKey: ["appointmentToUpdate", id],
    queryFn: () => getAppointmentById(Number(id)),
  });

  const onSubmit = useCallback(
    async (form: AppointmentRequest) => {
      const response = await updateAppointment(form);
      if (!response.success) {
        toast.danger(
          `${response.message} ${validationFailureToString(response.data)}`,
        );
        return response;
      }
      await client.invalidateQueries({ queryKey: ["appointments"] });
      await client.invalidateQueries({ queryKey: ["appointmentToUpdate", id] });
      toast.success("Cita actualizada correctamente");
      return response;
    },
    [client, id],
  );

  if (isLoading) return <LoadingComponent />;

  return (
    <div>
      {data?.success ? (
        <>
          {data.data.appointmentStatus?.name === "Pagada" && (
            <div className="max-w-3xl mx-auto px-4 pt-4 flex justify-end">
              <Button
                size="sm"
                variant="secondary"
                onPress={() =>
                  navigate(
                    `${nameRoutes.appointmentReassign}?appointmentId=${id}`,
                  )
                }
              >
                <i className="bi bi-person-check mr-2" />
                Reasignar M├®dico
              </Button>
            </div>
          )}
          <AppointmentForm
            initialForm={data.data}
            type="edit"
            onSubmit={onSubmit}
          />
        </>
      ) : (
        <div>
          Error: {error instanceof Error ? error.message : "Error desconocido"}
        </div>
      )}
    </div>
  );
}

import { useCallback, useState, type FormEvent } from "react";
import { Link } from "react-router";
import { z } from "zod";

