import { toast } from "@heroui/react";
import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useNavigate } from "react-router";
import type { SingleValue } from "react-select";
import { AsyncButton } from "../../components/button/AsyncButton";
import { CatalogueSelect } from "../../components/select/CatalogueSelect";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import { getBranches } from "../../services/branchService";
import { createBranchSpecialty } from "../../services/branchSpecialtyService";
import { getSpecialties } from "../../services/specialtyService";
import type { BranchResponse } from "../../types/BranchResponse";
import type { SpecialtyResponse } from "../../types/SpecialtyResponse";

export function CreateBranchSpecialtyPage() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { userId } = useAuth();

  const [branchId, setBranchId] = useState<number | null>(null);
  const [specialtyId, setSpecialtyId] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const selectorBranch = useCallback(
    (item: BranchResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const selectorSpecialty = useCallback(
    (item: SpecialtyResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const handleSubmit = useCallback(async () => {
    setError(null);
    if (!branchId) {
      setError("Debe seleccionar una sede.");
      return;
    }
    if (!specialtyId) {
      setError("Debe seleccionar una especialidad.");
      return;
    }

    setLoading(true);
    try {
      const response = await createBranchSpecialty({
        branchId,
        specialtyId,
        state: 1,
        createdBy: userId,
      });

      if (response.success) {
        toast.success("Especialidad asignada a la sede correctamente");
        await queryClient.invalidateQueries({
          queryKey: ["branch-specialties"],
        });
        navigate(nameRoutes.branchSpecialty);
      } else {
        setError(response.message ?? "Error al crear la asignaci├│n");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error inesperado");
    } finally {
      setLoading(false);
    }
  }, [branchId, specialtyId, userId, navigate, queryClient]);

  return (
    <div className="max-w-lg mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        Asignar Especialidad a Sede
      </h1>

      <div className="flex flex-col gap-5">
        <CatalogueSelect<BranchResponse>
          isRequired
          defaultValue={null}
          deps="State:eq:1"
          fieldSearch="Name"
          label="Sede"
          name="branchId"
          placeholder="Seleccione una sede"
          queryFn={getBranches}
          selectorFn={selectorBranch}
          onChange={(opt) => {
            const o = opt as SingleValue<{ label: string; value: string }>;
            setBranchId(o?.value ? Number(o.value) : null);
          }}
        />

        <CatalogueSelect<SpecialtyResponse>
          isRequired
          defaultValue={null}
          deps="State:eq:1"
          fieldSearch="Name"
          label="Especialidad"
          name="specialtyId"
          placeholder="Seleccione una especialidad"
          queryFn={getSpecialties}
          selectorFn={selectorSpecialty}
          onChange={(opt) => {
            const o = opt as SingleValue<{ label: string; value: string }>;
            setSpecialtyId(o?.value ? Number(o.value) : null);
          }}
        />

        {error ? (
          <p className="text-sm text-red-600 flex items-center gap-1">
            <i className="bi bi-exclamation-circle" />
            {error}
          </p>
        ) : null}

        <div className="flex gap-3 justify-end mt-2">
          <AsyncButton
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() => navigate(nameRoutes.branchSpecialty)}
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            isLoading={loading}
            loadingText="Guardando..."
            size="lg"
            type="button"
            variant="primary"
            onClick={handleSubmit}
          >
            Asignar
          </AsyncButton>
        </div>
      </div>
    </div>
  );
}

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { OptionsSelect } from "../../components/select/OptionsSelect";
import { PaymentReceipt } from "../../components/shared/PaymentReceipt";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { getAppointments } from "../../services/appointmentService";
import { createPayment } from "../../services/paymentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import type {
  PaymentRequest,
  PaymentResponse,
} from "../../types/PaymentResponse";
import { calculateChange } from "../../utils/calculateChange";
import { generateIdempotencyKey } from "../../utils/generateIdempotencyKey";

const PAYMENT_METHODS = [
  { label: "Efectivo (Q)", value: "0" },
  { label: "Visa", value: "1" },
  { label: "Mastercard", value: "2" },
  { label: "D├®bito", value: "3" },
];

export function CashierPage() {
  const [searchValue, setSearchValue] = useState("");
  const [searchType, setSearchType] = useState<"dpi" | "id">("dpi");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedAppointment, setSelectedAppointment] =
    useState<AppointmentResponse | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<number>(0);
  const [amountReceived, setAmountReceived] = useState<string>("");
  const [cardLastFour, setCardLastFour] = useState<string>("");
  const [paymentSuccess, setPaymentSuccess] = useState<{
    payment: PaymentResponse;
    change: number;
  } | null>(null);
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ["cashier-search", searchQuery, searchType],
    queryFn: () => {
      if (!searchQuery)
        return Promise.resolve({
          success: true as const,
          data: [],
          message: "",
          totalResults: 0,
        });
      const filter =
        searchType === "dpi"
          ? `Patient.IdentificationDocument:eq:${searchQuery} AND AppointmentStatus.Name:eq:Pendiente`
          : `Id:eq:${searchQuery} AND AppointmentStatus.Name:eq:Pendiente`;
      return getAppointments({
        pageNumber: 1,
        pageSize: 20,
        filters: `${filter} AND State:eq:1`,
        include: "Specialty,Branch,AppointmentStatus,Patient",
        includeTotal: false,
      });
    },
    enabled: !!searchQuery,
  });

  const paymentMutation = useMutation({
    mutationFn: (paymentData: PaymentRequest) => createPayment(paymentData),
    onSuccess: (response) => {
      if (response.success && response.data) {
        const payment = response.data as PaymentResponse;
        const change =
          paymentMethod === 0
            ? Math.max(
                0,
                calculateChange(
                  Number(amountReceived),
                  selectedAppointment?.amount ?? 0,
                ),
              )
            : 0;
        setPaymentSuccess({ payment, change });
        const patientName = selectedAppointment?.patient?.name ?? "Paciente";
        toast.success(
          `┬íPago registrado exitosamente! Paciente: ${patientName}. La cita ha sido actualizada a estado "Pagada".`,
        );
        queryClient.invalidateQueries({ queryKey: ["cashier-search"] });
      } else {
        const msg = response.message ?? "";
        if (
          msg.toLowerCase().includes("rechaz") ||
          msg.toLowerCase().includes("declined")
        ) {
          toast.danger(
            "La transacci├│n con tarjeta fue rechazada por el banco. Solicite al paciente otro m├®todo de pago.",
          );
        } else {
          toast.danger(
            `Error al procesar el pago: ${msg || "Intente nuevamente."}`,
          );
        }
      }
    },
    onError: () =>
      toast.danger(
        "Error de comunicaci├│n con el sistema de pagos. Intente nuevamente.",
      ),
  });

  const handleSearch = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      if (!searchValue.trim()) {
        toast.danger("Ingrese un n├║mero de cita o DPI para buscar");
        return;
      }
      setSearchQuery(searchValue.trim());
      setSelectedAppointment(null);
      setPaymentSuccess(null);
    },
    [searchValue],
  );

  const handleSelectAppointment = useCallback(
    (appointment: AppointmentResponse) => {
      setSelectedAppointment(appointment);
      setPaymentSuccess(null);
      setAmountReceived(String(appointment.amount));
    },
    [],
  );

  const handlePay = useCallback(() => {
    if (!selectedAppointment) return;

    if (paymentMethod === 0) {
      const received = Number(amountReceived);
      if (received < selectedAppointment.amount) {
        toast.danger(
          `El monto recibido (Q${received}) es menor al monto a cobrar (Q${selectedAppointment.amount})`,
        );
        return;
      }
    }

    if (
      (paymentMethod === 1 || paymentMethod === 2 || paymentMethod === 3) &&
      cardLastFour.length !== 4
    ) {
      toast.danger("Ingrese los ├║ltimos 4 d├¡gitos de la tarjeta");
      return;
    }

    const paymentData: PaymentRequest = {
      appointmentId: selectedAppointment.id,
      amount: selectedAppointment.amount,
      paymentMethod,
      paymentType: 0, // Consulta
      paymentStatus: 1, // Completado
      paymentDate: new Date().toISOString(),
      idempotencyKey: generateIdempotencyKey(),
      amountReceived: paymentMethod === 0 ? Number(amountReceived) : null,
      changeAmount:
        paymentMethod === 0
          ? Math.max(
              0,
              calculateChange(
                Number(amountReceived),
                selectedAppointment.amount,
              ),
            )
          : null,
      cardLastFourDigits: paymentMethod !== 0 ? cardLastFour : null,
      state: 1,
    };

    paymentMutation.mutate(paymentData);
  }, [
    selectedAppointment,
    paymentMethod,
    amountReceived,
    cardLastFour,
    paymentMutation,
  ]);

  const appointments = data?.success ? data.data : [];
  const change =
    paymentMethod === 0 && selectedAppointment
      ? Math.max(
          0,
          calculateChange(Number(amountReceived), selectedAppointment.amount),
        )
      : 0;

  return (
    <div className="max-w-5xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-2">Cobro de Consulta en Caja</h1>
      <p className="text-gray-500 text-sm mb-6">
        Busque citas con estado "Pendiente de pago" para procesar el cobro.
      </p>

      {/* Buscador */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border p-6 mb-6">
        <form
          className="flex flex-col md:flex-row gap-3"
          onSubmit={handleSearch}
        >
          <div className="flex gap-2">
            <button
              className={`px-4 py-2 rounded-lg text-sm font-semibold border transition-colors ${searchType === "dpi" ? "bg-blue-600 text-white border-blue-600" : "bg-white text-gray-600 border-gray-300"}`}
              type="button"
              onClick={() => setSearchType("dpi")}
            >
              Por DPI
            </button>
            <button
              className={`px-4 py-2 rounded-lg text-sm font-semibold border transition-colors ${searchType === "id" ? "bg-blue-600 text-white border-blue-600" : "bg-white text-gray-600 border-gray-300"}`}
              type="button"
              onClick={() => setSearchType("id")}
            >
              Por No. Cita
            </button>
          </div>
          <input
            className="flex-1 px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            placeholder={
              searchType === "dpi"
                ? "DPI del paciente (13 d├¡gitos)"
                : "N├║mero de cita"
            }
            type="text"
            value={searchValue}
            onChange={(e) => setSearchValue(e.target.value)}
          />
          <Button className="px-6" type="submit" variant="primary">
            <i className="bi bi-search mr-2" /> Buscar
          </Button>
        </form>
      </div>

      {isLoading ? <LoadingComponent /> : null}

      {/* Lista de citas pendientes */}
      {!isLoading && appointments.length > 0 && !selectedAppointment && (
        <div className="space-y-3 mb-6">
          <h2 className="font-bold text-lg">Citas Pendientes de Pago</h2>
          {appointments.map((appointment) => (
            <div
              key={appointment.id}
              className="border rounded-xl p-4 bg-yellow-50 border-yellow-200 cursor-pointer hover:bg-yellow-100 transition-colors"
              onClick={() => handleSelectAppointment(appointment)}
            >
              <div className="flex justify-between items-center">
                <div>
                  <p className="font-bold">
                    {appointment.patient?.name ??
                      `Paciente #${appointment.patientId}`}
                  </p>
                  <p className="text-sm text-gray-600">
                    Cita #{appointment.id} ┬À {appointment.specialty?.name} ┬À{" "}
                    {appointment.appointmentDate}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold text-green-700">
                    Q{appointment.amount?.toFixed(2)}
                  </p>
                  <Button size="sm" variant="primary">
                    Cobrar
                  </Button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {!isLoading && searchQuery && appointments.length === 0 ? (
        <div className="text-center py-8 text-gray-400">
          <i className="bi bi-cash-coin text-4xl block mb-3" />
          <p>
            No se encontraron citas pendientes de pago para los datos
            ingresados. Verifique el DPI o n├║mero de cita e intente de nuevo.
          </p>
        </div>
      ) : null}

      {/* Formulario de cobro */}
      {selectedAppointment && !paymentSuccess ? (
        <div className="bg-white dark:bg-gray-800 rounded-xl border p-6">
          <div className="flex justify-between items-start mb-6">
            <div>
              <h2 className="text-xl font-bold">Cobro de Consulta</h2>
              <p className="text-gray-500 text-sm">
                Cita #{selectedAppointment.id}
              </p>
            </div>
            <Button
              size="sm"
              variant="secondary"
              onPress={() => setSelectedAppointment(null)}
            >
              <i className="bi bi-arrow-left mr-1" /> Cambiar cita
            </Button>
          </div>

          {/* Resumen */}
          <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-4 mb-6">
            <div className="grid grid-cols-2 gap-2 text-sm">
              <div>
                <span className="font-semibold">Paciente:</span>{" "}
                {selectedAppointment.patient?.name}
              </div>
              <div>
                <span className="font-semibold">Especialidad:</span>{" "}
                {selectedAppointment.specialty?.name}
              </div>
              <div>
                <span className="font-semibold">Sucursal:</span>{" "}
                {selectedAppointment.branch?.name}
              </div>
              <div>
                <span className="font-semibold">Fecha:</span>{" "}
                {selectedAppointment.appointmentDate}
              </div>
            </div>
            <div className="mt-3 pt-3 border-t flex justify-between items-center">
              <span className="font-bold text-lg">Total a Cobrar:</span>
              <span className="text-3xl font-bold text-green-700">
                Q{selectedAppointment.amount?.toFixed(2)}
              </span>
            </div>
          </div>

          {/* M├®todo de pago */}
          <div className="mb-4">
            <OptionsSelect
              isRequired
              defaultValue={{ label: "Efectivo (Q)", value: "0" }}
              label="M├®todo de Pago"
              name="paymentMethod"
              options={PAYMENT_METHODS}
              placeholder="Seleccione m├®todo de pago"
              onChange={(v) => {
                const val =
                  v && !Array.isArray(v) && "value" in v
                    ? Number((v as { value: string }).value)
                    : 0;
                setPaymentMethod(val);
              }}
            />
          </div>

          {/* Efectivo */}
          {paymentMethod === 0 && (
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div>
                <label className="block text-sm font-bold mb-1">
                  Monto Recibido (Q)
                </label>
                <input
                  className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  min={selectedAppointment.amount}
                  step="0.01"
                  type="number"
                  value={amountReceived}
                  onChange={(e) => setAmountReceived(e.target.value)}
                />
              </div>
              <div className="flex flex-col justify-end">
                <div
                  className={`p-3 rounded-lg text-center ${change >= 0 ? "bg-green-50 border border-green-200" : "bg-red-50 border border-red-200"}`}
                >
                  <p className="text-sm font-semibold text-gray-600">
                    Cambio a Devolver
                  </p>
                  <p
                    className={`text-2xl font-bold ${change >= 0 ? "text-green-700" : "text-red-600"}`}
                  >
                    Q{change.toFixed(2)}
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Tarjeta */}
          {paymentMethod !== 0 && (
            <div className="mb-4">
              <label className="block text-sm font-bold mb-1">
                ├Ültimos 4 d├¡gitos de la tarjeta
              </label>
              <input
                className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                maxLength={4}
                placeholder="XXXX"
                type="text"
                value={cardLastFour}
                onChange={(e) =>
                  setCardLastFour(e.target.value.replace(/\D/g, ""))
                }
              />
            </div>
          )}

          <Button
            className="w-full py-3 text-lg font-bold"
            isDisabled={paymentMutation.isPending}
            variant="primary"
            onPress={handlePay}
          >
            {paymentMutation.isPending ? (
              <>
                <i className="bi bi-hourglass-split mr-2 animate-spin" />{" "}
                Procesando...
              </>
            ) : (
              <>
                <i className="bi bi-check-circle mr-2" /> Confirmar Pago Q
                {selectedAppointment.amount?.toFixed(2)}
              </>
            )}
          </Button>
        </div>
      ) : null}

      {/* Comprobante de pago */}
      {paymentSuccess && selectedAppointment ? (
        <div className="bg-green-50 border-2 border-green-300 rounded-xl p-8 text-center">
          <i className="bi bi-check-circle-fill text-green-600 text-5xl block mb-4" />
          <h2 className="text-2xl font-bold text-green-800 mb-2">
            ┬íPago Registrado Exitosamente!
          </h2>
          <p className="text-green-700 mb-6">
            La cita ha sido actualizada a estado "Pagada".
          </p>

          <PaymentReceipt
            branchName={selectedAppointment.branch?.name ?? "ÔÇö"}
            patientName={
              selectedAppointment.patient?.name ??
              `Paciente #${selectedAppointment.patientId}`
            }
            payment={paymentSuccess.payment}
            serviceDetail={`${selectedAppointment.specialty?.name ?? "Consulta"} ÔÇö Cita #${selectedAppointment.id}`}
          />

          <div className="flex gap-3 justify-center mt-6">
            <Button
              variant="secondary"
              onPress={() => {
                setSelectedAppointment(null);
                setPaymentSuccess(null);
                setSearchValue("");
                setSearchQuery("");
              }}
            >
              <i className="bi bi-arrow-repeat mr-2" /> Nuevo Cobro
            </Button>
          </div>
        </div>
      ) : null}
    </div>
  );
}

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback } from "react";
import { useNavigate } from "react-router";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { useAuth } from "../../hooks/useAuth";
import {
  finishAppointment,
  getAppointments,
  markNoShow,
  startConsultation,
} from "../../services/appointmentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import { callPatient } from "../../utils/tts";

const STATUS_EN_ESPERA = 4;
const STATUS_CONSULTA = 5;
const STATUS_EVALUADO = 6;

const statusColors: Record<string, string> = {
  "En Espera": "bg-yellow-100 text-yellow-800 border-yellow-200",
  "Consulta Medica": "bg-blue-100 text-blue-800 border-blue-200",
  Evaluado: "bg-teal-100 text-teal-800 border-teal-200",
};

function AppointmentCard({
  appointment,
  onAction,
  isLoading,
}: {
  readonly appointment: AppointmentResponse;
  readonly onAction: (a: AppointmentResponse, action: string) => void;
  readonly isLoading: boolean;
}) {
  const statusName = appointment.appointmentStatus?.name ?? "";
  const colorClass =
    statusColors[statusName] ?? "bg-gray-100 text-gray-800 border-gray-200";
  const isWaiting = appointment.appointmentStatusId === STATUS_EN_ESPERA;
  const isInConsultation = appointment.appointmentStatusId === STATUS_CONSULTA;
  const isEvaluated = appointment.appointmentStatusId === STATUS_EVALUADO;

  return (
    <div
      className={`rounded-xl border p-4 flex flex-col gap-3 shadow-sm ${colorClass}`}
    >
      <div className="flex justify-between items-start">
        <div>
          <p className="font-bold">
            #{appointment.id} ÔÇö{" "}
            {appointment.patient?.name ?? `Paciente #${appointment.patientId}`}
          </p>
          <p className="text-sm opacity-75">
            {appointment.specialty?.name ?? "ÔÇö"}
          </p>
          <p className="text-sm opacity-75">{appointment.appointmentDate}</p>
          {appointment.priority > 0 && (
            <p className="text-red-600 font-bold text-xs">Emergencia</p>
          )}
        </div>
        <span
          className={`px-2 py-1 rounded-full text-xs font-semibold border ${colorClass}`}
        >
          {statusName}
        </span>
      </div>
      <div className="flex gap-2 flex-wrap">
        {isWaiting ? (
          <>
            <Button
              isDisabled={isLoading}
              size="sm"
              variant="primary"
              onPress={() => onAction(appointment, "start-consultation")}
            >
              <i className="bi bi-clipboard2-pulse mr-1" /> Iniciar Consulta
            </Button>
            <Button
              isDisabled={isLoading}
              size="sm"
              variant="danger"
              onPress={() => onAction(appointment, "no-show")}
            >
              <i className="bi bi-person-x mr-1" /> No Asistio
            </Button>
          </>
        ) : null}
        {isInConsultation ? (
          <Button
            isDisabled={isLoading}
            size="sm"
            variant="primary"
            onPress={() => onAction(appointment, "consultation")}
          >
            <i className="bi bi-clipboard2 mr-1" /> Ver / Completar Consulta
          </Button>
        ) : null}
        {isEvaluated ? (
          <>
            <Button
              isDisabled={isLoading}
              size="sm"
              variant="secondary"
              onPress={() => onAction(appointment, "lab-order")}
            >
              <i className="bi bi-flask mr-1" /> Pedir Laboratorio
            </Button>
            <Button
              isDisabled={isLoading}
              size="sm"
              variant="secondary"
              onPress={() => onAction(appointment, "prescription")}
            >
              <i className="bi bi-prescription2 mr-1" /> Receta / Farmacia
            </Button>
            <Button
              isDisabled={isLoading}
              size="sm"
              variant="primary"
              onPress={() => onAction(appointment, "finish")}
            >
              <i className="bi bi-check-circle mr-1" /> Finalizar Atencion
            </Button>
          </>
        ) : null}
      </div>
    </div>
  );
}

export function DoctorDashboardPage() {
  const { userId } = useAuth();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ["doctor-appointments", userId],
    queryFn: () =>
      getAppointments({
        pageNumber: 1,
        pageSize: 50,
        filters: `DoctorId:eq:${userId} AND State:eq:1 AND AppointmentStatusId:in:${STATUS_EN_ESPERA},${STATUS_CONSULTA},${STATUS_EVALUADO}`,
        include: "Specialty,Branch,AppointmentStatus,Patient",
        includeTotal: false,
      }),
    refetchInterval: 30000,
  });

  const startMutation = useMutation({
    mutationFn: (appt: AppointmentResponse) => startConsultation(appt.id),
    onSuccess: (res, appt) => {
      if (res.success) {
        callPatient(
          appt.id,
          appt.patient?.name ?? "Paciente",
          "favor pasar a consulta medica",
        );
        toast.success(`Consulta iniciada para cita #${appt.id}`);
        queryClient.invalidateQueries({
          queryKey: ["doctor-appointments", userId],
        });
      } else {
        toast.danger(res.message ?? "Error al iniciar consulta");
      }
    },
    onError: () => toast.danger("Error al iniciar consulta"),
  });

  const finishMutation = useMutation({
    mutationFn: (appt: AppointmentResponse) => finishAppointment(appt.id),
    onSuccess: (res, appt) => {
      if (res.success) {
        toast.success(`Atencion finalizada para cita #${appt.id}`);
        queryClient.invalidateQueries({
          queryKey: ["doctor-appointments", userId],
        });
      } else {
        toast.danger(res.message ?? "Error al finalizar");
      }
    },
    onError: () => toast.danger("Error al finalizar atencion"),
  });

  const noShowMutation = useMutation({
    mutationFn: (appt: AppointmentResponse) => markNoShow(appt.id),
    onSuccess: (res, appt) => {
      if (res.success) {
        toast.success(`Cita #${appt.id} marcada como No Asistio`);
        queryClient.invalidateQueries({
          queryKey: ["doctor-appointments", userId],
        });
      } else {
        toast.danger(res.message ?? "Error");
      }
    },
    onError: () => toast.danger("Error al marcar no asistio"),
  });

  const handleAction = useCallback(
    (appt: AppointmentResponse, action: string) => {
      switch (action) {
        case "start-consultation":
          startMutation.mutate(appt);
          break;
        case "finish":
          finishMutation.mutate(appt);
          break;
        case "no-show":
          noShowMutation.mutate(appt);
          break;
        case "consultation":
          navigate(
            `/medical-consultation/create?appointmentId=${appt.id}&doctorId=${userId}&patientName=${encodeURIComponent(appt.patient?.name ?? "")}`,
          );
          break;
        case "prescription":
          navigate(
            `/prescription/create?appointmentId=${appt.id}&doctorId=${userId}&patientName=${encodeURIComponent(appt.patient?.name ?? "")}`,
          );
          break;
        case "lab-order":
          navigate(
            `/lab-order/create?appointmentId=${appt.id}&doctorId=${userId}&patientId=${appt.patientId}&patientName=${encodeURIComponent(appt.patient?.name ?? "")}`,
          );
          break;
      }
    },
    [startMutation, finishMutation, noShowMutation, navigate, userId],
  );

  if (isLoading) return <LoadingComponent />;

  const appointments = data?.success ? data.data : [];
  const waiting = appointments.filter(
    (a) => a.appointmentStatusId === STATUS_EN_ESPERA,
  );
  const inConsultation = appointments.filter(
    (a) => a.appointmentStatusId === STATUS_CONSULTA,
  );
  const evaluated = appointments.filter(
    (a) => a.appointmentStatusId === STATUS_EVALUADO,
  );
  const isMutating =
    startMutation.isPending ||
    finishMutation.isPending ||
    noShowMutation.isPending;

  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold mb-2">Mi Panel de Atencion</h1>
      <p className="text-gray-500 text-sm mb-6">
        Citas activas: <strong>{appointments.length}</strong> ÔÇö actualiza cada
        30s
      </p>

      {appointments.length === 0 && (
        <div className="text-center py-16 text-gray-400">
          <i className="bi bi-calendar-x text-5xl block mb-4" />
          <p className="text-lg">No tienes citas asignadas en espera.</p>
        </div>
      )}

      {evaluated.length > 0 && (
        <section className="mb-8">
          <h2 className="text-lg font-bold mb-3 flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-teal-500 inline-block" />
            Evaluados ÔÇö Pendiente de cierre ({evaluated.length})
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {evaluated.map((a) => (
              <AppointmentCard
                key={a.id}
                appointment={a}
                isLoading={isMutating}
                onAction={handleAction}
              />
            ))}
          </div>
        </section>
      )}

      {inConsultation.length > 0 && (
        <section className="mb-8">
          <h2 className="text-lg font-bold mb-3 flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-blue-500 inline-block" />
            En Consulta Medica ({inConsultation.length})
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {inConsultation.map((a) => (
              <AppointmentCard
                key={a.id}
                appointment={a}
                isLoading={isMutating}
                onAction={handleAction}
              />
            ))}
          </div>
        </section>
      )}

      {waiting.length > 0 && (
        <section className="mb-8">
          <h2 className="text-lg font-bold mb-3 flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-yellow-500 inline-block" />
            En Espera de Consulta ({waiting.length})
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {waiting.map((a) => (
              <AppointmentCard
                key={a.id}
                appointment={a}
                isLoading={isMutating}
                onAction={handleAction}
              />
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback } from "react";
import { useNavigate } from "react-router";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { useAuth } from "../../hooks/useAuth";
import {
  getAppointments,
  startVitals,
} from "../../services/appointmentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import { callPatient } from "../../utils/tts";

const STATUS_CONFIRMADA = 2;
const STATUS_SIGNOS = 3;

const statusColors: Record<string, string> = {
  Confirmada: "bg-green-100 text-green-800 border-green-200",
  "Signos Vitales": "bg-purple-100 text-purple-800 border-purple-200",
};

function AppointmentCard({
  appointment,
  onStartVitals,
  onGoToForm,
  isLoading,
}: {
  readonly appointment: AppointmentResponse;
  readonly onStartVitals: (a: AppointmentResponse) => void;
  readonly onGoToForm: (a: AppointmentResponse) => void;
  readonly isLoading: boolean;
}) {
  const statusName = appointment.appointmentStatus?.name ?? "";
  const colorClass =
    statusColors[statusName] ?? "bg-gray-100 text-gray-800 border-gray-200";
  const isConfirmed = appointment.appointmentStatusId === STATUS_CONFIRMADA;
  const isVitals = appointment.appointmentStatusId === STATUS_SIGNOS;
  const patientName =
    appointment.patient?.name ?? `Paciente #${appointment.patientId}`;

  return (
    <div
      className={`rounded-xl border p-4 flex flex-col gap-3 shadow-sm ${colorClass}`}
    >
      <div className="flex justify-between items-start">
        <div>
          <p className="font-bold text-base">
            #{appointment.id} ÔÇö {patientName}
          </p>
          <p className="text-sm opacity-75">
            {appointment.specialty?.name ?? "ÔÇö"}
          </p>
          <p className="text-sm opacity-75">
            {appointment.branch?.name ?? "ÔÇö"}
          </p>
          <p className="text-sm opacity-75">{appointment.appointmentDate}</p>
        </div>
        <span
          className={`px-2 py-1 rounded-full text-xs font-semibold border ${colorClass}`}
        >
          {statusName}
        </span>
      </div>
      <div className="flex gap-2 flex-wrap">
        {isConfirmed ? (
          <Button
            isDisabled={isLoading}
            size="sm"
            variant="primary"
            onPress={() => onStartVitals(appointment)}
          >
            <i className="bi bi-megaphone mr-1" />
            Llamar y Tomar Signos
          </Button>
        ) : null}
        {isVitals ? (
          <Button
            isDisabled={isLoading}
            size="sm"
            variant="primary"
            onPress={() => onGoToForm(appointment)}
          >
            <i className="bi bi-heart-pulse mr-1" />
            Registrar Signos Vitales
          </Button>
        ) : null}
      </div>
    </div>
  );
}

export function NurseDashboardPage() {
  const queryClient = useQueryClient();
  const navigate = useNavigate();
  const { userId } = useAuth();

  const { data, isLoading } = useQuery({
    queryKey: ["nurse-appointments"],
    queryFn: () =>
      getAppointments({
        pageNumber: 1,
        pageSize: 100,
        filters: `State:eq:1 AND AppointmentStatusId:in:${STATUS_CONFIRMADA},${STATUS_SIGNOS}`,
        include: "Specialty,Branch,AppointmentStatus,Patient",
        includeTotal: false,
      }),
    refetchInterval: 30000,
  });

  // Step 1: call patient via TTS + transition to "Signos Vitales"
  const startVitalsMutation = useMutation({
    mutationFn: (appt: AppointmentResponse) => startVitals(appt.id),
    onSuccess: (res, appt) => {
      if (res.success) {
        const patientName = appt.patient?.name ?? "Paciente";
        callPatient(
          appt.id,
          patientName,
          "favor pasar a toma de signos vitales",
        );
        toast.success(`Paciente ${patientName} llamado ÔÇö cita #${appt.id}`);
        queryClient.invalidateQueries({ queryKey: ["nurse-appointments"] });
      } else {
        toast.danger(res.message ?? "Error al cambiar estado");
      }
    },
    onError: () => toast.danger("Error al actualizar estado"),
  });

  // Step 2: navigate to the vitals form with appointment context
  const handleGoToForm = useCallback(
    (appt: AppointmentResponse) => {
      navigate(
        `/vital-sign/create?appointmentId=${appt.id}&patientId=${appt.patientId}&nurseId=${userId}&patientName=${encodeURIComponent(appt.patient?.name ?? "")}`,
      );
    },
    [navigate, userId],
  );

  const handleStartVitals = useCallback(
    (appt: AppointmentResponse) => {
      startVitalsMutation.mutate(appt);
    },
    [startVitalsMutation],
  );

  if (isLoading) return <LoadingComponent />;

  const appointments = data?.success ? data.data : [];
  const confirmed = appointments.filter(
    (a) => a.appointmentStatusId === STATUS_CONFIRMADA,
  );
  const inVitals = appointments.filter(
    (a) => a.appointmentStatusId === STATUS_SIGNOS,
  );

  return (
    <div className="p-4 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-2">Panel de Rol Interino</h1>
      <p className="text-gray-500 text-sm mb-6">
        Gestione la toma de signos vitales. Las citas se actualizan cada 30
        segundos. Total: <strong>{appointments.length}</strong>
      </p>

      {appointments.length === 0 && (
        <div className="text-center py-16 text-gray-400">
          <i className="bi bi-calendar-check text-5xl block mb-4" />
          <p>No hay citas confirmadas pendientes de signos vitales.</p>
        </div>
      )}

      {inVitals.length > 0 && (
        <section className="mb-8">
          <h2 className="text-lg font-bold mb-3 flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-purple-500 inline-block" />
            Pacientes Llamados ÔÇö Pendiente de Registrar Signos (
            {inVitals.length})
          </h2>
          <p className="text-xs text-gray-500 mb-3">
            Estos pacientes ya fueron llamados. Haga clic en "Registrar Signos
            Vitales" para completar el formulario.
          </p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {inVitals.map((a) => (
              <AppointmentCard
                key={a.id}
                appointment={a}
                isLoading={startVitalsMutation.isPending}
                onGoToForm={handleGoToForm}
                onStartVitals={handleStartVitals}
              />
            ))}
          </div>
        </section>
      )}

      {confirmed.length > 0 && (
        <section className="mb-8">
          <h2 className="text-lg font-bold mb-3 flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-green-500 inline-block" />
            Citas Confirmadas ÔÇö En Espera de Ser Llamadas ({confirmed.length})
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {confirmed.map((a) => (
              <AppointmentCard
                key={a.id}
                appointment={a}
                isLoading={startVitalsMutation.isPending}
                onGoToForm={handleGoToForm}
                onStartVitals={handleStartVitals}
              />
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
