  if (isLoading) {
    return (
      <div className="flex justify-center items-center py-16">
        <span className="text-gray-500">Cargando receta...</span>
      </div>
    );
  }

  if (!prescription) {
    return (
      <div className="max-w-2xl mx-auto p-6 text-center">
        <p className="text-red-600 font-semibold">
          No se encontr├│ la receta #{prescriptionId}.
        </p>
      </div>
    );
  }

  if (!isValid) {
    return (
      <div className="max-w-2xl mx-auto p-6">
        <div className="flex flex-col gap-3 rounded-lg border border-red-300 bg-red-50 p-6 text-center">
          <span aria-hidden="true" className="text-4xl">
            Ôøö
          </span>
          <h2 className="text-xl font-bold text-red-800">Receta Vencida</h2>
          <p className="text-red-700">
            La receta #{prescriptionId} fue emitida hace{" "}
            <strong>{daysOld} d├¡as</strong> y ya no es v├ílida para despacho. El
            paciente debe solicitar una nueva receta al m├®dico tratante.
          </p>
          <p className="text-sm text-red-600">
            Las recetas son v├ílidas por un m├íximo de 7 d├¡as desde su fecha de
            emisi├│n.
          </p>
          <button
            className="mt-2 px-4 py-2 rounded-lg bg-red-100 text-red-800 font-semibold hover:bg-red-200 transition-colors"
            type="button"
            onClick={() => navigate("/dispense")}
          >
            Volver a Despachos
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <DispenseForm
        prescriptionDate={prescription.prescriptionDate}
        prescriptionId={prescriptionId}
        onSuccess={() => navigate("/dispense")}
      />
    </div>
  );
}

import type { DatesSetArg, EventClickArg } from "@fullcalendar/core";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction";
import FullCalendar from "@fullcalendar/react";
import timeGridPlugin from "@fullcalendar/timegrid";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router";

import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import { getAppointments } from "../../services/appointmentService";
import { getDoctorEvents } from "../../services/doctorEventService";
import { getDoctorTasks } from "../../services/doctorTaskService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import type { DoctorEventResponse } from "../../types/DoctorEventResponse";
import type { DoctorTaskResponse } from "../../types/DoctorTaskResponse";
import { getAppTimezone } from "../../utils/dateFormatter";

import { EventModal } from "../../components/modal/EventModal";
import { TaskModal } from "../../components/modal/TaskModal";
import { TaskPanel } from "../../components/modal/TaskPanel";

interface CalendarEvent {
  id: string;
  title: string;
  start: string;
  end?: string;
  allDay?: boolean;
  backgroundColor?: string;
  borderColor?: string;
  textColor?: string;
  classNames?: string[];
  extendedProps: {
    type: "appointment" | "event" | "task";
    data: AppointmentResponse | DoctorEventResponse | DoctorTaskResponse;
  };
}

/** Map appointment status to color */
function getAppointmentColor(statusId: number): string {
  // 1=Pendiente(blue), 2=Confirmada(green), 3-6=En progreso(yellow), 7+=Completada(gray)
  if (statusId <= 1) return "#3b82f6"; // blue
  if (statusId === 2) return "#22c55e"; // green
  if (statusId >= 3 && statusId <= 6) return "#eab308"; // yellow
  return "#9ca3af"; // gray
}

/** Parse backend date strings (handles "dd/MM/yyyy HH:mm:ss" and ISO formats) */
function parseCalendarDate(dateStr: string | null | undefined): Date | null {
  if (!dateStr) return null;
  // ISO format
  if (dateStr.includes("T") || dateStr.endsWith("Z")) {
    const d = new Date(dateStr);
    return isNaN(d.getTime()) ? null : d;
  }
  // Backend format: "dd/MM/yyyy HH:mm:ss"
  const match = dateStr.match(
    /^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2}):(\d{2})$/,
  );
  if (match) {
    const [, day, month, year, hour, min, sec] = match;
    return new Date(Date.UTC(+year, +month - 1, +day, +hour, +min, +sec));
  }
  // Date-only: "dd/MM/yyyy"
  const dateOnly = dateStr.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (dateOnly) {
    const [, day, month, year] = dateOnly;
    return new Date(Date.UTC(+year, +month - 1, +day));
  }
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? null : d;
}

/**
 * Convert a UTC Date to a local datetime string in the user's timezone.
 * Returns format "YYYY-MM-DDTHH:mm:ss" (no Z suffix) so FullCalendar treats it as local.
 */
function toLocalCalendarString(utcDate: Date, tz: string): string {
  // Use Intl.DateTimeFormat to get the date parts in the target timezone
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: tz,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(utcDate);

  const get = (type: string) =>
    parts.find((p) => p.type === type)?.value ?? "00";
  return `${get("year")}-${get("month")}-${get("day")}T${get("hour")}:${get("minute")}:${get("second")}`;
}

export function DoctorCalendarPage() {
  const { userId } = useAuth();
  const navigate = useNavigate();
  const calendarRef = useRef<FullCalendar>(null);

  const [appointments, setAppointments] = useState<AppointmentResponse[]>([]);
  const [events, setEvents] = useState<DoctorEventResponse[]>([]);
  const [tasks, setTasks] = useState<DoctorTaskResponse[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(
    new Date().toISOString().split("T")[0],
  );

  // Modal states
  const [eventModalOpen, setEventModalOpen] = useState(false);
  const [taskModalOpen, setTaskModalOpen] = useState(false);
  const [editingEvent, setEditingEvent] = useState<DoctorEventResponse | null>(
    null,
  );
  const [editingTask, setEditingTask] = useState<DoctorTaskResponse | null>(
    null,
  );

  // Date range for current view
  const [dateRange, setDateRange] = useState<{
    start: string;
    end: string;
  } | null>(null);

  const loadData = useCallback(
    async (start: string, end: string) => {
      if (!userId) return;
      setLoading(true);
      try {
        const [apptRes, eventRes, taskRes] = await Promise.all([
          getAppointments({
            pageNumber: 1,
            pageSize: 200,
            filters: `DoctorId:eq:${userId} AND AppointmentDate:gte:${start} AND AppointmentDate:lte:${end}`,
            include: "Patient,Specialty,AppointmentStatus",
            includeTotal: false,
          }),
          getDoctorEvents({
            pageNumber: 1,
            pageSize: 200,
            filters: `DoctorId:eq:${userId} AND StartDate:lte:${end} AND EndDate:gte:${start} AND State:eq:1`,
            include: null,
            includeTotal: false,
          }),
          getDoctorTasks({
            pageNumber: 1,
            pageSize: 200,
            filters: `DoctorId:eq:${userId} AND DueDate:gte:${start} AND DueDate:lte:${end} AND State:eq:1`,
            include: null,
            includeTotal: false,
          }),
        ]);

        if (apptRes.success) setAppointments(apptRes.data);
        if (eventRes.success) setEvents(eventRes.data);
        if (taskRes.success) setTasks(taskRes.data);
      } catch (error) {
        console.error("Error loading calendar data:", error);
      } finally {
        setLoading(false);
      }
    },
    [userId],
  );

  const handleDatesSet = useCallback(
    (arg: DatesSetArg) => {
      const start = arg.startStr.split("T")[0];
      const end = arg.endStr.split("T")[0];
      setDateRange({ start, end });
      loadData(start, end);
    },
    [loadData],
  );

  // Map data to FullCalendar events
  const calendarEvents: CalendarEvent[] = useMemo(() => {
    const mapped: CalendarEvent[] = [];
    const tz = getAppTimezone();

    // Appointments ÔÇö only confirmed and beyond (exclude pendiente=1, no asisti├│=10, cancelada=11)
    const EXCLUDED_STATUSES = new Set([1, 10, 11]);
    appointments.forEach((appt) => {
      if (EXCLUDED_STATUSES.has(appt.appointmentStatusId)) return;
      const color = getAppointmentColor(appt.appointmentStatusId);
      const patientName = appt.patient?.name ?? "Paciente";
      const specialtyName = appt.specialty?.name ?? "";
      const startDate = parseCalendarDate(appt.appointmentDate);
      if (!startDate) return;
      const endDate = new Date(startDate.getTime() + 30 * 60 * 1000);
      mapped.push({
        id: `appt-${appt.id}`,
        title: `Cita #${appt.id} ÔÇö ${patientName}${specialtyName ? ` (${specialtyName})` : ""}`,
        start: toLocalCalendarString(startDate, tz),
        end: toLocalCalendarString(endDate, tz),
        backgroundColor: color,
        borderColor: color,
        textColor: "#ffffff",
        extendedProps: { type: "appointment", data: appt },
      });
    });

    // Events
    events.forEach((evt) => {
      const evtStart = parseCalendarDate(evt.startDate);
      const evtEnd = parseCalendarDate(evt.endDate);
      mapped.push({
        id: `event-${evt.id}`,
        title: evt.title,
        start: evtStart ? toLocalCalendarString(evtStart, tz) : evt.startDate,
        end: evtEnd ? toLocalCalendarString(evtEnd, tz) : evt.endDate,
        allDay: evt.isAllDay,
        backgroundColor: "#8b5cf6",
        borderColor: "#7c3aed",
        textColor: "#ffffff",
        extendedProps: { type: "event", data: evt },
      });
    });

    // Tasks
    tasks.forEach((task) => {
      const isCompleted = task.isCompleted;
      const taskDate = parseCalendarDate(task.dueDate);
      mapped.push({
        id: `task-${task.id}`,
        title: task.title,
        start: taskDate ? toLocalCalendarString(taskDate, tz) : task.dueDate,
        allDay: true,
        backgroundColor: isCompleted ? "#9ca3af" : "#f97316",
        borderColor: isCompleted ? "#6b7280" : "#ea580c",
        textColor: "#ffffff",
        classNames: isCompleted ? ["line-through", "opacity-60"] : [],
        extendedProps: { type: "task", data: task },
      });
    });

    return mapped;
  }, [appointments, events, tasks]);

  const handleEventClick = useCallback(
    (arg: EventClickArg) => {
      const { type, data } = arg.event.extendedProps;
      if (type === "appointment") {
        navigate(nameRoutes.doctorDashboard);
      } else if (type === "event") {
        setEditingEvent(data as DoctorEventResponse);
        setEventModalOpen(true);
      } else if (type === "task") {
        setEditingTask(data as DoctorTaskResponse);
        setTaskModalOpen(true);
      }
    },
    [navigate],
  );

  const handleDateClick = useCallback((arg: { dateStr: string }) => {
    setSelectedDate(arg.dateStr.split("T")[0]);
  }, []);

  const handleCreateEvent = useCallback(() => {
    setEditingEvent(null);
    setEventModalOpen(true);
  }, []);

  const handleCreateTask = useCallback(() => {
    setEditingTask(null);
    setTaskModalOpen(true);
  }, []);

  const [taskPanelOpen, setTaskPanelOpen] = useState(true);

  // Resize calendar when task panel toggles or window resizes
  useEffect(() => {
    const timer = setTimeout(() => {
      calendarRef.current?.getApi().updateSize();
    }, 50);
    return () => clearTimeout(timer);
  }, [taskPanelOpen]);

  // Also listen for window resize
  useEffect(() => {
    const handleResize = () => calendarRef.current?.getApi().updateSize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const refreshData = useCallback(() => {
    if (dateRange) {
      loadData(dateRange.start, dateRange.end);
    }
  }, [dateRange, loadData]);

  return (
    <div className="flex flex-col h-full gap-3 p-2 sm:p-4">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
        <h1 className="text-xl sm:text-2xl font-bold">Mi Calendario</h1>
        <div className="flex flex-wrap gap-2">
          <button
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-purple-600 text-white text-xs sm:text-sm font-medium hover:bg-purple-700 transition-colors"
            type="button"
            onClick={handleCreateEvent}
          >
            <i className="bi bi-calendar-event" />
            <span className="hidden xs:inline">Nuevo</span> Evento
          </button>
          <button
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-orange-500 text-white text-xs sm:text-sm font-medium hover:bg-orange-600 transition-colors"
            type="button"
            onClick={handleCreateTask}
          >
            <i className="bi bi-check2-square" />
            <span className="hidden xs:inline">Nueva</span> Tarea
          </button>
          <button
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs sm:text-sm font-medium transition-colors ${
              taskPanelOpen
                ? "bg-gray-200 dark:bg-zinc-700 text-gray-700 dark:text-gray-200"
                : "bg-gray-100 dark:bg-zinc-800 text-gray-500 dark:text-gray-400"
            }`}
            type="button"
            onClick={() => setTaskPanelOpen((prev) => !prev)}
          >
            <i
              className={`bi ${taskPanelOpen ? "bi-layout-sidebar-reverse" : "bi-list-task"}`}
            />
            <span className="hidden sm:inline">Tareas</span>
          </button>
        </div>
      </div>

      {/* Calendar + Task Panel */}
      <div className="flex flex-col lg:flex-row flex-1 gap-3 min-h-0">
        {/* Calendar */}
        <div className="flex-1 min-w-0 bg-white dark:bg-zinc-900 rounded-xl shadow-sm p-2 sm:p-4 overflow-auto relative">
          {loading ? (
            <div className="absolute inset-0 bg-white/50 dark:bg-zinc-900/50 z-10 flex items-center justify-center rounded-xl">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600" />
            </div>
          ) : null}
          <FullCalendar
            ref={calendarRef}
            allDaySlot
            nowIndicator
            buttonText={{
              today: "Hoy",
              month: "Mes",
              week: "Semana",
              day: "D├¡a",
            }}
            dateClick={handleDateClick}
            datesSet={handleDatesSet}
            editable={false}
            eventClick={handleEventClick}
            events={calendarEvents}
            firstDay={1}
            headerToolbar={{
              left: "prev,next today",
              center: "title",
              right: "timeGridDay,timeGridWeek,dayGridMonth",
            }}
            height="auto"
            initialView="timeGridWeek"
            locale="es"
            plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin]}
            selectable={false}
            slotMaxTime="22:00:00"
            slotMinTime="06:00:00"
            timeZone="local"
          />
        </div>

        {/* Task Panel ÔÇö collapsible */}
        {taskPanelOpen ? (
          <div className="lg:w-80 lg:shrink-0">
            <TaskPanel
              selectedDate={selectedDate}
              tasks={tasks}
              onRefresh={refreshData}
            />
          </div>
        ) : null}
      </div>

      {/* Event Modal */}
      {eventModalOpen ? (
        <EventModal
          event={editingEvent}
          userId={userId}
          onClose={() => {
            setEventModalOpen(false);
            setEditingEvent(null);
          }}
          onSaved={refreshData}
        />
      ) : null}

      {/* Task Modal */}
      {taskModalOpen ? (
        <TaskModal
          task={editingTask}
          userId={userId}
          onClose={() => {
            setTaskModalOpen(false);
            setEditingTask(null);
          }}
          onSaved={refreshData}
        />
      ) : null}
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { useNavigate, useSearchParams } from "react-router";
import { LabOrderForm } from "../../components/form/LabOrderForm";
import { BlockedWithoutContext } from "../../components/shared/BlockedWithoutContext";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import { getMedicalConsultations } from "../../services/medicalConsultationService";

export function CreateLabOrderPage() {
  const navigate = useNavigate();
  const { userId } = useAuth();
  const [searchParams] = useSearchParams();

  const consultationIdParam = searchParams.get("consultationId");
  const appointmentIdParam = searchParams.get("appointmentId");
  const doctorIdParam = searchParams.get("doctorId");
  const patientIdParam = searchParams.get("patientId");
  const patientNameParam = searchParams.get("patientName");
  const fromDoctorDashboard = !!appointmentIdParam || !!consultationIdParam;

  // ÔöÇÔöÇ Guard: no context ÔåÆ blocked ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (!appointmentIdParam && !consultationIdParam) {
    return (
      <BlockedWithoutContext
        backLabel="Ir al Panel del M├®dico"
        backRoute={nameRoutes.doctorDashboard}
        icon="bi-flask"
        message="No puedes crear una orden de laboratorio sin que provenga de una consulta m├®dica completada. Las ├│rdenes solo pueden generarse desde el panel del m├®dico."
        title="Acceso no permitido"
      />
    );
  }

  // If we have appointmentId but not consultationId, look up the consultation
  const { data: consultationData, isLoading } = useQuery({
    queryKey: ["consultation-for-appointment", appointmentIdParam],
    queryFn: () =>
      getMedicalConsultations({
        pageNumber: 1,
        pageSize: 1,
        filters: `AppointmentId:eq:${appointmentIdParam} AND ConsultationStatus:eq:1 AND State:eq:1`,
        include: null,
        includeTotal: false,
      }),
    enabled: !!appointmentIdParam && !consultationIdParam,
  });

  if (isLoading) return <LoadingComponent />;

  const resolvedConsultationId = consultationIdParam
    ? Number(consultationIdParam)
    : consultationData?.success && consultationData.data.length > 0
      ? consultationData.data[0].id
      : null;

  // No completed consultation found
  if (!resolvedConsultationId && fromDoctorDashboard) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6 p-8 text-center">
        <i className="bi bi-exclamation-triangle text-6xl text-yellow-400" />
        <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
          Consulta no finalizada
        </h1>
        <p className="text-gray-500 dark:text-gray-400 max-w-md">
          No se encontr├│ una consulta m├®dica finalizada para esta cita. Debe
          finalizar la consulta m├®dica antes de poder generar una orden de
          laboratorio.
        </p>
        <button
          className="flex items-center gap-2 rounded-xl bg-blue-600 px-6 py-3 font-bold text-white hover:bg-blue-700 transition-colors"
          type="button"
          onClick={() => navigate(nameRoutes.doctorDashboard)}
        >
          <i className="bi bi-arrow-left" />
          Volver al Panel
        </button>
      </div>
    );
  }

  return (
    <div>
      <LabOrderForm
        fromDoctorDashboard={fromDoctorDashboard}
        initialConsultationId={resolvedConsultationId}
        initialDoctorId={
          doctorIdParam ? Number(doctorIdParam) : (userId ?? null)
        }
        initialPatientId={patientIdParam ? Number(patientIdParam) : null}
        patientName={patientNameParam ?? undefined}
        onSuccess={(id) => {
          if (fromDoctorDashboard) {
            navigate(nameRoutes.doctorDashboard);
          } else {
            navigate(`/lab-order/${id}`);
          }
        }}
      />
    </div>
  );
}

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate, useParams } from "react-router";
import { LabOrderItemResultForm } from "../../components/form/LabOrderItemResultForm";
import { OutOfRangeAlert } from "../../components/shared/OutOfRangeAlert";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import {
  getLabOrderById,
  partialUpdateLabOrderItem,
} from "../../services/labOrderService";

export function LabOrderDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const labOrderId = Number(id);

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["lab-order", labOrderId],
    queryFn: () => getLabOrderById(labOrderId),
    enabled: !!labOrderId,
  });

  const publishMutation = useMutation({
    mutationFn: (itemId: number) =>
      partialUpdateLabOrderItem({ id: itemId, isPublished: true }),
    onSuccess: () => {
      toast.success("Resultado publicado exitosamente.");
      queryClient.invalidateQueries({ queryKey: ["lab-order", labOrderId] });
    },
    onError: () => toast.danger("Error al publicar el resultado."),
  });

  if (isLoading) return <LoadingComponent />;

  const order = data?.success ? data.data : null;

  if (!order) {
    return (
      <div className="max-w-4xl mx-auto p-6 text-center">
        <p className="text-gray-500">No se encontr├│ la orden de laboratorio.</p>
        <Button
          className="mt-4"
          size="sm"
          variant="secondary"
          onPress={() => navigate(-1)}
        >
          <i className="bi bi-arrow-left mr-1" /> Volver
        </Button>
      </div>
    );
  }

  // Items may be nested in the response under different keys depending on the API include
  const items = (order as unknown as { items?: unknown[] })?.items ?? [];

  // Calculate total amount as sum of item amounts
  const totalAmount = (
    items as unknown as Array<{ amount?: number | null }>
  ).reduce((sum, item) => sum + (item.amount ?? 0), 0);

  const statusLabel =
    order.orderStatus === 0
      ? "Pendiente"
      : order.orderStatus === 1
        ? "En proceso"
        : "Completada";

  return (
    <div className="max-w-4xl mx-auto p-6">
      {/* ÔöÇÔöÇ Header ÔöÇÔöÇ */}
      <div className="flex items-center gap-3 mb-6">
        <Button size="sm" variant="secondary" onPress={() => navigate(-1)}>
          <i className="bi bi-arrow-left mr-1" /> Volver
        </Button>
        <h1 className="text-2xl font-bold">
          Orden de Laboratorio #{order.orderNumber ?? order.id}
        </h1>
      </div>

      {/* ÔöÇÔöÇ Order summary ÔöÇÔöÇ */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border p-4 mb-6">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
          <div>
            <span className="font-semibold text-gray-500">N├║mero:</span>{" "}
            {order.orderNumber ?? "ÔÇö"}
          </div>
          <div>
            <span className="font-semibold text-gray-500">Paciente:</span>{" "}
            {(order as unknown as { patient?: { name?: string } })?.patient
              ?.name ?? `#${order.patientId}`}
          </div>
          <div>
            <span className="font-semibold text-gray-500">M├®dico:</span>{" "}
            {(order as unknown as { doctor?: { name?: string } })?.doctor
              ?.name ?? `#${order.doctorId}`}
          </div>
          <div>
            <span className="font-semibold text-gray-500">Estado:</span>{" "}
            <span className="inline-flex items-center rounded-full bg-yellow-100 px-2 py-0.5 text-xs font-semibold text-yellow-800">
              {statusLabel}
            </span>
          </div>
          <div>
            <span className="font-semibold text-gray-500">Total:</span>{" "}
            <span className="font-bold">Q {totalAmount.toFixed(2)}</span>
          </div>
          {order.isExternal ? (
            <div>
              <span className="inline-flex items-center rounded-full bg-blue-100 px-2 py-0.5 text-xs font-semibold text-blue-800">
                Externa
              </span>
            </div>
          ) : null}
          {order.notes ? (
            <div className="col-span-2 md:col-span-4">
              <span className="font-semibold text-gray-500">Notas:</span>{" "}
              {order.notes}
            </div>
          ) : null}
        </div>
      </div>

      {/* ÔöÇÔöÇ Items ÔöÇÔöÇ */}
      <h2 className="text-lg font-bold mb-4">
        <i className="bi bi-flask mr-2" />
        Ex├ímenes ({items.length})
      </h2>

      {items.length === 0 && (
        <p className="text-gray-400 text-center py-6">
          Esta orden no tiene ex├ímenes registrados.
        </p>
      )}

      <div className="flex flex-col gap-6">
        {(
          items as Array<{
            id: number;
            examName?: string | null;
            amount?: number | null;
            isOutOfRange?: boolean | null;
            referenceRange?: string | null;
            isPublished?: boolean | null;
            resultValue?: string | null;
            resultUnit?: string | null;
            resultNotes?: string | null;
            resultDate?: string | null;
            labExamId: number;
            labOrderId: number;
            state: number;
            createdAt: string;
            createdBy: number;
          }>
        ).map((item) => (
          <div
            key={item.id}
            className="bg-white dark:bg-gray-800 rounded-xl border p-5"
          >
            {/* Item header */}
            <div className="flex items-start justify-between mb-3">
              <div>
                <p className="font-bold text-base">
                  {item.examName ?? `Examen #${item.labExamId}`}
                </p>
                <p className="text-sm text-gray-500">
                  Cantidad:{" "}
                  <span className="font-semibold">{item.amount ?? 0}</span>
                </p>
              </div>
              <div className="flex items-center gap-2">
                <OutOfRangeAlert
                  isOutOfRange={item.isOutOfRange ?? false}
                  referenceRange={item.referenceRange ?? undefined}
                />
                {item.isPublished ? (
                  <span className="inline-flex items-center rounded-full bg-green-100 px-2 py-0.5 text-xs font-semibold text-green-800">
                    Ô£à Publicado
                  </span>
                ) : null}
              </div>
            </div>

            {/* Result entry form */}
            <div className="border-t pt-4 mt-2">
              <p className="text-sm font-semibold text-gray-600 mb-3">
                <i className="bi bi-pencil-square mr-1" /> Ingresar / Actualizar
                Resultado
              </p>
              <LabOrderItemResultForm item={item} onSuccess={() => refetch()} />
            </div>

            {/* Publish button */}
            {!item.isPublished && (
              <div className="mt-3 flex justify-end">
                <button
                  className="px-4 py-2 rounded-lg text-sm font-semibold bg-green-100 text-green-800 hover:bg-green-200 transition-colors disabled:opacity-50"
                  disabled={publishMutation.isPending}
                  type="button"
                  onClick={() => publishMutation.mutate(item.id)}
                >
                  <i className="bi bi-send-check mr-1" /> Publicar resultado
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { toast } from "@heroui/react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate, useSearchParams } from "react-router";
import { MedicalConsultationForm } from "../../components/form/MedicalConsultationForm";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import {
  createMedicalConsultation,
  getMedicalConsultations,
} from "../../services/medicalConsultationService";
import type { MedicalConsultationRequest } from "../../types/MedicalConsultationResponse";

export function CreateMedicalConsultationPage() {
  const client = useQueryClient();
  const navigate = useNavigate();
  const { userId } = useAuth();
  const [searchParams] = useSearchParams();

  const appointmentIdParam = searchParams.get("appointmentId");
  const doctorIdParam = searchParams.get("doctorId");
  const patientNameParam = searchParams.get("patientName");

  // ÔöÇÔöÇ Guard: no appointmentId ÔåÆ blocked ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (!appointmentIdParam) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6 p-8 text-center">
        <i className="bi bi-shield-exclamation text-6xl text-red-400" />
        <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
          Acceso no permitido
        </h1>
        <p className="text-gray-500 dark:text-gray-400 max-w-md">
          No puedes crear una consulta m├®dica sin que provenga de una cita
          m├®dica activa. Las consultas solo pueden iniciarse desde el panel del
          m├®dico.
        </p>
        <button
          className="flex items-center gap-2 rounded-xl bg-blue-600 px-6 py-3 font-bold text-white hover:bg-blue-700 transition-colors"
          type="button"
          onClick={() => navigate(nameRoutes.doctorDashboard)}
        >
          <i className="bi bi-arrow-left" />
          Ir al Panel del M├®dico
        </button>
      </div>
    );
  }

  // ÔöÇÔöÇ Check if a consultation already exists for this appointment ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  return (
    <CreateMedicalConsultationGuard
      appointmentId={Number(appointmentIdParam)}
      doctorId={doctorIdParam ? Number(doctorIdParam) : (userId ?? 0)}
      patientName={patientNameParam ?? undefined}
      onSubmitSuccess={() => {
        client.invalidateQueries({ queryKey: ["medical-consultations"] });
        client.invalidateQueries({ queryKey: ["doctor-appointments"] });
        navigate(nameRoutes.doctorDashboard);
      }}
    />
  );
}

// ÔöÇÔöÇ Inner component that runs the duplicate check ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function CreateMedicalConsultationGuard({
  appointmentId,
  doctorId,
  patientName,
  onSubmitSuccess,
}: {
  readonly appointmentId: number;
  readonly doctorId: number;
  readonly patientName?: string;
  readonly onSubmitSuccess: () => void;
}) {
  const navigate = useNavigate();

  const { data, isLoading } = useQuery({
    queryKey: ["consultation-check", appointmentId],
    queryFn: () =>
      getMedicalConsultations({
        pageNumber: 1,
        pageSize: 1,
        filters: `AppointmentId:eq:${appointmentId} AND State:eq:1`,
        include: null,
        includeTotal: false,
      }),
    staleTime: 0, // always fresh
  });

  if (isLoading) return <LoadingComponent />;

  const existing = data?.success && data.data.length > 0 ? data.data[0] : null;

  // Consultation exists and is NOT completed ÔåÆ redirect to update it
  if (existing && existing.consultationStatus !== 1) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6 p-8 text-center">
        <i className="bi bi-clipboard2-pulse text-6xl text-yellow-400" />
        <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
          Ya existe una consulta en curso
        </h1>
        <p className="text-gray-500 dark:text-gray-400 max-w-md">
          Esta cita ya tiene una consulta m├®dica registrada que a├║n no ha sido
          finalizada. Puedes continuar edit├índola.
        </p>
        <button
          className="flex items-center gap-2 rounded-xl bg-blue-600 px-6 py-3 font-bold text-white hover:bg-blue-700 transition-colors"
          type="button"
          onClick={() =>
            navigate(`/medical-consultation/update/${existing.id}`)
          }
        >
          <i className="bi bi-pencil-square mr-1" />
          Continuar Consulta Existente
        </button>
        <button
          className="text-sm text-gray-400 hover:text-gray-600"
          type="button"
          onClick={() => navigate(nameRoutes.doctorDashboard)}
        >
          Volver al panel
        </button>
      </div>
    );
  }

  // Consultation exists and IS completed ÔåÆ show info
  if (existing && existing.consultationStatus === 1) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6 p-8 text-center">
        <i className="bi bi-check-circle text-6xl text-green-400" />
        <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
          Consulta ya finalizada
        </h1>
        <p className="text-gray-500 dark:text-gray-400 max-w-md">
          Esta cita ya tiene una consulta m├®dica completada. No es posible crear
          una nueva. Puedes ver la consulta existente o regresar al panel.
        </p>
        <div className="flex gap-3">
          <button
            className="flex items-center gap-2 rounded-xl bg-gray-200 px-5 py-2.5 font-semibold text-gray-700 hover:bg-gray-300 transition-colors"
            type="button"
            onClick={() =>
              navigate(`/medical-consultation/update/${existing.id}`)
            }
          >
            <i className="bi bi-eye mr-1" />
            Ver Consulta
          </button>
          <button
            className="flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 font-bold text-white hover:bg-blue-700 transition-colors"
            type="button"
            onClick={() => navigate(nameRoutes.doctorDashboard)}
          >
            <i className="bi bi-arrow-left mr-1" />
            Volver al Panel
          </button>
        </div>
      </div>
    );
  }

  // No existing consultation ÔåÆ show the form
  const initialData: MedicalConsultationRequest = {
    appointmentId,
    doctorId,
    reasonForVisit: "",
    clinicalFindings: "",
    diagnosis: "",
    diagnosisCie10Code: "",
    treatmentPlan: "",
    consultationStatus: 0,
    notes: "",
    state: 1,
  };

  return (
    <MedicalConsultationForm
      fromDoctorDashboard
      initialForm={initialData}
      patientName={patientName}
      type="create"
      onSubmit={async (form) => {
        const response = await createMedicalConsultation(form);
        if (response.success) {
          if (form.consultationStatus === 1) {
            toast.success(
              "La consulta ha sido finalizada exitosamente. El paciente puede proceder a las siguientes indicaciones m├®dicas.",
            );
          } else {
            toast.success(
              "Consulta m├®dica registrada exitosamente. Puede continuar edit├índola desde el panel del m├®dico.",
            );
          }
          onSubmitSuccess();
        } else {
          toast.danger(response.message);
        }
        return response;
      }}
    />
  );
}

import { useMutation, useQuery } from "@tanstack/react-query";
import { useState } from "react";
import { useSearchParams } from "react-router";
import { CardPaymentForm } from "../../components/payment/CardPaymentForm";
import { PaymentReceipt } from "../../components/shared/PaymentReceipt";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import {
  getAppointmentById,
  partialUpdateAppointment,
} from "../../services/appointmentService";
import type { PaymentResponse } from "../../types/PaymentResponse";
import { formatDateLong } from "../../utils/dateFormatter";

/** appointmentStatusId that corresponds to "Pagada" */
const PAID_STATUS_ID = 1;

/**
 * Online payment page.
 * Reads appointmentId from the `appointmentId` query param,
 * shows a payment summary, and renders CardPaymentForm.
 * On success, updates the appointment status and shows a receipt.
 */
export function OnlinePaymentPage() {
  const [searchParams] = useSearchParams();
  const appointmentIdParam = searchParams.get("appointmentId");
  const appointmentId = appointmentIdParam
    ? parseInt(appointmentIdParam, 10)
    : NaN;

  const [completedPayment, setCompletedPayment] =
    useState<PaymentResponse | null>(null);

  const { data, isLoading, isError } = useQuery({
    queryKey: ["appointment", appointmentId],
    queryFn: () => getAppointmentById(appointmentId),
    enabled: !isNaN(appointmentId),
  });

  const statusMutation = useMutation({
    mutationFn: () =>
      partialUpdateAppointment({
        id: appointmentId,
        appointmentStatusId: PAID_STATUS_ID,
      }),
  });

  async function handleSuccess(payment: PaymentResponse) {
    // Update appointment status to "Pagada" ÔÇö fire and forget (non-blocking)
    statusMutation.mutate();
    setCompletedPayment(payment);
  }

  if (isNaN(appointmentId)) {
    return (
      <div className="max-w-lg mx-auto mt-16 text-center">
        <p className="text-red-600 font-semibold">
          No se proporcion├│ un ID de cita v├ílido.
        </p>
      </div>
    );
  }

  if (isLoading) {
    return <LoadingComponent />;
  }

  if (isError || !data?.success || !data.data) {
    return (
      <div className="max-w-lg mx-auto mt-16 text-center">
        <p className="text-red-600 font-semibold">
          No se pudo cargar la informaci├│n de la cita.
        </p>
      </div>
    );
  }

  const appointment = data.data;
  const patientName =
    appointment.patient?.name ?? `Paciente #${appointment.patientId}`;
  const specialtyName = appointment.specialty?.name ?? "Consulta";
  const branchName = appointment.branch?.name ?? "ÔÇö";

  const formattedDate = appointment.appointmentDate
    ? formatDateLong(appointment.appointmentDate)
    : "ÔÇö";

  // Show receipt after successful payment
  if (completedPayment) {
    return (
      <div className="max-w-lg mx-auto py-10 px-4">
        <div className="mb-6 text-center">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-green-100 mb-3">
            <svg
              className="w-8 h-8 text-green-600"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                d="M5 13l4 4L19 7"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-green-800">┬íPago exitoso!</h1>
          <p className="text-gray-500 text-sm mt-1">
            Su cita ha sido confirmada y marcada como pagada.
          </p>
        </div>

        <PaymentReceipt
          branchName={branchName}
          patientName={patientName}
          payment={completedPayment}
          serviceDetail={`${specialtyName} ÔÇö ${formattedDate}`}
        />
      </div>
    );
  }

  return (
    <div className="max-w-lg mx-auto py-10 px-4">
      <h1 className="text-2xl font-bold text-center mb-6">Pago en l├¡nea</h1>

      {/* Payment summary */}
      <div className="rounded-lg border border-gray-200 bg-white p-5 mb-6 shadow-sm">
        <h2 className="text-base font-semibold text-gray-700 mb-3">
          Resumen de la cita
        </h2>
        <dl className="space-y-2 text-sm">
          <div className="flex justify-between">
            <dt className="font-medium text-gray-500">Paciente</dt>
            <dd className="text-gray-800">{patientName}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="font-medium text-gray-500">Especialidad</dt>
            <dd className="text-gray-800">{specialtyName}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="font-medium text-gray-500">Sucursal</dt>
            <dd className="text-gray-800">{branchName}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="font-medium text-gray-500">Fecha</dt>
            <dd className="text-gray-800">{formattedDate}</dd>
          </div>
        </dl>
      </div>

      {/* Card payment form */}
      <div className="rounded-lg border border-gray-200 bg-white p-5 shadow-sm">
        <CardPaymentForm
          amount={appointment.amount}
          appointmentId={appointmentId}
          onSuccess={handleSuccess}
        />
      </div>
    </div>
  );
}

import {
  Button,
  Input,
  Label,
  Modal,
  Spinner,
  TextField,
  toast,
} from "@heroui/react";
import { useCallback, useMemo, useState } from "react";
import { AsyncButton } from "../../components/button/AsyncButton";
import { PaymentResponseColumns } from "../../components/column/PaymentResponseColumns";
import { Icon } from "../../components/icons/Icon";
import { TableServer } from "../../components/table/TableServer";
import { partialUpdateDispense } from "../../services/dispenseService";
import { partialUpdateLabOrder } from "../../services/labOrderService";
import {
  createPayment,
  getPayments,
  getPendingOrders,
} from "../../services/paymentService";
import { usePaymentStore } from "../../stores/usePaymentStore";
import { customStyles } from "../../theme/tableTheme";
import type { PaymentRequest } from "../../types/PaymentResponse";
import type { PendingOrderResponse } from "../../types/PendingOrderResponse";
import { formatDate } from "../../utils/dateFormatter";
import { generateIdempotencyKey } from "../../utils/generateIdempotencyKey";

type PaymentMethodType = "cash" | "card";

interface PaymentFormState {
  paymentMethod: PaymentMethodType;
  amountReceived: string;
  cardLastFourDigits: string;
}

const ORDER_TYPE_LABELS: Record<string, string> = {
  LabOrder: "Laboratorio",
  Dispense: "Farmacia",
};

function formatCurrency(amount: number): string {
  return `Q ${amount.toFixed(2)}`;
}

export function PaymentPage() {
  const { filters, setFilters } = usePaymentStore();

  // Pending orders state
  const [searchTerm, setSearchTerm] = useState("");
  const [pendingOrders, setPendingOrders] = useState<PendingOrderResponse[]>(
    [],
  );
  const [isSearching, setIsSearching] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(
    new Set(),
  );

  // Payment modal state
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [ordersToPayList, setOrdersToPayList] = useState<
    PendingOrderResponse[]
  >([]);
  const [paymentForm, setPaymentForm] = useState<PaymentFormState>({
    paymentMethod: "cash",
    amountReceived: "",
    cardLastFourDigits: "",
  });
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  // Unique key for each order row (used for selection)
  const getOrderKey = useCallback(
    (order: PendingOrderResponse) => `${order.orderType}-${order.orderId}`,
    [],
  );

  // Total for selected orders
  const selectedTotal = useMemo(() => {
    return pendingOrders
      .filter((o) => selectedOrderIds.has(getOrderKey(o)))
      .reduce((sum, o) => sum + o.totalAmount, 0);
  }, [pendingOrders, selectedOrderIds, getOrderKey]);

  // Total for orders in payment modal
  const paymentTotal = useMemo(() => {
    return ordersToPayList.reduce((sum, o) => sum + o.totalAmount, 0);
  }, [ordersToPayList]);

  // Change calculation for cash
  const changeAmount = useMemo(() => {
    const received = parseFloat(paymentForm.amountReceived);
    if (isNaN(received)) return 0;
    return Math.max(0, received - paymentTotal);
  }, [paymentForm.amountReceived, paymentTotal]);

  // Search pending orders
  const handleSearch = useCallback(async () => {
    const term = searchTerm.trim();
    if (!term) {
      toast.danger("Ingrese un DPI o n├║mero de orden para buscar.");
      return;
    }

    setIsSearching(true);
    setHasSearched(true);
    setSelectedOrderIds(new Set());

    try {
      // Determine if search term is a DPI (numeric, 13 digits) or order number
      const isNumericOnly = /^\d+$/.test(term);
      const isDpi = isNumericOnly && term.length >= 8;

      const response = await getPendingOrders(
        isDpi ? term : undefined,
        !isDpi ? term : undefined,
      );

      if (response.success && response.data) {
        setPendingOrders(response.data);
        if (response.data.length === 0) {
          toast.info("No se encontraron ├│rdenes pendientes.");
        }
      } else {
        setPendingOrders([]);
        toast.danger(response.message ?? "Error al buscar ├│rdenes pendientes.");
      }
    } catch {
      setPendingOrders([]);
      toast.danger("Error al buscar ├│rdenes pendientes.");
    } finally {
      setIsSearching(false);
    }
  }, [searchTerm]);

  const handleSearchKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter") {
        e.preventDefault();
        handleSearch();
      }
    },
    [handleSearch],
  );

  // Toggle selection of a single order
  const toggleOrderSelection = useCallback(
    (order: PendingOrderResponse) => {
      const key = getOrderKey(order);
      setSelectedOrderIds((prev) => {
        const next = new Set(prev);
        if (next.has(key)) {
          next.delete(key);
        } else {
          next.add(key);
        }
        return next;
      });
    },
    [getOrderKey],
  );

  // Toggle all orders
  const toggleAllOrders = useCallback(() => {
    if (selectedOrderIds.size === pendingOrders.length) {
      setSelectedOrderIds(new Set());
    } else {
      setSelectedOrderIds(new Set(pendingOrders.map(getOrderKey)));
    }
  }, [selectedOrderIds.size, pendingOrders, getOrderKey]);

  // Open payment modal for a single order
  const handlePaySingle = useCallback((order: PendingOrderResponse) => {
    setOrdersToPayList([order]);
    setPaymentForm({
      paymentMethod: "cash",
      amountReceived: "",
      cardLastFourDigits: "",
    });
    setIsPaymentModalOpen(true);
  }, []);

  // Open payment modal for selected orders
  const handlePaySelected = useCallback(() => {
    const selected = pendingOrders.filter((o) =>
      selectedOrderIds.has(getOrderKey(o)),
    );
    if (selected.length === 0) {
      toast.danger("Seleccione al menos una orden para cobrar.");
      return;
    }
    setOrdersToPayList(selected);
    setPaymentForm({
      paymentMethod: "cash",
      amountReceived: "",
      cardLastFourDigits: "",
    });
    setIsPaymentModalOpen(true);
  }, [pendingOrders, selectedOrderIds, getOrderKey]);

  // Close payment modal
  const closePaymentModal = useCallback(() => {
    if (!isProcessingPayment) {
      setIsPaymentModalOpen(false);
      setOrdersToPayList([]);
    }
  }, [isProcessingPayment]);

  // Validate payment form
  const validatePayment = useCallback((): boolean => {
    if (paymentForm.paymentMethod === "cash") {
      const received = parseFloat(paymentForm.amountReceived);
      if (isNaN(received) || received <= 0) {
        toast.danger("Ingrese el monto recibido.");
        return false;
      }
      if (received < paymentTotal) {
        toast.danger("El monto recibido es menor al total a pagar.");
        return false;
      }
    } else {
      if (!/^\d{4}$/.test(paymentForm.cardLastFourDigits)) {
        toast.danger("Ingrese los ├║ltimos 4 d├¡gitos de la tarjeta.");
        return false;
      }
    }
    return true;
  }, [paymentForm, paymentTotal]);

  // Process payment
  const handleProcessPayment = useCallback(async () => {
    if (!validatePayment()) return;

    setIsProcessingPayment(true);

    try {
      // Process each order individually
      for (const order of ordersToPayList) {
        const idempotencyKey = generateIdempotencyKey();

        const paymentRequest: PaymentRequest = {
          amount: order.totalAmount,
          paymentMethod: paymentForm.paymentMethod === "cash" ? 0 : 1,
          paymentType: order.paymentType,
          paymentStatus: 1,
          paymentDate: new Date().toISOString(),
          idempotencyKey,
          state: 1,
          ...(order.paymentType === 1 ? { labOrderId: order.orderId } : {}),
          ...(order.paymentType === 2 ? { dispenseId: order.orderId } : {}),
          ...(paymentForm.paymentMethod === "cash"
            ? {
                amountReceived: parseFloat(paymentForm.amountReceived),
                changeAmount: Math.max(
                  0,
                  parseFloat(paymentForm.amountReceived) - order.totalAmount,
                ),
              }
            : {
                cardLastFourDigits: paymentForm.cardLastFourDigits,
              }),
        };

        const paymentResponse = await createPayment(paymentRequest);

        if (!paymentResponse.success) {
          toast.danger(
            paymentResponse.message ??
              `Error al procesar pago de orden ${order.orderNumber}.`,
          );
          setIsProcessingPayment(false);
          return;
        }

        // Update order status to Paid (1)
        try {
          if (order.orderType === "LabOrder") {
            await partialUpdateLabOrder({ id: order.orderId, orderStatus: 1 });
          } else if (order.orderType === "Dispense") {
            await partialUpdateDispense({
              id: order.orderId,
              dispenseStatus: 1,
            });
          }
        } catch {
          toast.warning(
            `Pago registrado pero no se pudo actualizar el estado de la orden ${order.orderNumber}.`,
          );
        }
      }

      toast.success(
        ordersToPayList.length === 1
          ? "Pago procesado exitosamente."
          : `${ordersToPayList.length} pagos procesados exitosamente.`,
      );

      // Remove paid orders from the list
      const paidKeys = new Set(ordersToPayList.map(getOrderKey));
      setPendingOrders((prev) =>
        prev.filter((o) => !paidKeys.has(getOrderKey(o))),
      );
      setSelectedOrderIds((prev) => {
        const next = new Set(prev);
        for (const key of paidKeys) next.delete(key);
        return next;
      });

      setIsPaymentModalOpen(false);
      setOrdersToPayList([]);
    } catch {
      toast.danger("Error inesperado al procesar el pago.");
    } finally {
      setIsProcessingPayment(false);
    }
  }, [ordersToPayList, paymentForm, validatePayment, getOrderKey]);

  // Payments table query
  const queryFn = useCallback(
    async (filters: string, page: number, pageSize: number) => {
      return getPayments({
        pageNumber: page,
        pageSize,
        filters,
        include: "",
        includeTotal: false,
      });
    },
    [],
  );

  return (
    <div>
      <h1 className="text-2xl font-bold text-center mb-4">Pagos</h1>

      {/* Pending Orders Section */}
      <div className="mb-8 rounded-xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-700 dark:bg-gray-900">
        <h2 className="text-xl font-bold text-gray-800 dark:text-gray-100 mb-4 flex items-center gap-2">
          <Icon color="#0A4FA6" name="bi bi-clock-history" size={22} />
          <span>├ôrdenes Pendientes de Pago</span>
        </h2>

        {/* Search bar */}
        <div className="flex flex-wrap items-end gap-3 mb-4">
          <div className="flex-1 min-w-[250px]">
            <TextField name="pendingSearch">
              <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                Buscar por DPI del paciente o n├║mero de orden
              </Label>
              <Input
                placeholder="Ingrese DPI o n├║mero de orden..."
                type="search"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                onKeyDown={handleSearchKeyDown}
              />
            </TextField>
          </div>
          <Button
            className="px-6 py-2"
            isDisabled={isSearching}
            variant="primary"
            onPress={handleSearch}
          >
            {isSearching ? (
              <Spinner color="current" size="sm" />
            ) : (
              <Icon color="white" name="bi bi-search" size={16} />
            )}
            <span className="ml-1">Buscar</span>
          </Button>
        </div>

        {/* Results */}
        {isSearching ? (
          <div className="flex justify-center py-8">
            <Spinner color="accent" size="lg" />
          </div>
        ) : null}

        {!isSearching && hasSearched && pendingOrders.length === 0 ? (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            <Icon color="#9CA3AF" name="bi bi-inbox" size={40} />
            <p className="mt-2">No se encontraron ├│rdenes pendientes.</p>
          </div>
        ) : null}

        {!isSearching && pendingOrders.length > 0 && (
          <>
            {/* Selection actions */}
            <div className="flex flex-wrap items-center justify-between gap-3 mb-3">
              <div className="flex items-center gap-3">
                <span className="text-sm text-gray-600 dark:text-gray-400">
                  {selectedOrderIds.size} de {pendingOrders.length}{" "}
                  seleccionadas
                </span>
                {selectedOrderIds.size > 0 && (
                  <span className="text-sm font-semibold text-blue-700 dark:text-blue-400">
                    Total seleccionado: {formatCurrency(selectedTotal)}
                  </span>
                )}
              </div>
              {selectedOrderIds.size > 1 && (
                <Button size="sm" variant="primary" onPress={handlePaySelected}>
                  <Icon color="white" name="bi bi-cash-stack" size={16} />
                  <span className="ml-1">
                    Cobrar Seleccionados ({formatCurrency(selectedTotal)})
                  </span>
                </Button>
              )}
            </div>

            {/* Pending orders table */}
            <div className="overflow-x-auto rounded-lg border border-gray-200 dark:border-gray-700">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-blue-50 dark:bg-blue-900/20 text-left">
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300">
                      <input
                        aria-label="Seleccionar todas las ├│rdenes"
                        checked={
                          selectedOrderIds.size === pendingOrders.length &&
                          pendingOrders.length > 0
                        }
                        className="rounded border-gray-300"
                        type="checkbox"
                        onChange={toggleAllOrders}
                      />
                    </th>
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300 uppercase text-xs tracking-wide">
                      Tipo
                    </th>
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300 uppercase text-xs tracking-wide">
                      N├║mero
                    </th>
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300 uppercase text-xs tracking-wide">
                      Paciente
                    </th>
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300 uppercase text-xs tracking-wide">
                      Fecha
                    </th>
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300 uppercase text-xs tracking-wide text-center">
                      ├ìtems
                    </th>
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300 uppercase text-xs tracking-wide text-right">
                      Total
                    </th>
                    <th className="px-3 py-3 font-semibold text-blue-800 dark:text-blue-300 uppercase text-xs tracking-wide text-center">
                      Acci├│n
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {pendingOrders.map((order) => {
                    const key = getOrderKey(order);
                    const isSelected = selectedOrderIds.has(key);
                    return (
                      <tr
                        key={key}
                        className={`border-b border-gray-100 dark:border-gray-800 transition-colors ${
                          isSelected
                            ? "bg-blue-50 dark:bg-blue-900/10"
                            : "hover:bg-gray-50 dark:hover:bg-gray-800/50"
                        }`}
                      >
                        <td className="px-3 py-3">
                          <input
                            aria-label={`Seleccionar orden ${order.orderNumber}`}
                            checked={isSelected}
                            className="rounded border-gray-300"
                            type="checkbox"
                            onChange={() => toggleOrderSelection(order)}
                          />
                        </td>
                        <td className="px-3 py-3">
                          <span
                            className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
                              order.orderType === "LabOrder"
                                ? "bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300"
                                : "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300"
                            }`}
                          >
                            {ORDER_TYPE_LABELS[order.orderType] ??
                              order.orderType}
                          </span>
                        </td>
                        <td className="px-3 py-3 font-mono text-xs">
                          {order.orderNumber}
                        </td>
                        <td className="px-3 py-3">{order.patientName}</td>
                        <td className="px-3 py-3 text-gray-600 dark:text-gray-400">
                          {formatDate(order.createdAt)}
                        </td>
                        <td className="px-3 py-3 text-center">
                          {order.itemCount}
                        </td>
                        <td className="px-3 py-3 text-right font-semibold">
                          {formatCurrency(order.totalAmount)}
                        </td>
                        <td className="px-3 py-3 text-center">
                          <Button
                            size="sm"
                            variant="ghost"
                            onPress={() => handlePaySingle(order)}
                          >
                            <Icon color="#0A4FA6" name="bi bi-cash" size={14} />
                            <span className="ml-1">Cobrar</span>
                          </Button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>

      {/* Existing Payments Table */}
      <TableServer
        hasFilters
        columns={PaymentResponseColumns}
        filters={filters}
        queryFn={queryFn}
        queryKey="payments"
        setFilters={setFilters}
        styles={customStyles}
        text="pagos"
        title="Pagos"
      />

      {/* Payment Modal */}
      <Modal isOpen={isPaymentModalOpen} onOpenChange={closePaymentModal}>
        <Modal.Backdrop>
          <Modal.Container>
            <Modal.Dialog className="max-w-lg w-full">
              <Modal.CloseTrigger />
              <Modal.Header>
                <Modal.Heading>Procesar Pago</Modal.Heading>
              </Modal.Header>
              <Modal.Body>
                <div className="space-y-5 p-2">
                  {/* Order summary */}
                  <div className="rounded-lg bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 p-4">
                    <p className="text-sm font-medium text-blue-700 dark:text-blue-300 mb-2">
                      {ordersToPayList.length === 1
                        ? "Orden a cobrar"
                        : `${ordersToPayList.length} ├│rdenes a cobrar`}
                    </p>
                    {ordersToPayList.map((order) => (
                      <div
                        key={getOrderKey(order)}
                        className="flex justify-between items-center text-sm py-1 border-b border-blue-100 dark:border-blue-800 last:border-0"
                      >
                        <span className="text-gray-700 dark:text-gray-300">
                          {ORDER_TYPE_LABELS[order.orderType] ??
                            order.orderType}{" "}
                          ÔÇö {order.orderNumber}
                        </span>
                        <span className="font-semibold text-gray-900 dark:text-gray-100">
                          {formatCurrency(order.totalAmount)}
                        </span>
                      </div>
                    ))}
                    <div className="flex justify-between items-center mt-3 pt-2 border-t border-blue-300 dark:border-blue-700">
                      <span className="text-base font-bold text-blue-900 dark:text-blue-100">
                        Total a pagar
                      </span>
                      <span className="text-2xl font-bold text-blue-900 dark:text-blue-100">
                        {formatCurrency(paymentTotal)}
                      </span>
                    </div>
                  </div>

                  {/* Payment method selector */}
                  <div>
                    <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      M├®todo de pago
                    </p>
                    <div className="flex gap-3">
                      <button
                        className={`flex-1 rounded-lg border-2 p-3 text-center transition-colors ${
                          paymentForm.paymentMethod === "cash"
                            ? "border-blue-500 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300"
                            : "border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400 hover:border-gray-300"
                        }`}
                        type="button"
                        onClick={() =>
                          setPaymentForm((prev) => ({
                            ...prev,
                            paymentMethod: "cash",
                          }))
                        }
                      >
                        <Icon
                          color={
                            paymentForm.paymentMethod === "cash"
                              ? "#0A4FA6"
                              : "#9CA3AF"
                          }
                          name="bi bi-cash"
                          size={20}
                        />
                        <p className="text-sm font-medium mt-1">Efectivo</p>
                      </button>
                      <button
                        className={`flex-1 rounded-lg border-2 p-3 text-center transition-colors ${
                          paymentForm.paymentMethod === "card"
                            ? "border-blue-500 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300"
                            : "border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400 hover:border-gray-300"
                        }`}
                        type="button"
                        onClick={() =>
                          setPaymentForm((prev) => ({
                            ...prev,
                            paymentMethod: "card",
                          }))
                        }
                      >
                        <Icon
                          color={
                            paymentForm.paymentMethod === "card"
                              ? "#0A4FA6"
                              : "#9CA3AF"
                          }
                          name="bi bi-credit-card"
                          size={20}
                        />
                        <p className="text-sm font-medium mt-1">Tarjeta</p>
                      </button>
                    </div>
                  </div>

                  {/* Cash payment fields */}
                  {paymentForm.paymentMethod === "cash" && (
                    <div className="space-y-4">
                      <TextField name="amountReceived">
                        <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                          Monto recibido (GTQ)
                        </Label>
                        <Input
                          min={0}
                          placeholder="0.00"
                          step="0.01"
                          type="number"
                          value={paymentForm.amountReceived}
                          onChange={(e) =>
                            setPaymentForm((prev) => ({
                              ...prev,
                              amountReceived: e.target.value,
                            }))
                          }
                        />
                      </TextField>

                      {paymentForm.amountReceived &&
                      parseFloat(paymentForm.amountReceived) >= paymentTotal ? (
                        <div className="rounded-lg bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 p-3 flex justify-between items-center">
                          <span className="text-sm font-medium text-green-700 dark:text-green-300">
                            Cambio
                          </span>
                          <span className="text-xl font-bold text-green-800 dark:text-green-200">
                            {formatCurrency(changeAmount)}
                          </span>
                        </div>
                      ) : null}

                      {paymentForm.amountReceived &&
                      parseFloat(paymentForm.amountReceived) > 0 &&
                      parseFloat(paymentForm.amountReceived) < paymentTotal ? (
                        <div className="rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-3">
                          <span className="text-sm text-red-700 dark:text-red-300">
                            El monto recibido es insuficiente. Faltan{" "}
                            {formatCurrency(
                              paymentTotal -
                                parseFloat(paymentForm.amountReceived),
                            )}
                            .
                          </span>
                        </div>
                      ) : null}
                    </div>
                  )}

                  {/* Card payment fields */}
                  {paymentForm.paymentMethod === "card" && (
                    <TextField name="cardLastFour">
                      <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                        ├Ültimos 4 d├¡gitos de la tarjeta
                      </Label>
                      <Input
                        inputMode="numeric"
                        maxLength={4}
                        placeholder="1234"
                        type="text"
                        value={paymentForm.cardLastFourDigits}
                        onChange={(e) =>
                          setPaymentForm((prev) => ({
                            ...prev,
                            cardLastFourDigits: e.target.value
                              .replace(/\D/g, "")
                              .slice(0, 4),
                          }))
                        }
                      />
                    </TextField>
                  )}
                </div>
              </Modal.Body>
              <Modal.Footer>
                <div className="flex gap-2 justify-end w-full">
                  <Button
                    isDisabled={isProcessingPayment}
                    variant="secondary"
                    onPress={closePaymentModal}
                  >
                    Cancelar
                  </Button>
                  <AsyncButton
                    isLoading={isProcessingPayment}
                    variant="primary"
                    onPress={handleProcessPayment}
                  >
                    Confirmar Pago ({formatCurrency(paymentTotal)})
                  </AsyncButton>
                </div>
              </Modal.Footer>
            </Modal.Dialog>
          </Modal.Container>
        </Modal.Backdrop>
      </Modal>
    </div>
  );
}

