          <>
            <div
              className={`flex flex-col gap-3 transition-opacity ${isFetching ? "opacity-60" : "opacity-100"}`}
            >
              {appointments.map((appt) => (
                <AppointmentRow
                  key={appt.id}
                  appt={appt}
                  onCancel={handleCancelRequest}
                />
              ))}
            </div>

            {/* Pagination */}
            <div className="mt-6 flex items-center justify-between">
              <button
                className="flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-40 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200"
                disabled={!hasPrev || isFetching}
                type="button"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
              >
                <i className="bi bi-chevron-left" />
                Anterior
              </button>

              <span className="text-sm text-gray-500 dark:text-gray-400">
                P├ígina {page}
              </span>

              <button
                className="flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-40 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200"
                disabled={!hasMore || isFetching}
                type="button"
                onClick={() => setPage((p) => p + 1)}
              >
                Siguiente
                <i className="bi bi-chevron-right" />
              </button>
            </div>
          </>
        )}
      </div>

      {/* Cancel confirmation modal */}
      <Modal isOpen={!!cancelTarget} onOpenChange={() => setCancelTarget(null)}>
        <Modal.Backdrop>
          <Modal.Container>
            <Modal.Dialog className="max-w-md w-full">
              <Modal.CloseTrigger />
              <Modal.Header>
                <Modal.Heading>Cancelar Cita</Modal.Heading>
              </Modal.Header>
              <Modal.Body>
                <div className="flex items-start gap-4 p-4">
                  <i className="bi bi-exclamation-triangle text-red-500 text-3xl shrink-0" />
                  <div>
                    <p className="text-sm text-gray-700 dark:text-gray-300">
                      ┬┐Est├í seguro que desea cancelar esta cita?
                    </p>
                    <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                      Recibir├í un correo de confirmaci├│n y los fondos ser├ín
                      reintegrados seg├║n los t├®rminos del servicio.
                    </p>
                  </div>
                </div>
              </Modal.Body>
              <Modal.Footer>
                <div className="flex gap-2 justify-end w-full">
                  <Button
                    isDisabled={cancelMutation.isPending}
                    variant="secondary"
                    onPress={() => setCancelTarget(null)}
                  >
                    No, mantener cita
                  </Button>
                  <Button
                    isPending={cancelMutation.isPending}
                    variant="danger"
                    onPress={handleCancelConfirm}
                  >
                    S├¡, cancelar cita
                  </Button>
                </div>
              </Modal.Footer>
            </Modal.Dialog>
          </Modal.Container>
        </Modal.Backdrop>
      </Modal>
    </section>
  );
}

