import { useCallback, useState, type FormEvent } from "react";
import { Link, useNavigate } from "react-router";
import { z } from "zod";

import { LogoHIS } from "../../components/brand/LogoHIS";
import { nameRoutes } from "../../configs/constants";
import { loginPatient } from "../../services/patientPortalService";
import { usePatientAuthStore } from "../../stores/usePatientAuthStore";
import { getRoleFromToken } from "../../utils/jwt";

// ÔöÇÔöÇ Zod schema ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
const loginSchema = z.object({
  userName: z.string().min(1, "El nombre de usuario es requerido"),
  password: z.string().min(1, "La contrase├▒a es requerida"),
});

type LoginForm = z.infer<typeof loginSchema>;

const MAX_ATTEMPTS = 5;
const LOCKOUT_MINUTES = 15;

// ÔöÇÔöÇ Page ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
export function PortalLoginPage() {
  const navigate = useNavigate();
  const { signInPatient } = usePatientAuthStore();

  const [form, setForm] = useState<LoginForm>({ userName: "", password: "" });
  const [fieldErrors, setFieldErrors] = useState<
    Partial<Record<keyof LoginForm, string>>
  >({});
  const [apiError, setApiError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockedUntil, setLockedUntil] = useState<Date | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  const isLocked = lockedUntil !== null && new Date() < lockedUntil;

  const handleChange = useCallback(
    (field: keyof LoginForm) => (e: React.ChangeEvent<HTMLInputElement>) => {
      setForm((prev) => ({ ...prev, [field]: e.target.value }));
      setFieldErrors((prev) => ({ ...prev, [field]: undefined }));
      setApiError("");
    },
    [],
  );

  const handleSubmit = useCallback(
    async (e: FormEvent) => {
      e.preventDefault();

      if (isLocked) return;

      // Client-side validation
      const result = loginSchema.safeParse(form);
      if (!result.success) {
        const errs: Partial<Record<keyof LoginForm, string>> = {};
        for (const issue of result.error.issues) {
          const key = issue.path[0] as keyof LoginForm;
          errs[key] = issue.message;
        }
        setFieldErrors(errs);
        return;
      }

      setIsLoading(true);
      setApiError("");

      try {
        const response = await loginPatient({
          userName: form.userName,
          password: form.password,
        });

        if (response.success) {
          const {
            token,
            userId: responseUserId,
            name: responseName,
            email: responseEmail,
            timezoneIanaId: responseTz,
          } = response.data;

          // Only patients can log in via the portal
          const roleName = getRoleFromToken(token);
          if (roleName !== "Paciente") {
            setApiError(
              "Este acceso es exclusivo para pacientes. Si es personal del hospital, use el panel administrativo.",
            );
            return;
          }

          signInPatient({
            isLoggedIn: true,
            token,
            userId: responseUserId,
            name: responseName,
            email: responseEmail,
            userName: form.userName,
            timezoneIanaId: responseTz || "America/Guatemala",
          });

          navigate(nameRoutes.portalDashboard);
        } else {
          const newAttempts = failedAttempts + 1;
          setFailedAttempts(newAttempts);

          if (newAttempts >= MAX_ATTEMPTS) {
            const lockout = new Date(Date.now() + LOCKOUT_MINUTES * 60 * 1000);
            setLockedUntil(lockout);
            setApiError(
              `Cuenta bloqueada temporalmente. Intente de nuevo en ${LOCKOUT_MINUTES} minutos.`,
            );
          } else {
            const remaining = MAX_ATTEMPTS - newAttempts;
            setApiError(
              `Usuario o contrase├▒a incorrectos. Intentos restantes: ${remaining}.`,
            );
          }
        }
      } catch {
        setApiError(
          "No se pudo conectar con el servidor. Intente de nuevo m├ís tarde.",
        );
      } finally {
        setIsLoading(false);
      }
    },
    [form, isLocked, failedAttempts, signInPatient, navigate],
  );

  return (
    <section className="flex flex-col items-center justify-center min-h-[calc(100vh-140px)] px-4 py-12">
      <div className="w-full max-w-md">
        {/* Card */}
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 p-8">
          {/* Logo */}
          <div className="flex justify-center mb-6">
            <LogoHIS className="h-14 w-auto" height="auto" width="160px" />
          </div>

          <h1 className="text-2xl font-bold text-center text-gray-800 dark:text-gray-100 mb-1">
            Iniciar Sesi├│n
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 text-center mb-6">
            Acceda a su cuenta del portal de pacientes
          </p>

          {/* Error banner */}
          {apiError ? (
            <div
              className={`mb-4 p-4 rounded-xl text-sm flex items-start gap-2 ${
                isLocked
                  ? "bg-red-50 border border-red-300 text-red-800 dark:bg-red-900/20 dark:border-red-700 dark:text-red-300"
                  : "bg-amber-50 border border-amber-300 text-amber-800 dark:bg-amber-900/20 dark:border-amber-700 dark:text-amber-300"
              }`}
            >
              <i
                className={`bi ${isLocked ? "bi-lock-fill" : "bi-exclamation-triangle-fill"} mt-0.5 shrink-0`}
              />
              <span>{apiError}</span>
            </div>
          ) : null}

          <form
            noValidate
            className="flex flex-col gap-4"
            onSubmit={handleSubmit}
          >
            {/* Username */}
            <div className="flex flex-col gap-1">
              <label
