import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { useNavigate } from "react-router";
import { ReceptionSearch } from "../../components/reception/ReceptionSearch";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import {
  getAppointments,
  partialUpdateAppointment,
} from "../../services/appointmentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";

const statusColors: Record<string, string> = {
  Pagada: "bg-green-100 text-green-800 border-green-300",
  Pendiente: "bg-yellow-100 text-yellow-800 border-yellow-300",
  Cancelada: "bg-red-100 text-red-800 border-red-300",
  "En curso": "bg-blue-100 text-blue-800 border-blue-300",
  Completada: "bg-gray-100 text-gray-800 border-gray-300",
  "No asisti├│": "bg-orange-100 text-orange-800 border-orange-300",
  "Paciente presente": "bg-purple-100 text-purple-800 border-purple-300",
};

export function ReceptionPage() {
  const [searchQuery, setSearchQuery] = useState("");
  const [searchType, setSearchType] = useState<"dpi" | "id">("dpi");
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ["reception-search", searchQuery, searchType],
    queryFn: () => {
      if (!searchQuery)
        return Promise.resolve({
          success: true as const,
          data: [],
          message: "",
          totalResults: 0,
        });
      const filter =
        searchType === "dpi"
          ? `Patient.IdentificationDocument:eq:${searchQuery}`
          : `Id:eq:${searchQuery}`;
      return getAppointments({
        pageNumber: 1,
        pageSize: 20,
        filters: `${filter} AND State:eq:1`,
        include: "Specialty,Branch,AppointmentStatus,Patient",
        includeTotal: false,
      });
    },
    enabled: !!searchQuery,
  });

  const registerArrivalMutation = useMutation({
    mutationFn: async (appointment: AppointmentResponse) => {
      return partialUpdateAppointment({
        id: appointment.id,
        arrivalTime: new Date().toISOString(),
      });
    },
    onSuccess: (_data, appointment) => {
      const patientName =
        appointment.patient?.name ?? `Paciente #${appointment.patientId}`;
      if (appointment.priority > 0) {
        toast.success(
          `Paciente ${patientName} registrado con prioridad de EMERGENCIA. El paciente debe pasar directamente a toma de signos vitales.`,
        );
      } else {
        toast.success(
          `La llegada del paciente ${patientName} ha sido registrada exitosamente. El paciente debe pasar a la sala de espera.`,
        );
      }
      queryClient.invalidateQueries({ queryKey: ["reception-search"] });
    },
    onError: () => toast.danger("Error al registrar la llegada"),
  });

  const appointments = data?.success ? data.data : [];

  return (
    <div className="max-w-5xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-2">
        Recepci├│n y Verificaci├│n de Citas
      </h1>
      <p className="text-gray-500 text-sm mb-6">
        Busque al paciente por DPI o n├║mero de cita para verificar y registrar
        su llegada.
      </p>

      {/* Buscador */}
      <ReceptionSearch
        onSearch={(query, type) => {
          setSearchType(type);
          setSearchQuery(query);
        }}
      />

      {/* Resultados */}
      {isLoading ? <LoadingComponent /> : null}

      {!isLoading && searchQuery && appointments.length === 0 ? (
        <div className="text-center py-12 text-gray-400">
          <i className="bi bi-search text-4xl block mb-3" />
          <p className="text-gray-600 dark:text-gray-300">
            No se encontraron citas activas para el paciente.
          </p>
          <p className="text-sm mt-1">
            El paciente no se encuentra registrado en el sistema o no tiene
            citas activas. Verifique los datos e intente nuevamente.
          </p>
          <div className="flex gap-3 justify-center mt-4">
            <Button
              variant="primary"
              onPress={() => navigate("/appointment/create")}
            >
              <i className="bi bi-plus-circle mr-2" /> Nueva Cita (Walk-in)
            </Button>
            <Button variant="secondary" onPress={() => navigate("/register")}>
              <i className="bi bi-person-plus mr-2" /> Registrar Paciente
            </Button>
          </div>
        </div>
      ) : null}

      {appointments.length > 0 && (
        <div className="space-y-4">
          {appointments.map((appointment) => {
            const statusName = appointment.appointmentStatus?.name ?? "";
            const colorClass =
              statusColors[statusName] ??
              "bg-gray-100 text-gray-800 border-gray-300";
            const isPaid = statusName === "Pagada";
            const isPending = statusName === "Pendiente";
            const isCancelled = statusName === "Cancelada";

            return (
              <div
                key={appointment.id}
                className={`border rounded-xl p-5 ${colorClass}`}
              >
                <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <h3 className="text-lg font-bold">
                        {appointment.patient?.name ??
                          `Paciente #${appointment.patientId}`}
                      </h3>
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-semibold border ${colorClass}`}
                      >
                        {statusName}
                      </span>
                      {appointment.priority > 0 && (
                        <span className="px-2 py-1 rounded-full text-xs font-bold bg-red-600 text-white">
                          ­ƒÜ¿ EMERGENCIA
                        </span>
                      )}
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-sm">
                      <div>
                        <span className="font-semibold">Cita #:</span>{" "}
                        {appointment.id}
                      </div>
                      <div>
                        <span className="font-semibold">Especialidad:</span>{" "}
                        {appointment.specialty?.name ?? "ÔÇö"}
                      </div>
                      <div>
                        <span className="font-semibold">Sucursal:</span>{" "}
                        {appointment.branch?.name ?? "ÔÇö"}
                      </div>
                      <div>
                        <span className="font-semibold">Fecha:</span>{" "}
                        {appointment.appointmentDate}
                      </div>
                      <div className="col-span-2 md:col-span-4">
                        <span className="font-semibold">Motivo:</span>{" "}
                        {appointment.reason}
                      </div>
                      {appointment.arrivalTime ? (
                        <div>
                          <span className="font-semibold">Llegada:</span>{" "}
                          {appointment.arrivalTime}
                        </div>
                      ) : null}
                    </div>
                  </div>

                  <div className="flex flex-col gap-2 min-w-[180px]">
                    {isPaid && !appointment.arrivalTime ? (
                      <Button
                        isDisabled={registerArrivalMutation.isPending}
                        variant="primary"
                        onPress={() =>
                          registerArrivalMutation.mutate(appointment)
                        }
                      >
                        <i className="bi bi-person-check mr-2" />
                        Registrar Llegada
                      </Button>
                    ) : null}
                    {isPaid ? (
                      <Button
                        variant="secondary"
                        onPress={() =>
                          navigate(
                            `/appointment/reassign?appointmentId=${appointment.id}`,
                          )
                        }
                      >
                        <i className="bi bi-person-badge mr-2" />
                        Reasignar M├®dico
                      </Button>
                    ) : null}
                    {isPaid && appointment.arrivalTime ? (
                      <div className="text-green-700 font-semibold text-sm text-center p-2 bg-green-50 rounded-lg border border-green-200">
                        Ô£à Llegada registrada
                      </div>
                    ) : null}
                    {isPending ? (
                      <>
                        <div className="text-yellow-700 text-xs text-center p-2 bg-yellow-50 rounded-lg border border-yellow-200">
                          La cita del paciente tiene estado &apos;Pendiente de
                          pago&apos;. Debe realizar el pago en caja antes de ser
                          atendido.
                        </div>
                        <Button
                          variant="primary"
                          onPress={() =>
                            navigate(
                              `/payment/create?appointmentId=${appointment.id}`,
                            )
                          }
                        >
                          <i className="bi bi-cash-coin mr-2" />
                          Ir a Caja
                        </Button>
                      </>
                    ) : null}
                    {isCancelled ? (
                      <>
                        <div className="text-red-700 text-xs text-center p-2 bg-red-50 rounded-lg border border-red-200">
                          La cita fue cancelada. El paciente debe agendar una
                          nueva cita.
                        </div>
                        <Button
                          variant="secondary"
                          onPress={() => navigate("/appointment/create")}
                        >
                          <i className="bi bi-calendar-plus mr-2" />
                          Nueva Cita
                        </Button>
                      </>
                    ) : null}
                    {appointment.priority > 0 && (
                      <Button
                        variant="danger"
                        onPress={() =>
                          navigate(
                            `/vital-sign/create?appointmentId=${appointment.id}`,
                          )
                        }
                      >
                        <i className="bi bi-heart-pulse mr-2" />
                        Signos Vitales (Urgente)
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { toast } from "@heroui/react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate, useSearchParams } from "react-router";
import { VitalSignForm } from "../../components/form/VitalSignForm";
import { BlockedWithoutContext } from "../../components/shared/BlockedWithoutContext";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import {
  createVitalSign,
  getVitalSignByAppointment,
} from "../../services/vitalSignService";
import type { VitalSignRequest } from "../../types/VitalSignResponse";

export function CreateVitalSignPage() {
  const { userId } = useAuth();
  const [searchParams] = useSearchParams();

  const appointmentIdParam = searchParams.get("appointmentId");
  const nurseIdParam = searchParams.get("nurseId");
  const patientNameParam = searchParams.get("patientName");

  // ÔöÇÔöÇ Guard: no appointmentId ÔåÆ blocked ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (!appointmentIdParam) {
    return (
      <BlockedWithoutContext
        backLabel="Ir al Panel de Signos Vitales"
        backRoute={nameRoutes.nurseDashboard}
        icon="bi-heart-pulse"
        message="No puedes registrar signos vitales sin que provenga de una cita m├®dica activa. Los signos vitales solo pueden registrarse desde el panel del rol interino."
        title="Acceso no permitido"
      />
    );
  }

  return (
    <CreateVitalSignGuard
      appointmentId={Number(appointmentIdParam)}
      nurseId={nurseIdParam ? Number(nurseIdParam) : (userId ?? 0)}
      patientName={patientNameParam ?? undefined}
    />
  );
}

function CreateVitalSignGuard({
  appointmentId,
  nurseId,
  patientName,
}: {
  readonly appointmentId: number;
  readonly nurseId: number;
  readonly patientName?: string;
}) {
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const { data: vitalData, isLoading } = useQuery({
    queryKey: ["vitals-check", appointmentId],
    queryFn: () => getVitalSignByAppointment(appointmentId),
    staleTime: 0,
  });

  if (isLoading) return <LoadingComponent />;

  const alreadyHasVitals = vitalData?.success && vitalData.data.length > 0;

  if (alreadyHasVitals) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6 p-8 text-center">
        <i className="bi bi-check-circle text-6xl text-green-400" />
        <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
          Signos vitales ya registrados
        </h1>
        <p className="text-gray-500 dark:text-gray-400 max-w-md">
          Esta cita ya tiene signos vitales registrados. No es posible
          registrarlos nuevamente.
        </p>
        <button
          className="flex items-center gap-2 rounded-xl bg-blue-600 px-6 py-3 font-bold text-white hover:bg-blue-700 transition-colors"
          type="button"
          onClick={() => navigate(nameRoutes.nurseDashboard)}
        >
          <i className="bi bi-arrow-left" />
          Volver al Panel
        </button>
      </div>
    );
  }

  const initialData: VitalSignRequest = {
    appointmentId,
    nurseId,
    bloodPressureSystolic: null,
    bloodPressureDiastolic: null,
    temperature: null,
    weight: null,
    height: null,
    heartRate: null,
    isEmergency: false,
    state: 1,
  };

  return (
    <VitalSignForm
      fromNurseDashboard
      initialForm={initialData}
      patientName={patientName}
      type="create"
      onSubmit={async (form) => {
        const response = await createVitalSign(form);
        if (response.success) {
          const name = patientName ?? "Paciente";
          if (form.isEmergency) {
            toast.success(
              `Signos vitales de emergencia registrados para paciente ${name}. El paciente debe pasar directamente a consulta m├®dica.`,
            );
          } else {
            toast.success(
              `Signos vitales del paciente ${name} registrados correctamente. El paciente puede regresar a la sala de espera.`,
            );
          }
          await queryClient.invalidateQueries({ queryKey: ["vital-signs"] });
          await queryClient.invalidateQueries({
            queryKey: ["nurse-appointments"],
          });
          navigate(nameRoutes.nurseDashboard);
        } else {
          toast.danger(response.message);
        }
        return response;
      }}
    />
  );
}

