import { PortalPaymentPage } from "../pages/portal/PortalPaymentPage";
import { PortalRegisterPage } from "../pages/portal/PortalRegisterPage";
import { ProfilePage } from "../pages/portal/ProfilePage";
import { usePatientAuthStore } from "../stores/usePatientAuthStore";
import ProtectedPatient from "./middlewares/ProtectedPatient";

// Redirect already-logged-in patients away from login/register
function GuestOnlyRoute({ children }: { readonly children: React.ReactNode }) {
  const { isLoggedIn } = usePatientAuthStore();
  return isLoggedIn ? (
    <Navigate replace to={nameRoutes.portalDashboard} />
  ) : (
    <>{children}</>
  );
}

export const PortalRoutes: RouteObject[] = [
  // Rutas p├║blicas del portal
  {
    index: true,
    element: <PortalPage />,
  },
  {
    path: "login",
    element: (
      <GuestOnlyRoute>
        <PortalLoginPage />
      </GuestOnlyRoute>
    ),
  },
  {
    path: "register",
    element: (
      <GuestOnlyRoute>
        <PortalRegisterPage />
      </GuestOnlyRoute>
    ),
  },
  {
    path: "forgot-password",
    element: <PortalForgotPasswordPage />,
  },
  {
    path: "reset-password",
    element: <PortalResetPasswordPage />,
  },
  // Rutas protegidas del portal (requieren autenticaci├│n de paciente)
  {
    element: <ProtectedPatient />,
    children: [
      {
        path: "dashboard",
        element: <PatientDashboardPage />,
      },
      {
        path: "book",
        element: <BookAppointmentPage />,
      },
      {
        path: "book/pay",
        element: <PortalPaymentPage />,
      },
      {
        path: "book/confirm",
        element: <ConfirmationPage />,
      },
      {
        path: "appointments",
        element: <MyAppointmentsPage />,
      },
      {
        path: "profile",
        element: <ProfilePage />,
      },
      {
        path: "change-password",
        element: <PortalChangePasswordPage />,
      },
    ],
  },
];

/**
 * PublicOnly ÔÇö permite acceso sin autenticaci├│n.
 * Usado para el portal p├║blico, registro y recuperaci├│n de contrase├▒a.
 */
import type { ReactNode } from "react";

interface PublicOnlyProps {
  readonly children: ReactNode;
}

function PublicOnly({ children }: PublicOnlyProps) {
  return <>{children}</>;
}

export default PublicOnly;
